window.__D("text/zohar-hebrew-translation/c019",{"p":[[9522011749,"<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר רַבִּי יוֹסֵי, נִפְתַּח בְּעִדּוּנִים (במלאכים ובזמנים) וְנֹאמַר דִּבְרֵי תוֹרָה. פָּתַח רַבִּי יוֹסֵי בְּדִבְרֵי קְרִיאַת שְׁמַע וְאָמַר, כָּתוּב (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וְכָתוּב (שם כז) שְׁמַע יִשְׂרָאֵל הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם. וְכָתוּב (שם ט) שְׁמַע יִשְׂרָאֵל אַתָּה עֹבֵר הַיּוֹם אֶת הַיַּרְדֵּן. כָּל הַשְּׁמַע שְׁמַע הַלָּלוּ שֶׁאָמַר מֹשֶׁה לְשֵׁם מָה, שֶׁהֲרֵי שְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד הוּא נָאֶה, (שהרילדרשההואבא) וְהָאֲחֵרִים הַלָּלוּ לָמָּה?</p>\n<p>אֶלָּא כֻּלָּם בָּאִים לִדְרָשָׁה. שְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד וַדַּאי שֶׁזֶּה בָּא לִדָּרֵשׁ, וְכָאן רָמוּז וְנִרְאֶה הַיִּחוּד שֶׁל הַחָכְמָה הָעֶלְיוֹנָה. שְׁמַע - ע' הִיא מֵהָאוֹתִיּוֹת הַגְּדוֹלוֹת, לָמָּה? אֶלָּא רֶמֶז הוּא רוֹמֵז בִּכְלָל אֶחָד, לִכְלֹל מַעְלָה וּמַטָּה כְּאֶחָד בְּיִחוּד אֶחָד. שְׁמַע - שֵׁם ע'. כָּאן נִכְלָל הַשֵּׁם הַזֶּה בְּאוֹתָם שִׁבְעִים שֵׁמוֹת עֶלְיוֹנִים לְהַכְלִילָם, שֶׁהֲרֵי הַשֵּׁם מִתְבָּרֵךְ מֵהֶם וְנִכְלָל בָּהֶם, וְצָרִיךְ לְהַכְלִילָם כְּאֶחָד בְּיִחוּד אֶחָד, וְלָשִׂים רְצוֹנוֹ בָהֶם.</p>\n<p>שֶׁהֲרֵי וַדַּאי שִׁבְעִים שֵׁמוֹת הֵם בְּסוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, וּמֵהַמֶּרְכָּבָה הָעֶלְיוֹנָה הַזּוֹ מִתְבָּרֵךְ הַשֵּׁם הַזֶּה וְנִכְלָל בְּתוֹכָם, וְאַחַר כָּךְ יִשְׂרָאֵל בִּכְלָל. אֲבָל הֲרֵי שָׁנִינוּ, זֶה יִשְׂרָאֵל סָבָא, לִהְיוֹת יִשְׂרָאֵל בִּכְלָל אֶחָד, אוֹתוֹ מָקוֹם שֶׁל דְּבֵקוּת הַכֹּל. וְעַל זֶה שְׁמַע יִשְׂרָאֵל. עַכְשָׁו נִדְבְּקָה הָאִשָּׁה בְּבַעְלָהּ, וְנִהְיָה הַכֹּל בִּכְלָל אֶחָד, וְזֶה שְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד. (ישראל) אַחַר כָּךְ מְיַחֵד שְׁלֹשָׁה צְדָדִים, ה' אֱלֹהֵינוּ ה' אֶחָד, לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>שְׁמַע יִשְׂרָאֵל שֶׁל כָּל הַשְּׁאָר אֵינָם כְּמוֹ זֶה, אֲבָל כָּל הָאֲחֵרִים בָּאוּ לִדְרָשׁ, וְכֻלָּם בְּמָקוֹם אַחֵר נִדְבְּקוּ. שְׁמַע יִשְׂרָאֵל אַתָּה עֹבֵר הַיּוֹם. שְׁמַע יִשְׂרָאֵל הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם. וְכֻלָּם בְּדַרְגָּה תַּחְתּוֹנָה נִדְבְּקוּ.</p>\n<p>שְׁמַע יִשְׂרָאֵל הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם - שְׁמַע יִשְׂרָאֵל נָאֶה הוּא, אֲבָל הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם מַהוּ? הָיָה צָרִיךְ לִהְיוֹת הָיִיתָ! מַה זֶּה נִהְיֵיתָ? אֶלָּא בְּכָל מָקוֹם עַם, כְּשֶׁנִּשְׁבְּרוּ לִבּוֹתֵיהֶם לָעֲבוֹדָה, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ח) נִהְיֵיתִי וְנֶחֱלֵיתִי. וְזֶהוּ שֶׁכָּתוּב שְׁמָעוּנִי אַחַי וְעַמִּי. אִם אַחַי, לָמָּה עַמִּי? וְאִם עַמִּי, לָמָּה אַחַי? אֶלָּא, אָמַר דָּוִד, אִם בְּרָצוֹן - אַתֶּם אַחַי. וְאִם לֹא - אַתֶּם עַמִּי, לִשְׁבֹּר לִבְּכֶם לַעֲבוֹדָתִי. כָּךְ הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם - שָׁבַרְתָּ לִבְּךְ לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>שְׁמַע יִשְׂרָאֵל אַתָּה עֹבֵר הַיּוֹם אֶת הַיַּרְדֵּן, הַכֹּל הוּא בְּדַרְגָּה תַחְתּוֹנָה, וּשְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד הוּא בְּדַרְגָּה עֶלְיוֹנָה. מַה בֵּין זֶה לָזֶה? אֶלָּא אוֹתוֹ שְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד לֹא הָיָה בְּכֻלָּם כְּמוֹ זֶה, שֶׁהֲרֵי הוּא הָיָה סוֹד שֶׁל מַעְלָה וּמַטָּה (כראוי), (ובכל מקום הסוד לקבל) וְהוּא סוֹד לְקַבֵּל עֲלֵיהֶם עֹל מַלְכוּת שָׁמַיִם בְּכָל צַד, כְּדֵי שֶׁיִּצְטָרֵךְ לָאָדָם לִהְיוֹת מְזֻמָּן (באותו שם) בְּאוֹתָהּ שָׁעָה לְיַחֵד אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמַיִם.</p>\n<p>וּבְשָׁעָה שֶׁבָּא אָדָם לְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמַיִם, אָז הַשְּׁכִינָה בָּאָה וְשׁוֹרָה עַל רֹאשׁוֹ, וְעוֹמֶדֶת עָלָיו כְּעֵד לְהָעִיד עֵדוּת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁזֶּהוּ מִי שֶׁמְּיַחֵד שְׁמוֹ פַּעֲמַיִם בְּיוֹם, וּשְׁמוֹ מִתְיַחֵד מַעְלָה וּמַטָּה כָּרָאוּי. וְלָכֵן ע' מִשְּׁמַע יִשְׂרָאֵל הִיא מֵהָאוֹתִיּוֹת הַגְּדוֹלוֹת, וְגַם ד' מֵהָאוֹתִיּוֹת הַגְּדוֹלוֹת, לִהְיוֹת עֵד לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. וַהֲרֵי פֵּרְשׁוּהָ, יְהֹוָ\"ה אֱלֹהֵינ\"וּ יְהֹוָ\"ה, וְזֶהוּ סוֹד הַיִּחוּד בִּשְׁלֹשָׁה צְדָדִים, כְּמוֹ שֶׁבֵּאֲרוֹ הַמְּנוֹרָה הַקְּדוֹשָׁה וְהִתְעוֹרֵר בּוֹ בְּכַמָּה מְקוֹמוֹת, וְאֵין לָנוּ רְשׁוּת לְהָעִיר בּוֹ יוֹתֵר.</p>\n<p>וַדַּאי הָאִישׁ הַזֶּה שֶׁמְּיַחֵד אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה כָּרָאוּי, שֶׁשְּׁכִינָה בָּאָה וְשׁוֹרָה עַל רֹאשׁוֹ וּמְבָרֶכֶת אוֹתוֹ בְּשֶׁבַע בְּרָכוֹת, וְקוֹרֵאת עָלָיו, (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>"],[9522011750,"<p>רַבִּי חִיָּיא פָּתַח אַחֲרָיו וְאָמַר, (דברים ד) אַתָּה הָרְאֵתָ לָדַעַת כִּי ה' הוּא הָאֱלֹהִים וְגוֹ'. בְּפָסוּק זֶה יֵשׁ לְהִתְבּוֹנֵן, אַתָּה הָרְאֵתָ - מַה הָרְאֵתָ? אֶלָּא כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא הָיוּ מַכִּירִים אֶת סוֹד הָאֱמוּנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלוּם, מִשּׁוּם שֶׁכֻּלָּם הָיוּ עוֹבְדִים עֲבוֹדָה זָרָה בַּגָּלוּת, וְשָׁכְחוּ אֶת כָּל עִקַּר הָאֱמוּנָה שֶׁהָיָה בָּהֶם בָּרִאשׁוֹנָה, שֶׁיָּרְשׁוּ כָּל אוֹתָם שְׁנֵים עָשָׂר שְׁבָטִים מֵאֲבִיהֶם יַעֲקֹב.</p>\n<p>וּכְשֶׁבָּא מֹשֶׁה וְלִמֵּד אוֹתָם שֶׁיֵּשׁ אֱלוֹהַּ עֶלְיוֹן בָּעוֹלָם, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְאַחַר כָּךְ רָאוּ כָּל אוֹתָם נִסִּים וּגְבוּרוֹת עַל הַיָּם וְכָל הַנִּסִּים וְהַגְּבוּרוֹת שֶׁעָשָׂה לָהֶם בְּמִצְרַיִם, וְאַחַר כָּךְ רָאוּ כַּמָּה גְבוּרוֹת בַּמָּן וּבַמַּיִם, וְנִתְּנָה לָהֶם תּוֹרָה, וְלָמְדוּ אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁהִגִּיעוּ לַזְּמַן הַזֶּה.</p>\n<p>אמר להם משה: עַד כָּאן הִצְטָרַכְתִּי לְלַמֶּדְכֶם כְּמוֹ שֶׁמְּלַמְּדִים תִּינוֹק. (מכאן ולהלאה) וְזֶהוּ אַתָּה הָרְאֵתָ לָדַעַת, וְלָמַדְתָּ עַד כָּאן לָדַעַת וּלְהִתְבּוֹנֵן וּלְהִכָּנֵס לְסוֹד הָאֱמוּנָה, וּמַהִי? כִּי ה' הוּא הָאֱלֹהִים.</p>\n<p>אִם תֹּאמַר, דָּבָר קָטָן הוּא לָדַעַת - הֲרֵי כָּתוּב, וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבֹתָ אֶל לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתַּחַת אֵין עוֹד. כָּאן תָּלוּי כָּל סוֹד הָאֱמוּנָה לָדַעַת מִתּוֹךְ זֶה סוֹד כָּל הַסּוֹדוֹת, לָדַעַת סֵתֶר (סוד של כל) כָּל הַנִּסְתָּרִים, יְהֹוָ\"ה אֱלֹהִים שֵׁם מָלֵא, וְהַכֹּל אֶחָד. אַתָּה הָרְאֵתָ לָדַעַת - כָּאן סוֹד הַסּוֹדוֹת לְיוֹדְעֵי מִדִּין.</p>"],[9522011751,"<p>אַשְׁרֵיהֶם כָּל אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, וּבִגְלַל שֶׁכְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִתְבּוֹנֵן בַּתּוֹרָה וּבָרָא אֶת הָעוֹלָם, וּבַתּוֹרָה נִבְרָא הָעוֹלָם, כְּמוֹ שֶׁבֵּאֲרוּהָ, שֶׁכָּתוּב (משלי ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן. אַל תִּקְרֵי אָמוֹן אֶלָּא אֻמָּן.</p>\n<p>וְכִי הַתּוֹרָה הָיְתָה אֻמָּן? כֵּן. לְמֶלֶךְ שֶׁרָצָה לַעֲשׂוֹת פַּלְטֵרִין. אִם לֹא שָׂם אֵלָיו אֻמָּן, לֹא יָכוֹל לַעֲשׂוֹת הַפַּלְטֵרִין. כֵּיוָן שֶׁנַּעֲשָׂה הָאַרְמוֹן, לֹא עוֹלֶה אֶלָּא בִשְׁמוֹ שֶׁל הַמֶּלֶךְ. בְּאוֹתָם אַרְמוֹנוֹת שֶׁעָשָׂה הַמֶּלֶךְ, מַשְׁקִיעַ הַמֶּלֶךְ מַחֲשָׁבָה בְּאוֹתָם אַ רְמוֹנוֹת.</p>\n<p>כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לִבְרֹא אֶת הָעוֹלָם, הִסְתַּכֵּל בָּאֻמָּן. וְאַף עָל גַּב שֶׁהָאֻמָּן עָשָׂה אֶת הָאַרְמוֹן, לֹא עוֹלֶה אֶלָּא בִשְׁמוֹ שֶׁל הַמֶּלֶךְ: אֵלּוּ הָאַרְמוֹנוֹת שֶׁעָשָׂה הַמֶּלֶךְ; וַדַּאי הַמֶּלֶךְ בָּנָה הָאַרְמוֹנוֹת. הַתּוֹרָה צוֹוַחַת: וָאֶהְיֶה אֶצְלוֹ אָמוֹן, בִּי בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם! שֶׁטֶּרֶם (אלא עד) (לא נברא) נִבְרָא הָעוֹלָם הִקְדִּימַתּוּ הַתּוֹרָה אַלְפַּיִם שָׁנִים לָעוֹלָם, וּכְשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם, הָיָה מִתְבּוֹנֵן בַּתּוֹרָה בְּכָל דָּבָר וְדָבָר, וְעָשָׂה כְנֶגְדָּהּ אֻמָּנוּתוֹ שֶׁל עוֹלָם, מִשּׁוּם שֶׁכָּל הַדְּבָרִים וְהַמַּעֲשִׂים שֶׁל כָּל הָעוֹלָמוֹת הֵם בַּתּוֹרָה, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מִתְבּוֹנֵן בָּהּ וּבוֹרֵא אֶת הָעוֹלָם.</p>\n<p>לֹא שֶׁהַתּוֹרָה בָּרְאָה אֶת הָעוֹלָם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בַּהִתְבּוֹנְנוּת שֶׁל הַתּוֹרָה בָּרָא אֶת הָעוֹלָם. נִמְצָא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא אֻמָּן, וְהַתּוֹרָה כְּנֶגְדּוֹ וְאֵלָיו אֻמָּן, שֶׁנֶּאֱמַר וָאֶהְיֶה אֶצְלוֹ אָמוֹן. וָאֶהְיֶה אָמוֹן לֹא כָתוּב, אֶלָּא אֶצְלוֹ. הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְבּוֹנֵן בָּהּ, אֶצְלוֹ הָיְתָה אֻמָּן.</p>\n<p>וְאִם תֹּאמַר, מִי יָכוֹל לִהְיוֹת אֻמָּן אֵלָיו? אֶלָּא הִתְבּוֹנְנוּת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגָוֶן זֶה (נעשה הכל בלא עמל ויגיעה, שכתוב בדבר ה' שמים נעשו וגו'. בצורה זו בהסתכלות שלו זו אמנות) בַּתּוֹרָה, כָּתוּב בָּהּ, (בראשית א) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. הִסְתַּכֵּל בְּדָבָר זֶה וּבָרָא אֶת הַשָּׁמַיִם. בַּתּוֹרָה כָּתוּב בָּהּ, וַיּאמֶר אֱלֹהִים יְהִי אוֹר - בַּדָּבָר הַזֶּה הִתְבּוֹנֵן וּבָרָא אֶת הָאוֹר. וְכֵן בְּכָל דָּבָר וְדָבָר שֶׁכָּתוּב בַּתּוֹרָה, הִתְבּוֹנֵן הַקָּדוֹשׁ בָּרוּךְ הוּא וְעָשָׂה אוֹתוֹ הַדָּבָר. וְלָכֵן כָּתוּב וָאֶהְיֶה אֶצְלוֹ אָמוֹן. כְּמוֹ כֵן נִבְרָא כָּל הָעוֹלָם.</p>\n<p>כֵּיוָן שֶׁנִּבְרָא הָעוֹלָם בְּכָל דָּבָר וְדָבָר, לֹא הִתְקַיֵּם עַד שֶׁעָלָה בְרָצוֹן לִבְרֹא אָדָם שֶׁיִּהְיֶה מִשְׁתַּדֵּל בַּתּוֹרָה, וּבִגְלָלָהּ הִתְקַיֵּם הָעוֹלָם. כָּעֵת, כָּל מִי שֶׁמִּסְתַּכֵּל בַּתּוֹרָה וּמִשְׁתַּדֵּל בָּהּ, כִּבְיָכוֹל הוּא מְקַיֵּם אֶת הָעוֹלָם. הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְתַּכֵּל בַּתּוֹרָה וּבָרָא אֶת הָעוֹלָם. אָדָם מִתְבּוֹנֵן בַּתּוֹרָה וּמְקַיֵּם אֶת הָעוֹלָם. נִמְצָא שֶׁכָּל מַעֲשֶׂה וְקִיּוּמוֹ שֶׁל עוֹלָם הִיא הַתּוֹרָה. מִשּׁוּם כָּךְ אַשְׁרֵי הָאִישׁ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, שֶׁהֲרֵי הוּא מְקַיֵּם אֶת הָעוֹלָם.</p>\n<p>בְּשָׁעָה שֶׁעָלָה בִרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָאָדָם, עָמַד לְפָנָיו בִּדְמוּתוֹ וְקִיּוּמוֹ כְּמוֹ שֶׁהוּא בָּעוֹלָם הַזֶּה. וַאֲפִלּוּ כָּל אוֹתָם בְּנֵי הָעוֹלָם, טֶרֶם בּוֹאָם לָעוֹלָם הַזֶּה, כֻּלָּם עוֹמְדִים בְּתִקּוּנָם וְקִיּוּמָם כְּמוֹ שֶׁעוֹמְדִים בָּעוֹלָם הַזֶּה בְּאוֹצָר אֶחָד שֶׁשָּׁם כָּל נִשְׁמוֹת הָעוֹלָם מִתְלַבְּשׁוֹת בִּדְמֻיּוֹתֵיהֶן.</p>\n<p>וּבְשָׁעָה שֶׁמְּזֻמָּנִים לָרֶדֶת לָעוֹלָם הַזֶּה, קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְמֻנֶּה אֶחָד שֶׁמִּנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּרְשׁוּתוֹ אֶת כָּל הַנְּשָׁמוֹת הָעֲתִידוֹת לָרֶדֶת לָעוֹלָם הַזֶּה, וְאוֹמֵר לוֹ: לֵךְ תָּבִיא לִי רוּחוֹ שֶׁל פְּלוֹנִי. בְּאוֹתָהּ שָׁעָה בָּאָה אוֹתָהּ נְשָׁמָה מְלֻבֶּשֶׁת בִּדְמוּת שֶׁל הָעוֹלָם הַזֶּה, וְאוֹתוֹ מְמֻנֶּה מַרְאֶה אוֹתָהּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>הַקָּדוֹשׁ בָּרוּךָ הוּא אוֹמֵר לוֹ וּמַשְׁבִּיעַ אוֹתָהּ, שֶׁכְּשֶׁתֵּרֵד לָעוֹלָם הַזֶּה, שֶׁתִּשְׁתַּדֵּל בַּתּוֹרָה לָדַעַת אוֹתוֹ וְלָדַעַת אֶת סוֹד הָאֱמוּנָה. שֶׁכָּל מִי שֶׁהָיָה בָּעוֹלָם הַזֶּה וְלֹא הִשְׁתַּדֵּל לָדַעַת אוֹתוֹ - טוֹב לוֹ שֶׁלֹּא יִבָּרֵא. מִשּׁוּם כָּךְ נִרְאָה לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, לָדַעַת אֶת הָעוֹלָם הַזֶּה, וּלְהִשְׁתַּדֵּל בַּקָּדוֹשׁ-בָּרוּךְ- הוּא בְּסוֹד הָאֱמוּנָה.</p>"],[9522011752,"<p>זְהִוּ שֶׁכָּתוּב (דברים ד) אַתָּה הָרְאֵתָ לָדַעַת. הָרְאֵיתָ עַל יְדֵי אוֹתוֹ הַמְמֻנֶּה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. לָדַעַת - לָדַעַת וּלְהִסְתַּכֵּל בָּעוֹלָם הַזֶּה בְּסוֹד הָאֱמוּנָה וּבְסוֹד הַתּוֹרָה. וְכָל מִי שֶׁהָיָה בָּעוֹלָם הַזֶּה וְלֹא הִשְׁתַּדֵּל בַּתּוֹרָה לְהַכִּירוֹ, טוֹב לוֹ שֶׁלֹּא נִבְרָא, שֶׁהֲרֵי בִּשְׁבִיל זֶה הֱבִיאוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם לָעוֹלָם הַזֶּה.</p>\n<p>לָדַעַת כִּי ה' הוּא הָאֱלֹהִים. זֶהוּ הַכְּלָל שֶׁל כָּל סוֹד הָאֱמוּנָה, (כלל) שֶׁל כָּל הַתּוֹרָה, כְּלָל שֶׁלְּמַעְלָה וּמַטָּה. וְסוֹד זֶה הוּא הַכְּלָל שֶׁל כָּל סוֹד הָאֱמוּנָה, וְכָךְ זֶה וַדַּאי. הַכְּלָל שֶׁל כָּל הַתּוֹרָה זֶהוּ סוֹד הַתּוֹרָה שֶׁבִּכְתָב, וְזֶהוּ סוֹד הַתּוֹרָה שֶׁבְּעַל פֶּה, וְהַכֹּל אֶחָד, הַכְּלָל שֶׁל סוֹד הָאֱמוּנָה, בִּשְׁבִיל שֶׁהוּא שֵׁם מָלֵא, שֶׁהוּא סוֹד הָאֱמוּנָה, וּמִיהוּ? ה' אֶחָד וּשְׁמוֹ אֶחָד. ה' אֶחָד - שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. זֶהוּ יִחוּד אֶחָד. וּשְׁמוֹ אֶחָד, בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד - הֲרֵי יִחוּד אַחֵר לִהְיוֹת שְׁמוֹ אֶחָד. וְסוֹד זֶה - ה' הוּא הָאֱלֹהִים, זֶה כָּתוּב כְּשֶׁהֵם בְּיִחוּד אֶחָד.</p>\n<p>וְאִם תֹּאמַר, אִם כֵּן, כְּדֻגְמַת מַה שֶּׁכָּתוּב (זכריה יד) ה' אֶחָד וּשְׁמוֹ אֶחָד, לֹא הוּא ה' הוּא הָאֱלֹהִים, שֶׁאִם הָיָה כָתוּב (ה' הוא ושמו אחד) ה' אֶחָד וּשְׁמוֹ הוּא אֶחָד, הָיִיתִי אוֹמֵר כָּךְ. אֲבָל לֹא כָתוּב אֶלָּא ה' אֶחָד וּשְׁמוֹ אֶחָד, וְצָרִיךְ לוֹמַר, כְּדֻגְמַת זֶה ה' הוּא הָאֱלֹהִים הוּא, וְנִרְאֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>\n<p>אֶלָּא הַכֹּל אֶחָד. שֶׁכְּשֶׁמִּתְיַחֲדִים שְׁנֵי הַשֵּׁמוֹת הַלָּלוּ, זֶה בְּיִחוּד אֶחָד וְזֶה בְּיִחוּד אֶחָד, אָז שְׁנֵי הַשֵּׁמוֹת הַלָּלוּ נַעֲשִׂים אֶחָד וְנִכְלָלִים זֶה בָּזֶה, וְנִהְיָה הַכֹּל שֵׁם שָׁלֵם בְּיִחוּד אֶחָד, וּבְכֵן ה' הוּא הָאֱלֹהִים, שֶׁהֲרֵי אָז הַכֹּל נִכְלָל זֶה בָּזֶה לִהְיוֹת אֶחָד. וְטֶרֶם שֶׁמִּתְיַחֲדִים כָּל אֶחָד, זֶה בִּלְבַדּוֹ וְזֶה בִּלְבַדּוֹ, לֹא נִכְלָלִים זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>הַכְּלָל שֶׁל כָּל הַתּוֹרָה כָּךְ הוּא וַדַּאי. שֶׁהֲרֵי הַתּוֹרָה הִיא תּוֹרָה שֶׁבִּכְתָב וְהוּא תּוֹרָה שֶׁבְּעַל פֶּה. תּוֹרָה שֶׁבִּכְתָב, זֶהוּ שֶׁכָּתוּב ה'. תּוֹרָה שֶׁבְּעַל פֶּה, זֶהוּ שֶׁכָּתוּב הָאֱלֹהִים. וּמִשּׁוּם שֶׁהַתּוֹרָה הִיא סוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, נִקְרֵאת כָּךְ - תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, זֶה כְּלָל וְזֶה פְּרָט. הַכְּלָל צָרִיךְ אֶת הַפְּרָט, וְהַפְּרָט צָרִיךְ אֶת הַכְּלָל, וּמִתְיַחֲדִים זֶה עִם זֶה לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וְעַל זֶה הַכְּלָל שֶׁל הַתּוֹרָה הוּא הַכְּלָל שֶׁל מַעְלָה וּמַטָּה, מִשּׁוּם שֶׁשֵּׁם זֶה לְמַעְלָה וְשֵׁם זֶה לְמַטָּה זֶה סוֹד שֶׁל הָעוֹלָם הָעֶלְיוֹן, וְזֶה סוֹד שֶׁל הָעוֹלָם הַתַּחְתּוֹן, וְעַל זֶה כָּתוּב אַתָּה הָרְאֵתָ לָדַעַת כִּי ה' הוּא הָאֱלֹהִים. זֶהוּ הַכְּלָל שֶׁל הַכֹּל, וְזֶה צָרִיךְ אָדָם לָדַעַת בָּעוֹלָם הַזֶּה.</p>\n<p>וְאִם תֹּאמַר, אֵיפֹה הֵן מִצְווֹת הַתּוֹרָה כָּאן בַּכְּלָל הַזֶּה? אֶלָּא זֶהוּ זָכוֹר וְזֶהוּ שָׁמוֹר, וְכָל מִצְווֹת הַתּוֹרָה כְּלוּלִים בְּאֵלֶּה, בְּסוֹד שֶׁל זָכוֹר וְשָׁמוֹר, וְהַכֹּל הוּא אֶחָד.</p>"],[9522011753,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, זֶה שֶׁשָּׁנִינוּ שֶׁתְּפִלַּת עַרְבִית חוֹבָה - חוֹבָה הִיא וַדַּאי, מִשּׁוּם שֶׁקְּרִיאַת שְׁמַע שֶׁל עַרְבִית חוֹבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְיַחֵד בַּלַּיְלָה כְּמוֹ שֶׁמִּתְיַחֵד בַּיּוֹם, וּמִדַּת לַיְלָה נִכְלֶלֶת בַּיּוֹם, וּמִדַּת יוֹם נִכְלֶלֶת בַּלַּיְלָה, וְנַעֲשֶׂה יִחוּד אֶחָד. וּמִי שֶׁאָמַר רְשׁוּת - מִשּׁוּם אֵמוּרִים וּפְדָרִים שֶׁמִּתְאַכְּלִים בַּלַּיְלָה, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>כָּתוּב, (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ וּבְכָל נַפְשְׁךְ וְגוֹ'. פָּסוּק זֶה בֵּאַרְנוּהוּ וּפֵרְשׁוּהוּ הַחֲבֵרִים, אֲבָל יֵשׁ לִשְׁאֹל, אִם בַּיִּחוּד הַזֶּה שֶׁל שְׁמַע יִשְׂרָאֵל נִכְלָל הַכֹּל - יָמִין וּשְׂמֹאל, לָמָּה (כתוב) אַחַר כָּךְ וְאָהַבְתָּ, (שם יא) וְהָיָה אִם שָׁמוֹעַ, שֶׁהֲרֵי בַּיִּחוּד נִכְלְלוּ? אֲבָל שָׁם בִּכְלָל, וְכָאן בִּפְרָט, וְכָךְ צָרִיךְ.</p>\n<p>וּבְסוֹד הַיִּחוּד הַזֶּה הֵעַרְנוּ בוֹ, הַיִּחוּד הַזֶּה הוּא כְּמוֹ שֶׁל הַתְּפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ. בִּתְפִלֵּי הָרֹאשׁ אַרְבַּע פָּרָשִׁיּוֹת, וַהֲרֵי נִתְבָּאֵר, וְכָאן שְׁלֹשָׁה שֵׁמוֹת הֵם. שָׁם בִּתְפִלִּין שֶׁל רֹאשׁ, אַרְבַּע פָּרָשִׁיּוֹת, כָּל אַחַת וְאַחַת לְבַדָּהּ, וְכָאן שְׁלֹשָׁה שֵׁמוֹת. מַה בֵּין זֶה לָזֶה?</p>\n<p>אֶלָּא, אוֹתָן אַרְבַּע פָּרָשִׁיּוֹת הֲרֵי הֵעִירוּ בָהֶן, אַחַת נְקֻדָּה רִאשׁוֹנָה עֶלְיוֹנָה, וְאַחַת סוֹד הָעוֹלָם הַבָּא, וְאַחַת יָמִין, וְאַחַת שְׂמֹאל. אֵלּוּ סוֹד תְּפִלִּין שֶׁל רֹאשׁ. וְכָאן בְּסוֹד הַיִּחוּד הַזֶּה שְׁלֹשָׁה שֵׁמוֹת, וְהֵם כְּמוֹ שֶׁאוֹתָן אַרְבַּע פָּרָשִׁיּוֹת. ה' הָרִאשׁוֹן זוֹ נְקֻדָּה עֶלְיוֹנָה, רֵאשִׁית הַכֹּל. אֱלֹהֵינוּ - סוֹד הָעוֹלָם הַבָּא. ה' הָאַחֲרוֹן - כְּלָל שֶׁל יָמִין וּשְׂמֹאל כְּאֶחָד בִּכְלָל אֶחָד, וְאֵלֶּה הֵן תְּפִלִּין שֶׁל רֹאשׁ, וְזֶהוּ הַיִּחוּד הָרִאשׁוֹן.</p>\n<p>תְּפִלִּין שֶׁל זְרוֹעַ, הַכְּלָל שֶׁל כָּל אֵלֶּה כְּאֶחָד, וְזֶהוּ סוֹד בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. כָּאן הַכְּלָל שֶׁל אוֹתָן תְּפִלִּין שֶׁל רֹאשׁ שֶׁנִּכְלְלוּ בְתוֹךְ תְּפִלִּין שֶׁל זְרוֹעַ.</p>\n<p>וְסוֹד זֶה, בָּרוּךְ - זֶה סוֹד הַנְּקֻדָּה הָעֶלְיוֹנָה, שֶׁהוּא בָּרוּךְ, שֶׁכָּל הַבְּרָכוֹת נוֹבְעוֹת מִשָּׁם. וְאִם תֹּאמַר, הָעוֹלָם הַבָּא הוּא שֶׁנִּקְרָא בָּרוּךְ - לֹא כָּךְ! שֶׁהֲרֵי הַנְּקֻדָּה הָעֶלְיוֹנָה הִיא זָכָר, הָעוֹלָם הַבָּא נְקֵבָה. הוּא בָּרוּךְ וְהִיא בְּרָכָה. בָּרוּךְ זָכָר, בְּרָכָה נְקֵבָה. וְלָכֵן בָּרוּךְ הוּא נְקֻדָּה עֶלְיוֹנָה. שֵׁם - זֶה הָעוֹלָם הַבָּא, שֶׁהוּא שֵׁם גָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר (יהושע ז) וּמַה תַּעֲשֵׂה לְשִׁמְךְ הַגָּדוֹל. כְּבוֹד - זֶה הַכָּבוֹד הָעֶלְיוֹן שֶׁהוּא יָמִין וּשְׂמֹאל.</p>\n<p>וְכֻלָּם כְּלוּלִים בִּתְפִלָּה זוֹ שֶׁל יָד, שֶׁהִיא מַלְכוּתוֹ, וְנוֹטֶלֶת הַכֹּל לְתוֹכָהּ. וּבַמַּלְכוּתוֹ הַזּוֹ נִכְלָלִים כָּל הָעוֹלָמוֹת לָזוּן אוֹתָם וּלְסַפֵּק לָהֶם בְּכָל מַה שֶּׁצְּרִיכִים, וְעַל זֶה לְעוֹלָם וָעֶד.</p>\n<p>וְזְהִוּ הַיִּחוּד שֶׁל תְּפִלִּין שֶׁל רֹאשׁ וּתְפִלִּין שֶׁל זְרוֹעַ, וּכְמוֹ שֶׁסּוֹד הַיִּחוּד שֶׁל הַתְּפִלִּין - כָּךְ הוּא הַיִּחוּד שֶׁל הַכֹּל, וְזֶהוּ בֵּרוּר הַדָּבָר. וַהֲרֵי סִדַּרְנוּ הַיִּחוּד הַזֶּה לִפְנֵי הַמְּנוֹרָה הַקְּדוֹשָׁה, וְאָמַר לִי, שֶׁהֲרֵי בְּאַרְבָּעָה גְוָנִים הִסְתַּדֵּר הַיִּחוּד, וְזֶהוּ הַמֻּבְחָר מִכֻּלָּם, וְכָךְ הוּא וַדַּאי, וְכֻלָּם סוֹד הָאֱמוּנָה. אֲבָל סִדּוּר הַתְּפִלִּין זֶהוּ הַיִּחוּד הָעֶלְיוֹן כָּרָאוּי.</p>"],[9522011754,"<p>וּמִתּוֹךְ שֶׁנִּכְלְלוּ יָמִין וּשְׂמֹאל בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ בְּדֶרֶךְ כְּלָל, צָרִיךְ אַחַר כָּךְ לְהוֹצִיאָם בְּדֶרֶךְ פְּרָט, אֲבָל לֹא בְּדֶרֶךְ יִחוּד, שֶׁהֲרֵי הַיִּחוּד בַּפָּסוּק הוּא רִאשׁוֹן, לִהְיוֹת יְהֹוָ\"ה אֶחָד בִּתְפִלִּין שֶׁל רֹאשׁ, וּשְׁמוֹ אֶחָד בִּתְפִלִּין שֶׁל זְרוֹעַ, וְנִהְיָה הַכֹּל אֶחָד. כֵּיוָן שֶׁהַיִּחוּד הַזֶּה מִסְתַּדֵּר הַכֹּל בִּכְלָל מֵהָרֹאשׁ שֶׁל הַנְּקֻדָּה הָעֶלְיוֹנָה, (שהוא ראשית הכל) צָרִיךְ אַחַר כָּךְ לְהָעִיר מֵהָרֹאשׁ (מהסוד) שֶׁל הָאוֹר הָרִאשׁוֹן, שֶׁהוּא רֹאשׁ הַכֹּל.</p>\n<p>וְאָהַבְתָּ - זוֹ רֵאשִׁית הַיָּמִין, לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאַהֲבָה שֶׁל הַדְּבֵקוּת שֶׁלּוֹ, וּמִיהוּ? (האהבה של התעוררותהימין) הַיָּמִין, שֶׁהוּא מְעוֹרֵר הָאַהֲבָה. מִי שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הוּא מֵעִיר אֶת יְמִינוֹ אֵלָיו וּמְקַבְּלוֹ בְּאַהֲבָה. כָּל דִּבְרֵי הָעוֹלָם לֹא תְלוּיִים אֶלָּא בְרָצוֹן, רוּחַ מַמְשִׁיכָה רוּחַ וּמְבִיאָה רוּחַ, וְסִימָנְךְ זֶה - (איובלד) אִם יָשִׂים אֵלָיו לִבּוֹ רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסֹף.</p>\n<p>כְּשֶׁמְּעוֹרֵר הָאָדָם אַהֲבָה לַקָּדוֹשׁ בָּרוּךְ הוּא, הִתְעוֹרְרוּת הַיָּמִין לֹא נְעוֹרָה אֶלָּא בִּשְׁלֹשָׁה גְוָנִים, כְּמוֹ שֶׁנֶּאֱמַר (דברים ו) בְּכָל לְבָבְךְ וּבְכָל נַפְשְׁךְ וּבְכָל מְאֹדֶךְ. הֲרֵי כָּאן שְׁלֹשָׁה גְוָנִים. שֶׁלֹּא תֹאמַר אוֹ זֶה אוֹ זֶה, שֶׁהֲרֵי לֹא כָתוּב אוֹ בְּכָל לְבָבְךְ אוֹ בְּכָל נַפְשְׁךְ אוֹ בְּכָל מְאֹדֶךְ. אֶלָּא צָרִיךְ אֶת כֻּלָּם, לֵב וְנֶפֶשׁ וּמָמוֹן. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מֵעִיר אֶת יְמִינוֹ אֵלָיו, וּפוֹשֵׁט אוֹתָהּ כְּנֶגְדּוֹ וּמְקַבֵּל אוֹתוֹ.</p>\n<p>וְעַל זֶה כָּתוּב, (תהלים קו) נְאֻם ה' לַאדנִי שֵׁב לִימִינִי. וְסוֹד הַכָּתוּב הַזֶּה הֲרֵי הֵעַרְנוּ בוֹ, שֶׁדָּוִד הַמֶּלֶךְ עַל דַּרְגָּתוֹ אָמַר, כְּשֶׁנִּקְשַׁר בַּיָּמִין. שְׁלֹשׁ עֶשְׂרֵה מִצְווֹת כָּאן בְּיָמִין: וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ - הֲרֵי אַחַת. בְּכָל לְבָבְךְ - שְׁתַּיִם. וּבְכָל נַפְשְׁךְ - שָׁלֹשׁ. וּבְכָל מְאֹדֶךְ - אַרְבַּע. וְשִׁנַּנְתָּם לְבָנֶיךְ - חָמֵשׁ. וְדִבַּרְתָּ בָּם - הֲרֵי שֵׁשׁ. בְּשִׁבְתְּךְ בְּבֵיתֶךְ - הֲרֵי שֶׁבַע. וּבְלֶכְתְּךְ בַדֶּרֶךְ - שְׁמוֹנֶה. וּבְשָׁכְבְּךְ - הֲרֵי תֵּשַׁע. וּבְקוּמֶךְ - הֲרֵי עֶשֶׂר. וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךְ - הֲרֵי אַחַת עֶשְׂרֵה. וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךְ - הֲרֵי שְׁתֵּים עֶשְׂרֵה. וּכְתַבְתָּם עַל מְזֻזוֹת בֵּיתֶךְ וּבִשְׁעָרֶיךְ - הֲרֵי שְׁלֹשׁ עֶשְׂרֵה.</p>\n<p>שְׁלש עֶשְׂרֵה הַמִּצְווֹת הַלָּלוּ תְּלוּיוֹת בַּיָּמִין, וְהַשְּׂמֹאל נִכְלָל בַּיָּמִין, וְכָךְ צָרִיךְ. וּבְכָל זְמַן שֶׁמִּתְעוֹרֵר הַשְּׂמֹאל, הַיָּמִין מַתְחִיל בָּרֹאשׁ. וְלָכֵן אִם יִזְכּוּ, הַשְּׂמֹאל נִכְלָל בַּיָּמִין. וְאִם לֹא, הַיָּמִין נִכְלָל בַּשְּׂמֹאל, וְשׁוֹלֵט הַשְּׂמֹאל. וְסִימָן לָזֶה, אִם בָּרֹאשׁ, כְּמוֹ אִם בְּחֻקֹּתַי תֵּלֵכוּ. וּבְכָל מָקוֹם הַשְּׂמֹאל מִתְעוֹרֵר בְּאַהֲבָה בְּסוֹד הַיָּמִין, אַחַר כָּךְ מִתְחַזֵּק דִּינוֹ כְּמוֹ שֶׁצָּרִיךְ, וְכָךְ צָרִיךְ בְּכָל מָקוֹם, וְזֶה הֵעִירוּ הַחֲבֵרִים בַּדְּבָרִים הַלָּלוּ. בָּא רַבִּי חִיָּיא וּנְשָׁקוֹ.</p>"],[9522011755,"<p>פָּתַח וְאָמַר, וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעֹת וְגוֹ'. הֲרֵי כָּאן סוֹד הַיִּחוּד, שֶׁהֲרֵי תִּקּוּנוֹ שֶׁל הַמִּשְׁכָּן הוּא מִכַּמָּה דְרָגוֹת, שֶׁכָּתוּב בּוֹ וְהָיָה הַמִּשְׁכָּן אֶחָד. לְהַרְאוֹת שֶׁכָּל הָאֵיבָרִים שֶׁל הַגּוּף כֻּלָּם בְּסוֹד שֶׁל גּוּף אֶחָד.</p>\n<p>בְּאָדָם יֵשׁ כַּמָּה אֵיבָרִים עֶלְיוֹנִים וְתַחְתּוֹנִים, אֵלֶּה פְּנִימִיִּים לַפְּנִים, וְאֵלֶּה בְּגִלּוּי לַחוּץ, וְכֻלָּם נִקְרָאִים גּוּף אֶחָד, וְנִקְרָא אָדָם אֶחָד בְּחִבּוּר אֶחָד. אַף כָּךְ הַמִּשְׁכָּן כָּל הָאֵיבָרִים כְּמוֹ שֶׁלְּמַעְלָה, וּכְשֶׁכֻּלָּם מִתְחַבְּרִים כְּאֶחָד, אָז כָּתוּב וְהָיָה הַמִּשְׁכָּן אֶחָד. (כדגמת האדם).</p>\n<p>מִצְווֹת הַתּוֹרָה כֻּלָּם אֵיבָרִים בַּסּוֹד שֶׁל מַעְלָה. וּכְשֶׁכֻּלָּם מִתְחַבְּרִים כְּאֶחָד, אָז כֻּלָּם עוֹלִים לְסוֹד אֶחָד. סוֹד הַמִּשְׁכָּן, שֶׁהוּא פְּרָקִים וְאֵיבָרִים, כֻּלָּם עוֹלִים לְסוֹד שֶׁל אָדָם, כְּמוֹ שֶׁמִּצְווֹת הַתּוֹרָה, שֶׁהֲרֵי מִצְווֹת הַתּוֹרָה כֻּלָּם בְּסוֹד שֶׁל אָדָם, זָכָר וּנְקֵבָה, שֶׁכְּשֶׁמִּתְחַבְּרִים כְּאֶחָד הֵם אֶחָד בְּסוֹד שֶׁל אָדָם. מִי שֶׁפּוֹגֵם אֲפִלּוּ מִצְוָה אַחַת שֶׁל הַתּוֹרָה, כְּאִלּוּ פָּגַם בִּדְמוּת הָאֱמוּנָה, שֶׁהֲרֵי כָּל הַפְּרָקִים וְהָאֵיבָרִים בִּדְמוּת אָדָם, וְלָכֵן הַכֹּל עוֹלֶה בְּסוֹד הַיִּחוּד.</p>\n<p>וְעַל זֶה יִשְׂרָאֵל הֵם גּוֹי אֶחָד, שֶׁכָּתוּב (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וְכָתוּב (שמואל ב ז) מִי כְעַמְּךְ כְּיִשְׂרָאֵל וְגוֹ'.</p>"],[9522011756,"<p>רַבִּי יִצְחָק הָיָה מָצוּי לִפְנֵי רַבִּי אֶלְעָזָר, אָמַר לוֹ, וַדַּאי שֶׁאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאָדָם אוֹהֵב אוֹתוֹ לֹא מִתְעוֹרֶרֶת אֶלָּא מֵהַלֵּב, מִשּׁוּם שֶׁלֵּב הוּא הִתְעוֹרְרוּת לְהָעִיר אֵלָיו אַהֲבָה. (והקדושברוך הוא רוצהאתהלב) אִם כָּךְ, לָמָּה כָּתוּב בְּכָל לְבָבְךְ וְאַחַר כָּךְ וּבְכָל נַפְשְׁךְ, שֶׁמַּשְׁמָע שֶׁהֵם שְׁנֵי גְוָנִים, אֶחָד הַלֵּב וְאֶחָד הַנֶּפֶשׁ? אִם הַלֵּב עִקָּר - מַה צָּרִיךְ נֶפֶשׁ? אָמַר לוֹ, וַדַּאי שֶׁלֵּב וָנֶפֶשׁ הֵם שְׁנַיִם, וּמִתְאַחֲדִים לְאֶחָד. שֶׁהֲרֵי לֵב וְנֶפֶשׁ וּמָמוֹן, כֻּלָּם אֲחוּזִים זֶה בָּזֶה, וְהַלֵּב הוּא עִקַּר וִיסוֹד הַכֹּל.</p>\n<p>וְזְהִ שֶׁנֶּאֱמַר בְּכָל לְבָבְךְ, בִּשְׁנֵי לְבָבוֹת הוּא, שֶׁהֵם שְׁנֵי יְצָרִים, אֶחָד יֵצֶר טוֹב וְאֶחָד יֵצֶר רַע. וּשְׁנֵי אֵלֶּה, כָּל אֶחָד וְאֶחָד נִקְרָא לֵב. זֶה נִקְרָא לֵב טוֹב, וְזֶה נִקְרָא לֵב רַע. וּמִשּׁוּם כָּךְ הוּא לְבָבְךְ, שֶׁהֵם שְׁנַיִם, יֵצֶר הַטּוֹב וְיֵצֶר הָרָע.</p>\n<p>וּבְכָל נַפְשְׁךְ? וּבְנַפְשְׁךְ הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה וּבְכָל נַפְשְׁךְ? הַבְּכָל הַזֶּה לְשֵׁם מָה? אֶלָּא לְהַכְלִיל נֶפֶ\"שׁ וְרוּ\"חַ וּנְשָׁמָ\"ה. זֶהוּ וּבְכָל נַפְשְׁךְ, בְּכָל מַה שֶּׁאוֹחֶזֶת הַנֶּפֶשׁ הַזּוֹ. וּבְכָל מְאֹדֶךְ, אַף כָּךְ כַּמָּה מִינִים הֵם שֶׁל מָמוֹן, כֻּלָּם מְשֻׁנִּים אֵלֶּה מֵאֵלֶּה, וְעַל זֶה כָּתוּב בְּכָל. אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא לִמְסֹר לוֹ כָּל זֶה, לֶאֱהֹב אוֹתוֹ בְּכָל אֶחָד וְאֶחָד.</p>\n<p>וְאִם תֹּאמַר, בַּיֵּצֶר הָרָע אֵיךְ אָדָם יָכוֹל לֶאֱהֹב אוֹתוֹ, שֶׁהֲרֵי יֵצֶר הָרָע הוּא מְקַטְרֵג שֶׁלֹּא יִקְרַב אָדָם לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֵיךְ יאהַב אוֹתוֹ בּוֹ? אֶלָּא זוֹהִי עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹתֵר, כְּשֶׁהַיֵּצֶר הַזֶּה נִכְנָע לוֹ מִשּׁוּם הָאַהֲבָה שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכְּשֶׁהַיֵּצֶר הָרָע הַזֶּה נִכְנָע וְהָאָדָם הַזֶּה שׁוֹבֵר אוֹתוֹ, זוֹהִי אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁיּוֹדֵעַ לְקָרֵב אֶת אוֹתוֹ יֵצֶר הָרָע לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>כָּאן הוּא סוֹד לְבַעֲלֵי הַדִּין. כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה, הַכֹּל הוּא כְּדֵי לְהַרְאוֹת כְּבוֹדוֹ, וְהַכֹּל הוּא לַעֲבוֹדָתוֹ. וְכִי מִי רָאָה עֶבֶד שֶׁמְּקַטְרֵג אֶת אֲדוֹנוֹ, וּבְכָל מַה שֶּׁרְצוֹן אֲדוֹנוֹ נַעֲשֶׂה הוּא מְקַטְרֵג?! רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא שֶׁיִּהְיוּ הָאֲנָשִׁים תָּמִיד בַּעֲבוֹדָתוֹ וְיֵלְכוּ בְּדֶרֶךְ אֱמֶת כְּדֵי לְזַכּוֹתָם בְּכַמָּה טוֹבוֹת. הוֹאִיל וּרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּזֶה, אֵיךְ בָּא עֶבֶד רַע וְנִמְצָא מְקַטְרֵג מִתּוֹךְ רְצוֹן אֲדוֹנוֹ וּמַסְטֶה אֶת בְּנֵי הָאָדָם לְדֶרֶךְ רָעָה, וְדוֹחֶה אוֹתָם מִדֶּרֶךְ טוֹבָה, וְעוֹשֶׂה לָהֶם שֶׁלֹּא יַעֲשׂוּ אֶת רְצוֹן אֲדוֹנָם וּמַסְטֶה אֶת בְּנֵי הָאָדָם לְדֶרֶךְ רָעָה?</p>\n<p>אֶלָּא וַדַּאי שֶׁרְצוֹן אֲדוֹנוֹ הוּא עוֹשֶׂה. לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יְחִידִי וְהָיָה אוֹהֵב אוֹתוֹ בְּיוֹתֵר, וְצִוָּה עָלָיו בְּאַהֲבָה שֶׁלֹּא יַקְרִיב אֶת עַצְמוֹ לְאִשָּׁה רָעָה, מִשּׁוּם שֶׁכָּל מִי שֶׁקָּרֵב אֵלֶיהָ, אֵינוֹ כְּדָאִי לְהִכָּנֵס לְהֵיכַל הַמֶּלֶךְ. הוֹדָה לוֹ אוֹתוֹ הַבֵּן לַעֲשׂוֹת רְצוֹן אָבִיו בְּאַהֲבָה.</p>\n<p>בְּבֵית הַמֶּלֶךְ בַּחוּץ הָיָה זוֹנָה אַחַת נָאָה לְמַרְאֶה וִיפַת תֹּאַר. לְיָמִים אָמַר הַמֶּלֶךְ, אֲנִי רוֹצֶה לִרְאוֹת אֶת רְצוֹנוֹ שֶׁל בְנִי אֵלַי. קָרָא לְאוֹתָהּ הַזּוֹנָה וְאָמַר לָהּ: לְכִי וּתְפַתִּי אֶת בְּנִי, כְּדֵי לִרְאוֹת אֶת רְצוֹן בְּנִי אֵלַי. מֶה עָשְׂתָה אוֹתָהּ זוֹנָה? הָלְכָה אַחַר בֶּן הַמֶּלֶךְ וְהִתְחִילָה לְחַבֵּק וּלְנַשֵּׁק אוֹתוֹ וּלְפַתּוֹתוֹ בְּכַמָּה פִתּוּיִים. אִם אוֹתוֹ בֵּן יָאֶה וּמְצַיֵּת לְמִצְוַת אָבִיו - גּוֹעֵר בָּהּ וְלֹא מְצַיֵּת לָהּ וְדוֹחֶה אוֹתָהּ מִמֶּנּוּ. וְאָז אָבִיו שָׂמֵחַ בִּבְנוֹ וּמַכְנִיסוֹ לְתוֹךְ הַפַּרְגּוֹד שֶׁל הֵיכָלוֹ, וְנוֹתֵן לוֹ מַתָּנוֹת וְאוֹצָרוֹת וְכָבוֹד רַב. מִי גָרַם אֶת כָּל הַכָּבוֹד הַזֶּה לַבֵּן הַזֶּה? הֱוֵה אוֹמֵר, אוֹתָהּ הַזּוֹנָה.</p>\n<p>וְאוֹתָהּ הַזּוֹנֶה יֵשׁ לָהּ בָּזֶה שֶׁבַח אוֹ לֹא? וַדַּאי שֶׁיֵּשׁ לָהּ שֶׁבַח מִכָּל הַצְּדָדִים. אֶחָד - שֶׁעָשְׂתָה אֶת רְצוֹן הַמֶּלֶךְ. וְאֶחָד - שֶׁגָּרְמָה לְאוֹתוֹ הַבֵּן כָּל אוֹתוֹ הַטּוּב וּלְכָל הָאַהֲבָה הַזּוֹ שֶׁל הַמֶּלֶךְ אֵלָיו. וְעַל זֶה כָּתוּב (בראשית א) וְהִנֵּה טוֹב מְאֹד. וְהִנֵּה טוֹב - זֶה מַלְאַךְ הַחַיִּים. מְאֹד - זֶה מַלְאַךְ הַמָּוֶת, שֶׁהוּא וַדַּאי טוֹב מְאֹד לְמִי שֶׁמְּצַיֵּת לְמִצְווֹת רִבּוֹנוֹ. וּבֹא רְאֵה, אִם לֹא יִהְיה הַמְקַטְרֵג הַזֶּה, לֹא הָיוּ יוֹרְשִׁים הַצַּדִּיקִים אֶת הַגְּנָזִים הָעֶלְיוֹנִים הַלָּלוּ, שֶׁעֲתִידִים לָרֶשֶׁת עוֹלָם הַבָּא.</p>\n<p>אַשְׁרֵיהֶם שֶׁנִּפְגְּשׁוּ בַּמְקַטְרֵג הַזֶּה, וְאַשְׁרֵיהֶם שֶׁלֹּא פָגְשׁוּ בוֹ. אַשְׁרֵיהֶם שֶׁפָּגְשׁוּ בוֹ וְנִצְּלוּ מִמֶּנּוּ, שֶׁבִּשְׁבִילוֹ יוֹרְשִׁים כָּל אוֹתָן טוֹבוֹת וְכָל אוֹתָם עִדּוּנִים וְכָל אוֹתָן תְּשׁוּקוֹת שֶׁל הָעוֹלָם הַבָּא, שֶׁעָלָיו כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתֶךְ.</p>\n<p>וְאַשְׁרֵי אוֹתָם שֶׁלֹּא פָגְשׁוּ בוֹ, שֶׁבִּשְׁבִילוֹ יוֹרְשִׁים גֵּיהִנֹּם וְנִטְרְדוּ מֵאֶרֶץ הַחַיִּים, שֶׁהֲרֵי אוֹתָם הָרְשָׁעִים שֶׁפָּגְשׁוּ אוֹתוֹ, הָיוּ מְצַיְּתִים לוֹ וְנִמְשְׁכוּ אַחֲרָיו, וְעַל זֶה יֵשׁ לַצַּדִּיקִים לְהַחֲזִיק לוֹ טוֹבָה, שֶׁהֲרֵי בִּגְלָלוֹ יוֹרְשִׁים כָּל אוֹתָן הַטּוֹבוֹת וְעִדּוּנִים וּתְשׁוּקוֹת לָעוֹלָם הַבָּא.</p>\n<p>מַהִי תּוֹעַלְתּוֹ שֶׁל הַמְקַטְרֵג הַזֶּה כַּאֲשֶׁר הָרְשָׁעִים מְצַיְּתִים לוֹ? אֶלָּא אַף עַל גַּב שֶׁאֵין בּוֹ תּוֹעֶלֶת, מִצְוַת אֲדוֹנוֹ הוּא עוֹשֶׂה. וְעוֹד, שֶׁהֲרֵי מִתְחַזֵּק בִּשְׁבִיל זֶה. הוֹאִיל וְהוּא רַע, הוּא מִתְחַזֵּק כְּשֶׁהוּא עוֹשֶׂה רַע. הָרָשָׁע אֵינוֹ מִתְחַזֵּק, עַד שֶׁהוֹרֵג אָדָם. כֵּיוָן שֶׁהָרַג בְּנֵי אָדָם, אָז מִתְחַזֵּק וּמִתְגַּבֵּר בְּכֹחוֹ וְיֵשׁ לוֹ נַחַת. כָּךְ אוֹתוֹ מְקַטְרֵג שֶׁנִּקְרָא מַלְאַךְ הַמָּוֶת לֹא מִתְגַּבֵּר בְּכֹחוֹ, עַד שֶׁמַּסְטֶה אֶת בְּנֵי הָאָדָם וּמְקַטְרֵג לָהֶם וְהוֹרֵג אוֹתָם, וְאָז יֵשׁ לוֹ נַחַת וּמִתְחַזֵּק וּמִתְגַּבֵּר בְּכֹחוֹ.</p>\n<p>כְּמוֹ שֶׁמִּתְחַזֵּק צַד הַחַיִּים כְּשֶׁבְּנֵי אָדָם הֵם טוֹבִים וְיֵלְכוּ בְּדֶרֶךְ יָשָׁר, אַף כָּךְ הַמְקַטְרֵג הַזֶּה מִתְחַזֵּק וּמִתְגַּבֵּר כְּשֶׁהָרְשָׁעִים מְצַיְּתִים לוֹ, וְהוּא שׁוֹלֵט עֲלֵיהֶם. הָרַחֲמָן יַצִּילֵנוּ. וְאַשְׁרֵי אוֹתָם שֶׁזּוֹכִים לְנַצְּחוֹ וּלְהַכְנִיעוֹ וְלִזְכּוֹת בִּשְׁבִילוֹ לָעוֹלָם הַבָּא, וּמִתְחַזֵּק אָדָם בַּמֶּלֶךְ הַקָּדוֹשׁ תָּמִיד. עַל זֶה וַדַּאי נֶאֱמַר, (תהלים פד) אַשְׁרֵי אָדָם עוֹז לוֹ בָךְ מְסִלּוֹת בִּלְבָבָם. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522011757,"<p>רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. פָּגַשׁ בָּהֶם רַבִּי אֶלְעָזָר. עַד שֶׁרָאוּ אוֹתוֹ, יָרְדוּ כֻלָּם מִן הַחֲמוֹרִים. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי פְּנֵי הַשְּׁכִינָה רָאִיתִי, שֶׁהֲרֵי כְּשֶׁרוֹאֶה אָדָם צַדִּיקִים אוֹ זַכָּאִים שֶׁבַּדּוֹר וּפוֹגֵשׁ בָּהֶם, וַדַּאי הֵם פְּנֵי הַשְּׁכִינָה. וְלָמָּה נִקְרְאוּ פְּנֵי הַשְּׁכִינָה? מִשּׁוּם שֶׁשְּׁכִינָה מִסְתַּתֶּרֶת בְּתוֹכָם, הִיא בַסֵּתֶר, וְהֵם בְּגָלוּי. מִשּׁוּם שֶׁהֵם קְרוֹבִים שֶׁל הַשְּׁכִינָה, הֵם נִקְרָאִים פָּנִים שֶׁלָּהּ. וּמִי הֵם? אוֹתָם שֶׁהִיא הִתְתַּקְּנָה עִמָּם לְהֵרָאוֹת אֵצֶל הַמֶּלֶךְ הָעֶלְיוֹן. וְהוֹאִיל וְאַתֶּם כָּאן, וַדַּאי שֶׁשְּׁכִינָה הִתְתַּקְּנָה עֲלֵיכֶם וְאַתֶּם פָּנֶיהָ. (ופגש בהם ודאי רואה פני השכינה, משום שהשכינה מסתתרת בתוכם, היאבסתרוהםבגלוי, והיאנתקנת עמםלהראות לפני המלך. והואיל ואתם כאן שלשה, ודאי שהשכינה נתקנה עליכם ושורה בתוככם).</p>"],[9522011758,"<p>פָּתַח וְאָמַר, (בראשית לג) קַח נָא אֶת בִּרְכָתִי אֲשֶׁר הֻבָאת לָךְ וְגוֹ'. כְּשֶׁרָאָה יַעֲקֹב אֶת סָמָאֵל מְקַטְרֵג בְּאוֹתוֹ לַיְלָה, רָאָה אוֹתוֹ בִּדְמוּת עֵשָׂו, וְלֹא הִכִּיר בּוֹ עַד שֶׁעָלָה הַבֹּקֶר. כֵּיוָן שֶׁעָלָה הַבֹּקֶר וְהִשְׁגִּיחַ בּוֹ, רָאָה אוֹתוֹ בְּפָנִים נִסְתָּרִים וּגְלוּיִים. הִתְבּוֹנֵן בְּאוֹתָהּ דְּמוּת שֶׁהָיְתָה כִדְמוּת עֵשָׂו, מִיָּד הִשְׁגִּיחַ וְיָדַע שֶׁהָיָה מְמֻנֶּה שֶׁל עֵשָׂו וְהֶחֱזִיק בּוֹ. מַה כָּתוּב? (שם לד) וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר. וְהַחֲבֵרִים הֵעִירוּ, שֶׁבִּשְׁבִיל שֶׁהִגִּיעַ זְמַנּוֹ לְזַמֵּר וּלְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה כִּי עָלָה הַשָּׁחַר.</p>\n<p>וְכָאן יֵשׁ לְהִסְתַּכֵּל, שֶׁוַּדַּאי שִׁלְטוֹנוֹ אֵינוֹ אֶלָּא בַּלַּיְלָה בְּתוֹךְ הַחֲשֵׁכָה, וְסוֹד זֶה - מִפַּחַד בַּלֵּילוֹת, זֶה פַּחַד הַגֵּיהִנֹּם. וּמַה שֶּׁאָמַר בַּלֵּילוֹת, רָצָה לוֹמַר הוּא וּנְקֵבָתוֹ. וּבִשְׁבִיל כָּךְ לֹא שׁוֹלֵט אֶלָּא בַּלַּיְלָה.</p>\n<p>וְזְהִ שֶׁאָמַר וַיֹּאמֶר שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר. מַה זֶּה כִּי עָלָה הַשָּׁחַר? מִשּׁוּם שֶׁכְּשֶׁמַּגִּיעַ הַבֹּקֶר וְעוֹבֵר שִׁלְטוֹנוֹ שֶׁל הַחֹשֶׁךְ שֶׁל הַלַּיְלָה, אָז נִכְנָס הוּא וְאוּכְלוּסָיו בְּנֶקֶב תְּהוֹם רַבָּה שֶׁלְּצַד צָפוֹן, עַד שֶׁנִּכְנָס הַלַּיְלָה, וְנִשְׁאָרִים הַכְּלָבִים, וְשׁוֹלְטִים וּמְשׁוֹטְטִים בַּלַּיְלָה (בעולם) עַד שֶׁבָּא הַבֹּקֶר. וְלָכֵן הָיָה דּוֹחֵק לוֹמַר, שַׁלְּחֵנִי כִּי עָלָה הַשָּׁחַר, שֶׁהֲרֵי לֹא שׁוֹלֵט בַּיּוֹם.</p>\n<p>כְּמוֹ זֶה גָּלוּתָם שֶׁל יִשְׂרָאֵל, שֶׁהִיא בַּלַּיְלָה וְנִקְרֵאת לַיְלָה. מֶלֶךְ עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת רָשָׁע שׁוֹלֵט עַל יִשְׂרָאֵל, עַד שֶׁיָּבֹא הַבֹּקֶר וְיָאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְיַעֲבֹר שִׁלְטוֹנָם, וְעַל זֶה כִּי עָלָה הַשָּׁחַר. דָּחוּק הָיָה בְיָדוֹ וְתָשַׁשׁ כֹּחוֹ, שֶׁהֲרֵי עָבַר הַלַּיְלָה. וְעַל זֶה יַעֲקֹב הֶחֱזִיק בּוֹ וְרָאָה דְיוֹקְנוֹ כִּדְיוֹקְנוֹ שֶׁל עֵשָׂו, אֲבָל לֹא כָּל כָּךְ בְּגִלּוּי, וְאָז הוֹדָה לוֹ עַל הַבְּרָכוֹת.</p>\n<p>מַה כָּתוּב אַחֲרֵי זֶה? (שם לג) כִּי עַל כֵּן רָאִיתִי פָנֶיךְ כִּרְאֹת פְּנֵי אֱלֹהִים וַתִּרְצֵנִי. שֶׁרָאָה בְּאוֹתָם הַפָּנִים שֶׁל עֵשָׂו כִּדְמוּת שֶׁנִּרְאֶה לוֹ סָמָאֵל מַמָּשׁ, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁאָדָם נִקְשָׁר, כָּךְ נִרְאִים פָּנָיו. וְאַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, שְׁכִינָה עִמָּכֶם, וּפְנֵיכֶם כְּאוֹתָם הַפָּנִים שֶׁלָּהּ, אַשְׁרֵיכֶם! אָמַר, אִם בַּדֶּרֶךְ הַזּוֹ הָיִיתִי הוֹלֵךְ עִמָּכֶם, הָיִיתִי יוֹשֵׁב עִמָּכֶם. כָּעֵת שֶׁאַתֶּם לְדַרְכְּכֶם וַאֲנִי לְדַרְכִּי, אֶפָּרֵד מִכֶּם בְּדִבְרֵי תוֹרָה.</p>"],[9522011759,"<p>פָּתַח וְאָמַר, (תהלים קכז) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. וְכִי שְׁלֹמֹה אָמַר הַתִּשְׁבַּחַת הַזּוֹ כְּשֶׁבָּנָה אֶת בֵּית הַמִּקְדָּשׁ? לֹא כָּךְ, שֶׁהֲרֵי דָּוִד הַמֶּלֶךְ אָמַר לוֹ בִּשְׁבִיל שְׁלֹמֹה בְּנוֹ, כְּשֶׁבָּא נָתָן אֶצְלוֹ וְאָמַר לוֹ עַל שְׁלֹמֹה שֶׁהוּא יִבְנֶה אֶת בֵּית הַמִּקְדָּשׁ. וְאַחַר כָּךְ דָּוִד הַמֶּלֶךְ הֶרְאָה לִשְׁלֹמֹה בְנוֹ אֶת דְּיוֹקַן בֵּית הַמִּקְדָּשׁ. כֵּיוָן שֶׁרָאָה דָוִד אֶת דְּיוֹקַן בֵּית הַמִּקְדָּשׁ וְכָל תִּקּוּנָיו, אָמַר שִׁירָה עַל שְׁלֹמֹה בְנוֹ, וְאָמַר אִם ה' לֹא יִבְנֶה בַיִת וְגוֹ'.</p>\n<p>דָּבָר אַחֵר שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה - לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ. וְשִׁירָה זוֹ הִיא שִׁירָה וְתִשְׁבַּחַת עַל כָּל שְׁאָר הַשִּׁירָה, וְשִׁירָה זוֹ עוֹלָה עַל כֻּלָּן. אִם ה' לֹא יִבְנֶה בַיִת - שֶׁרָאָה דָוִד הַמֶּלֶךְ אֶת כָּל אוֹתָם שִׁבְעַת הָעַמּוּדִים שֶׁהַבַּיִת הַזֶּה עוֹמֵד עֲלֵיהֶם שֶׁעוֹמְדִים שׁוּרוֹת שׁוּרוֹת לִבְנוֹת אֶת הַבַּיִת הַזֶּה. מֵעַל כֻּלָּם עוֹמֵד בַּעַל הַבַּיִת שֶׁהוֹלֵךְ עַל גַּבֵּיהֶם, וְנוֹתֵן לָהֶם כֹּחַ וְתֹקֶף לְכָל אֶחָד וְאֶחָד כָּרָאוּי.</p>\n<p>וְעַל זֶה אָמַר דָּוִד, אִם הַמֶּלֶךְ הַזֶּה שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ, שֶׁהוּא בַּעַל הַבַּיִת, לֹא בוֹנֶה אֶת הַבַּיִת הַזֶּה - שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, אוֹתָם עַמּוּדִים שֶׁעוֹמְדִים לִבְנוֹת עַל הַבַּיִת הַזֶּה. אִם ה' לֹא יִשְׁמָר עִיר - זֶה הַמֶּלֶךְ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ. שָׁוְא שָׁקַד שׁוֹמֵר - זֶהוּ עַמּוּד אֶחָד שֶׁהָעוֹלָם הִתְתַּקֵּן עָלָיו, וּמִיהוּ? צַדִּיק, שֶׁהֲרֵי הוּא שׁוֹמֵר אֶת אוֹתָהּ הָעִיר.</p>\n<p>הַמִּשְׁכָּן שֶׁעָשָׂה מֹשֶׁה, תָּמִיד הָיָה יְהוֹשֻׁעַ עוֹמֵד וְשׁוֹמֵר אוֹתוֹ, שֶׁהֲרֵי אֵין שְׁמִירָתוֹ - רַק בָּזֶה שֶׁנִּקְרָא נַעַר, שֶׁכָּתוּב (שמות לג) וּמְשָׁרַתוֹ יְהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל. אַחַר כָּךְ מִשְׁכָּן זֶה לֹא הָיָה שָׁמוּר אֶלָּא בִּשְׁבִיל נַעַר אַחֵר, שֶׁכָּתוּב (שמואל א ג) וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת. (והיה מסדר שם) מִשּׁוּם שֶׁאֵין שְׁמִירַת הַמִּשְׁכָּן אֶלָּא בְּנַעַר. (אבל בית המקדש אינו כך, שאין שמירתו אלא בקדוש'ברוך'הוא, שכתוב אם ה' לא ישמר עיר שוא שקד שומר) וּמִיהוּ הַשּׁוֹמֵר הַזֶּה? אוֹתוֹ שֶׁשּׁוֹמֵר הַמִּשְׁכָּן שֶׁנִּקְרָא כָּךְ: נַעַר מְטַטְרוֹ\"ן.</p>\n<p>אֲבָל אַתֶּם קְדוֹשִׁים עֶלְיוֹנִים, אֵין שְׁמִירַתְכֶם כְּמוֹ שְׁמִירַת הַמִּשְׁכָּן, אֶלָּא שְׁמִירַתְכֶם כִּשְׁמִירַת בֵּית הַמִּקְדָּשׁ, הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ, שֶׁכָּתוּב אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. שֶׁהֲרֵי בְּכָל זְמַן שֶׁצַדִּיקִים הוֹלְכִים בַּדֶּרֶךְ, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם תָּמִיד, שֶׁכָּתוּב ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ.</p>\n<p>הָלְכוּ אַחֲרָיו, וְלִוּוּ אוֹתוֹ שְׁלֹשָׁה מִילִים, וְחָזְרוּ לְדַרְכָּם. קָרְאוּ עָלָיו, (תהלים צא) כִּי מַלְאָכָיו יְצַוֶּה לָּךְ לִשְׁמָרְךְ בְּכָל דְּרָכֶיךְ, עַל כַּפַּיִם יִשָּׂאוּנְךְ וְגוֹ'. (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְתָגֵל יוֹלַדְתֶּךְ.</p>"],[9522011760,"<p>וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעֹת וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (שם יד) בְּרָב עַם הַדְרַת מֶלֶךְ וּבְאֶפֶס לְאֹם מְחִתַּת רָזוֹן. בְּרָב עַם הַדְרַת מֶלֶךְ - אֵלֶּה הֵם יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם (דברים ז) כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ. וְהֵם עַם שֶׁעוֹלִים לְכַמָּה אֲלָפִים וּלְכַמָּה רְבָבוֹת, וּכְשֶׁהֵם רַבִּים בְּחֶשְׁבּוֹנָם, זֶהוּ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים מְשַׁבְּחִים אֶת שְׁמוֹ שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן וּמְשַׁבְּחִים אוֹתוֹ בִּשְׁבִיל הָעָם הַקָּדוֹשׁ הַזֶּה. זֶהוּ שֶׁכָּתוּב (שם ד) רַק עַם חָכָם וְנָבוֹן הַגּוֹי הַגָּדוֹל הַזֶּה.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (שם ז) כִּי אַתֶּם הַמְעַט מִכָּל הָעַמִּים - אֶלָּא, מִכָּל הָעַמִּים וַדַּאי, אֲבָל מֵעַם אֶחָד הֵם יוֹתֵר רַבִּים. שֶׁהֲרֵי אֵין עַם בְּכָל הָעוֹלָם גָּדוֹל וָרַב כְּיִשְׂרָאֵל. וְאִם תֹּאמַר, הֲרֵי בְּנֵי יִשְׁמָעֵאל וַהֲרֵי בְּנֵי אֱדוֹם הֲרֵי כַּמָּה הֵם - וַדַּאי כָּךְ רַבִּים הֵם, אֲבָל כָּל שְׁאָר הָעַמִּים, כֻּלָּם מְעֹרָבִים אֵלֶּה בְּאֵלֶּה, בָּנִים יֵשׁ לְעַם זֶה בְּעַם זֶה, וּלְאֵלֶּה בָּנִים בְּעַם אַחֵר וּלְאֵלֶּה בְּאַחֵר. וּמִשּׁוּם כָּךְ אֵין עַם בְּכָל הָעוֹלָם גָּדוֹל וָרַב כְּיִשְׂרָאֵל, עַם נִבְחָר וִיחִידִי, אֵלֶּה בְּאֵלֶּה בְּלִי עִרְבּוּבְיָה אַחֶרֶת כְּלָל, שֶׁכָּתוּב כִּי עַם קָדוֹשׁ אַתָּה לַה' אֱלֹהֶיךְ וּבְךְ בָּחַר ה', וְעַל זֶה בְּרָב עַם הַדְרַת מֶלֶךְ, הִדּוּר הוּא לַמֶּלֶךְ הָעֶלְיוֹן בַּקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>עוֹד, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְבֵית הַכְּנֶסֶת (שהוא מקדש מעט) וְכָל הָעָם הוֹלְכִים כְּאֶחָד וּמִתְפַּלְלִים וּמוֹדִים וּמְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲזַי הוּא הִדּוּרוֹ שֶׁל מֶלֶךְ, שֶׁמֶּלֶךְ סְתָם זֶה מֶלֶךְ הַקָּדוֹשׁ (המשיח), שֶׁהִתְתַּקֵּן בְּיֹפִי וְתִקּוּן לַעֲלוֹת לְמַעְלָה.</p>\n<p>וּבְאֶפֶס לְאֹם מְחִתַּת רָזוֹן - וּכְשֶׁהוּא מַקְדִּים לְבֵית הַכְּנֶסֶת וְהָעָם לֹא בָאִים לְהִתְפַּלֵּל וּלְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז כָּל אוֹתוֹ שִׁלְטוֹן שֶׁלְּמַעְלָה וְכָל אוֹתָם מְמֻנִּים וּמַחֲנוֹת עֶלְיוֹנִים, כֻּלָּם נִשְׁבָּרִים (מעברים) מֵאוֹתוֹ עִלּוּי שֶׁמִּתְתַּקְּנִים בְּתִקּוּנֵי אוֹתוֹ הַמֶּלֶךְ.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁבְּאוֹתָהּ שָׁעָה שֶׁיִּשְׂרָאֵל לְמַטָּה מְסַדְּרִים תְּפִלּוֹתֵיהֶם וּבַקָּשׁוֹתֵיהֶם וּמְשַׁבְּחִים אֶת הַמֶּלֶךְ הָעֶלְיוֹן, כָּל אוֹתָם מַחֲנוֹת עֶלְיוֹנִים מְסַדְּרִים שְׁבָחִים וּמִתְתַּקְּנִים בְּאוֹתוֹ תִּקּוּן קָדוֹשׁ, מִשּׁוּם שֶׁכָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים כֻּלָּם חֲבֵרִים עִם יִשְׂרָאֵל לְמַטָּה לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כְּאֶחָד, לִהְיוֹת עֲלִיָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַעְלָה וּמַטָּה כְּאֶחָד.</p>\n<p>וּכְשֶׁהֵם מִזְדַּמְּנִים לִהְיוֹת חֲבֵרִים עִם יִשְׂרָאֵל, וְיִשְׂרָאֵל לְמַטָּה לֹא בָאִים לְסַדֵּר תְּפִלָּתָם וּבַקָּשָׁתָם וּלְשַׁבֵּחַ אֶת אֲדוֹנָם - כָּל הַמַּחֲנוֹת הַקְּדוֹשִׁים שֶׁל הַשִּׁלְטוֹן הָעֶלְיוֹן נִשְׁבָּרִים (מעברים) מִתִּקּוּנֵיהֶם, שֶׁהֲרֵי לֹא עוֹלִים בַּעֲלִיָּה וְלֹא יְכוֹלִים לְשַׁבֵּחַ אֶת רִבּוֹנָם כָּרָאוּי. מִשּׁוּם שֶׁשִּׁבְחֵי הַקָּדוֹשׁ בָּרוּךְ הוּא צְרִיכִים לִהְיוֹת כְּאֶחָד מַעְלָה וּמַטָּה, עֶלְיוֹנִים וְתַחְתּוֹנִים בְּשָׁעָה אַחַת, וְעַל זֶה מְחִתַּת רָזוֹן וְלֹא מְחִתַּת מֶלֶךְ.</p>\n<p>וַאֲפִלּוּ שֶׁלֹּא הִתְרַבּוּ בְּבֵית הַכְּנֶסֶת אֶלָּא עֲשָׂרָה, בְּאוֹתָם הָעֲשָׂרָה מִזְדַּמְּנִים הַמַּחֲנוֹת הָעֶלְיוֹנִים לִהְיוֹת עִמָּהֶם חֲבֵרִים. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל תִּקּוּנֵי אוֹתוֹ הַמֶּלֶךְ הֵם בַּעֲשָׂרָה, וְלָכֵן דַּי בַּעֲשָׂרָה, אִם אֵינָם יוֹתֵר.</p>"],[9522011761,"<p>וּבֹא רְאֵה, בַּמִּשְׁכָּן מַה כָּתוּב? וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעֹת. עֶשֶׂר, מִשּׁוּם שֶׁתִּקּוּן הַמִּשְׁכָּן (השכינה) הוּא בַּעֲשָׂרָה לִהְיוֹת כָּרָאוּי. עֶשֶׂר, מָה הַטַּעַם עֶשֶׂר וְלֹא עֲשָׂרָה? אֶלָּא עֶשֶׂר בְּכָל מָקוֹם הוּא בְּלִי שְׁכִינָה, שֶׁאֵינָהּ בַּחֶשְׁבּוֹן, כְּגוֹן זֶה (מלכים א ז) עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר. הַשְּׁכִינָה אֵינָהּ בַּחֶשְׁבּוֹן, שֶׁהֲרֵי הִיא עוֹמֶדֶת לְמַעְלָה, שֶׁכָּתוּב (שם) וְהַיָּם עֲלֵיהֶם מִלְמָעְלָה. וּבַמְּקוֹמוֹת הַלָּלוּ שֶׁל רְמָזִים לַסּוֹד שֶׁלְּמַעְלָה שֶׁחָסֵר מֵהֶם (ה'), הֲרֵי שְׁכִינָה יְתֵרָה עַל אוֹתוֹ חֶשְׁבּוֹן, שֶׁאֵינָהּ בַּחֶשְׁבּוֹן.</p>\n<p>לַצַד הָאַחֵר נוֹתְנִים חֶשְׁבּוֹן יוֹתֵר. וְהִיא בַּמִּנְיָן בִּגְרִיעוּת, (לא תאמר חשבון יותר, אלא תוספת אות, והחשבון בגריעות) כְּמוֹ עַשְׁתֵּי, וַהֲרֵי פֵּרְשׁוּהָ. וּבְכָל מָקוֹם שֶׁנּוֹסָפוֹת אוֹתִיּוֹת כְּגוֹן זֶה, זֶה לִגְרִיעוּת. כְּמוֹ הַאֲמִינוֹן אָחִיךְ, שֶׁמַּסְפִּיק אַמְנוֹן. וּבְצַד הַקְּדֻשָּׁה גּוֹרֵעַ אוֹת, וְהִיא תוֹסֶפֶת.</p>"],[9522011762,"<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קד) עֹטֶה אוֹר כַּשַּׂלְמָה נוֹטֶה שָׁמַיִם כַּיְרִיעָה. פָּסוּק זֶה פֵּרְשׁוּהוּ, שֶׁכְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִתְעַטֵּף בְּאוֹתוֹ אוֹר קַדְמוֹן וּבָרָא בּוֹ שָׁמַיִם.</p>\n<p>וּבֹא רְאֵה, אוֹר וְחֹשֶׁךְ (לא) הָיוּ כְאֶחָד. אוֹר מִצַּד הַיָּמִין, וְחֹשֶׁךְ מִצַּד הַשְּׂמֹאל. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? שִׁתְּפָם כְּאֶחָד וּבָרָא מֵהֶם שָׁמַיִם. מַה זֶּה שָׁמַיִם? אֵשׁ וּמַיִם שִׁתְּפָם כְּאֶחָד וְעָשָׂה שָׁלוֹם בֵּינֵיהֶם.</p>\n<p>וּכְשֶׁנִּתְקְנוּ כְאֶחָד וּמָתַח אוֹתָם, מָתַח אוֹתָם כַּיְרִיעָה וְעָשָׂה מֵהֶם אוֹת ו', וְזוֹ נִקְרֵאת יְרִיעָה. יְרִיעוֹת, שֶׁהֲרֵי מֵאוֹת זוֹ הִתְפַּשֵּׁט אוֹר וְנַעֲשׂוּ יְרִיעוֹת. זֶהוּ שֶׁכָּתוּב וְאֶת הַמִּשְׁכָּן תַּעֲשֶׂה עֶשֶׂר יְרִיעֹת.</p>\n<p>וְשִׁבְעָה רְקִיעִים הֵם מְתוּחִים, גְּנוּזִים בִּגְנִיזָה עֶלְיוֹנָה, כְּמוֹ שֶׁבֵּאֲרוּהָ, וְרָקִיעַ אֶחָד שֶׁעוֹמֵד עֲלֵיהֶם. וּלְאוֹתוֹ רָקִיעַ אֵין גָּוֶן וְאֵין לוֹ מָקוֹם בְּגִלּוּי, וְלֹא עוֹמֵד לְהִתְבּוֹנֵן בּוֹ (אלא בתבונה), וְהָרָקִיעַ הַזֶּה גָּנוּז וּמֵאִיר לְכֻלָּם, וּמַסִּיעַ אוֹתָם לְמַסְעֵיהֶם, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. אֶלָּא עוֹמֵד בְּהַשְׂכֵּל.</p>\n<p>מֵהָרָקִיעַ הַזֶּה וָהָלְאָה אֵין מִי שֶׁיֵּדַע וְיַשְׁגִּיחַ, וְיֵשׁ לָאָדָם לִסְתֹּם פִּיו וְלֹא לְדַבֵּר וּלְהִתְבּוֹנֵן בְּהַשְׂכֵּל. מִי שֶׁיִּסְתַּכֵּל חוֹזֵר לְאָחוֹר, שֶׁאֵין מִי שֶׁיָּכוֹל לָדַעַת.</p>\n<p>עָשֶׂר יְרִיעוֹת הֵן, שֶׁהֵם עֲשָׂרָה רְקִיעִים. וּמִי הֵם יְרִיעוֹת הַמִּשְׁכָּן שֶׁהֵן עֶשֶׂר וְעוֹמְדוֹת לְהִוָּדַע לְחַכְמֵי הַלֵּב? מִי שֶׁיֵּדַע בָּהֶן, מִסְתַּכֵּל בְּחָכְמָה רַבָּה וּבַסּוֹדוֹת שֶׁל הָעוֹלָם, וּמִסְתַּכֵּל לְמַעְלָה בְּאוֹתוֹ מָקוֹם, שֶׁכָּל אֶחָד וְאֶחָד נִדְבָּק בּוֹ, פְּרָט לִשְׁנֵי אֵלֶּה שֶׁעוֹמְדִים בְּיָמִין וּבִשְׂמֹאל, וְהֵם גְּנוּזִים עִם הַשְּׁכִינָה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, תִּשְׁעָה רְקִיעִים הֵם, וּשְׁכִינָה הִיא עֲשִׂירִית. שֶׁאִם תֹּאמַר בִּשְׁבִיל שֶׁכָּתוּב עֶשֶׂר - הוּא חוּץ מֵהַשְּׁכִינָה. אִם כָּךְ, הַשְּׁכִינָה הִיא אַחַת עֶשְׂרֵה שֶׁעוֹמֶדֶת עַל עֶשֶׂר. אֶלָּא וַדַּאי שֶׁתֵּשַׁע הֵן, וְהֵם תִּשְׁעָה יָמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים, וְהִיא הָעֲשִׂירִית. כְּמוֹ זֶה הַמִּשְׁכָּן הוּא עֶשֶׂר יְרִיעוֹת.</p>\n<p>אוֹתָם עֲשָׂרָה רְקִיעִים סוֹד הַסּוֹדוֹת שֶׁלֹּא נִמְסָר, רַק לְיוֹדְעֵי הַחָכְמָה, וְהַכֹּל הוּא בַּסּוֹדוֹת שֶׁל הַמְּנוֹרָה הַקְּדוֹשָׁה, שֶׁהוּא גִּלָּה סוֹד כָּל רָקִיעַ וְרָקִיעַ, וְהֵם שַׁמָּשִׁים שֶׁמְּשַׁמְּשִׁים בְּכָל אֶחָד וְאֶחָד. שִׁבְעָה רְקִיעִים הֵם לְמַעְלָה, וְשִׁבְעָה רְקִיעִים הֵם לְמַטָּה, כְּמוֹ שֶׁלְּמַעְלָה. שִׁבְעָה רְקִיעִים הֵם שֶׁבָּהֶם כּוֹכָבִים וּמַזָּלוֹת לְהַנְהִיג הָעוֹלָם הַזֶּה כְּפִי דַרְכּוֹ וּכְמוֹ שֶׁצָּרִיךְ לוֹ.</p>"],[9522011763,"<p>בְּכֻלָּם הַשְּׁבִיעִי עָדִיף, חוּץ מִן הַשְּׁמִינִי שֶׁמַּנְהִיג אֶת כֻּלָּם וְעוֹמֵד עַל כֻּלָּם. כָּתוּב סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת. מִי רוֹכֵב בָּעֲרָבוֹת, וּמִי הֵן הָעֲרָבוֹת? אֶלָּא עֲרָבוֹת זֶה הָרָקִיעַ הַשְּׁבִיעִי, וְלָמָּה נִקְרָא עֲרָבוֹת? עַל שֶׁהוּא כָּלוּל מֵאֵשׁ וּמַיִם כְּאֶחָד, וּמִצַּד הַדָּרוֹם, וּמִצַּד הַצָּפוֹן, וְהוּא מְעֹרָב מִשְּׁנֵי צְדָדִים.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, שְׁתֵּי הָעֲרָבוֹת שֶׁמִּתְחַבְּרוֹת בַּלּוּלָב, וְשָׁנִינוּ עֲרָבוֹת. ? זֶהוּ שֶׁכָּתוּב (תהלים סח) סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת. אִם כָּךְ, מִי נוֹתֵן יְרֵכַיִם בַּגּוּף, אוֹ גוּף בַּיְרֵכַיִם? שֶׁהֲרֵי זֶה עוֹשֶׂה פֵרוֹת וְנִצָּנִים, וְזֶה לֹא עוֹשֶׂה פֵרוֹת וְנִצָּנִים.</p>\n<p>אֶלָּא וַדַּאי שֶׁהַכֹּל הוּא סוֹד שֶׁל עֲרָבוֹת שֶׁבַּלּוּלָב. אוֹתָם עֲרָבוֹת שֶׁבַּלּוּלָב, אֶחָד אֵשׁ וְאֶחָד מַיִם. בַּסּוֹד הַזֶּה שֶׁל כֻּלָּם, וְהוּא שְׁבִיעִי, הוּא אֵשׁ וּמַיִם כְּלוּלִים כְּאֶחָד בְּסוֹד אֶחָד, וּמִשּׁוּם שֶׁעֲרָבוֹת הוּא סוֹד הַכְּלָל שֶׁל כָּל שֵׁשֶׁת הָאַחֲרוֹנִים, הוּא סוֹד הַמֶּרְכָּבָה הָעֶלְיוֹנָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָּרָקִיעַ הַזֶּה יוֹתֵר מִכָּל הָרְקִיעִים, וּתְשׁוּקָתוֹ תָּמִיד לְתַקֵּן אוֹתוֹ הָרָקִיעַ בְּיֹפִי עֶלְיוֹן. וְעַל זֶה סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת, לְאוֹתוֹ שֶׁרוֹכֵב בָּעֲרָבוֹת, וּמִיהוּ? אוֹתוֹ הָרָקִיעַ טָמִיר וְגָנוּז שֶׁעוֹמֵד עַל גַּב הַחַיּוֹת, שֶׁהוּא רוֹכֵב בָּעֲרָבוֹת.</p>\n<p>וְעִלְזוּ לְפָנָיו. לֹא כָתוּב מִלְּפָנָיו, אֶלָּא לְפָנָיו, שֶׁהֲרֵי אֵין מִי שֶׁיֵּדַע בּוֹ כְּלוּם. אֲבָל לְפָנָיו, מִי שֶׁנִּכְנָס אֵצֶל הָרָקִיעַ הַזֶּה, צָרִיךְ לְהִכָּנֵס בְּשִׂמְחָה וְלֹא בְּעֶצֶב כְּלָל, מִשּׁוּם שֶׁהָרָקִיעַ הַזֶּה גּוֹרֵם, שֶׁשָּׁם לֹא שׁוֹרֶה עֶצֶב וְרֹגֶז כְּלָל, שֶׁהֲרֵי שָׁם הַכֹּל בְּשִׂמְחָה.</p>\n<p>וְעַל זֶה, כֹּהֵן גָּדוֹל שֶׁעוֹמֵד לְפָנָיו לֹא הָיָה נִכְנָס לְבֵית הַקֹּדֶשׁ - רַק בְּשִׂמְחָה וּלְהַרְאוֹת שִׂמְחָה, שֶׁהֲרֵי הַמָּקוֹם גּוֹרֵם. וְעַל זֶה כָּתוּב (תהלים ק) עבדו את ה' בשמחה באו לפניו ברננה. שהרי צריך שלא להראות בו עצב.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, מִי שֶׁהוּא בְצַעַר וְדחַק, שֶׁלֹּא יָכוֹל לְשַׂמֵּחַ אֶת לִבּוֹ, וּמִתּוֹךְ דָּחְקוֹ יֵשׁ לוֹ לְבַקֵּשׁ רַחֲמִים לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. אִם כָּךְ, לֹא יִתְפַּלֵּל תְּפִלָּה כְּלָל, וְלֹא יִכָּנֵס בְּעֶצֶב כְּלָל, שֶׁהֲרֵי לֹא יָכוֹל לְשַׂמֵּחַ אֶת לִבּוֹ וּלְהִכָּנֵס לְפָנָיו בְּשִׂמְחָה. מָה הַתִּקּוּן שֶׁיֵּשׁ לָאָדָם הַזֶּה?</p>\n<p>אֶלָּא וַדַּאי הֲרֵי שָׁנִינוּ, כָּל הַשְּׁעָרִים נִנְעֲלוּ וְנִסְגְּרוּ, וְשַׁעֲרֵי דְמָעוֹת לֹא נִסְגְּרוּ, וְאֵין דִּמְעָה אֶלָּא מִתּוֹךְ צַעַר וְעֶצֶב, וְכָל אוֹתָם הַמְמֻנִּים עַל אוֹתָם הַשְּׁעָרִים, כֻּלָּם מְשַׁבְּרִים חֲתִיכוֹת קָשׁוֹת וּמַנְעוּלִים וּמַכְנִיסִים אוֹתָן דְּמָעוֹת, וְאוֹתָהּ תְּפִלָּה נִכְנֶסֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>וְאָז לְאוֹתוֹ מָקוֹם יֵשׁ דּחַק מֵאוֹתוֹ עֶצֶב וְדחַק שֶׁל אוֹתוֹ אָדָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה סג) בְּכָל צָרָתָם לא (לו) צָר. תְּשׁוּקַת אוֹתוֹ הָעוֹלָם הָעֶלְיוֹן לַמָּקוֹם הַזֶה, כְּזָכָר שֶׁתְּשׁוּקָתוֹ תָּמִיד אֶל הַנְּקֵבָה. כְּשֶׁנִּכְנָס הַמֶּלֶךְ לַגְּבִירָה וּמוֹצֵא אוֹתָהּ בְּעֶצֶב, אָז כָּל מַה שֶּׁהִיא רוֹצָה, נִמְסָר בְּיָדֶיהָ, וְאוֹתוֹ אָדָם וְאוֹתָהּ תְּפִלָּה לֹא חוֹזֶרֶת רֵיקָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁשּׁוֹפֵךְ דְּמָעוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְפִלָּתוֹ.</p>\n<p>כְּמוֹ זֶה בְּשַׁבָּת, מִי שֶׁיּוֹשֵׁב בְּתַעֲנִית בְּשַׁבָּת, מִתּוֹךְ צַעֲרוֹ מַרְאֶה עֶצֶב, וּבְשַׁבָּת שׁוֹלֵט אוֹתוֹ רָקִיעַ עֶלְיוֹן, אוֹתוֹ שֶׁנִּרְאֶה בְשִׂמְחָה, שֶׁהוּא שִׂמְחָה וּמְשַׂמֵּחַ לַכֹּל. אוֹתוֹ שֶׁיּוֹשֵׁב בְּעֶצֶב, מִשּׁוּם שֶׁהוּא שׁוֹלֵט, מוֹצִיא אֶת אוֹתוֹ הָאָדָם מֵאוֹתוֹ הָעֹנֶשׁ שֶׁנִּגְזַר עָלָיו, וַהֲרֵי נֶאֱמַר סֹלּוּ - הָבוּ כָבוֹד וְרוֹמְמוּת לְאוֹתוֹ שֶׁרוֹכֵב בָּעֲרָבוֹת, שֶׁהוּא שִׂמְחָה וּמְשַׂמֵּחַ לַכֹּל, הָרָקִיעַ שֶׁעַל גַּבֵּי הַחַיּוֹת בְּיָ\"הּ שְׁמוֹ וַדַּאי, שֶׁהֲרֵי בְּאוֹתוֹ מָקוֹם הַשֵּׁם הַזֶּה נִכְלָל. וְעִלְזוּ לְפָנָיו - מִשּׁוּם שֶׁלֹּא צָרִיךְ לְהַרְאוֹת לְפָנָיו עֶצֶב, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, פָּסוּק זֶה כָּךְ צָרִיךְ לוֹמַר: סֹלּוּ לָרֹכֵב עַל עֲרָבוֹת. מַה זֶּה בָּעֲרָבוֹת? בְּיָהּ שְׁמוֹ, בְּיָהּ הוּא הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה שְׁמוֹ? אֶלָּא פָּסוּק זֶה עַל נִסְתַּר כָּל הַנִּסְתָּרִים, עַתִּיק כָּל הָעַתִּיקִים נֶאֱמַר, אוֹתוֹ שֶׁלֹּא הִתְגַּלָּה וְלֹא נוֹדַע כְּלָל שֶׁהוּא רוֹכֵב בָּעֲרָבוֹת. וְאִם תֹּאמַר שֶׁהוּא בָּא וְרוֹכֵב בּוֹ, אִם כָּךְ, אַף עַל גַּב שֶׁהוּא נִסְתָּר, בַּמָּקוֹם הַזֶּה עוֹמֵד לְהִתְגַּלּוֹת.</p>\n<p>אֶלָּא סֹלּוּ לָרֹכֵב בָּעֲרָבוֹת, זֶהוּ עַתִּיק שֶׁל כָּל הָעַתִּיקִים, נִסְתַּר כָּל הַנִּסְתָּרִים, שֶׁלֹּא יָדוּעַ. וּבַמָּה הוּא רוֹכֵב? בָּעֲרָבוֹת, בְּיָ\"הּ, שֶׁהוּא סוֹד קַדְמוֹן שֶׁיָּצָא לְפָנָיו (ממגו), וְזֶהוּ שְׁמוֹ. מֵאוֹתוֹ נִסְתָּר שֶׁלֹּא יָדוּעַ שְׁמוֹ הוּא יָ\"הּ. לֹא שֶׁהוּא הוּא, אֶלָּא הוּא הוּא, בִּשְׁבִיל שֶׁאוֹתָהּ פָּרֹכֶת שֶׁנִּפְרְסָה וְיָצְאָה מִלְּפָנָיו. אֲבָל הַפָּרֹכֶת הַזּוֹ הִיא שְׁמוֹ, וְזוֹהִי מֶרְכַּבְתּוֹ, וְלֹא נוֹדָע כְּלָל.</p>\n<p>וְזְהִוּ שְׁמוֹ הַגָּדוֹל, מִשּׁוּם שֶׁיֵּשׁ שְׁמוֹ שֶׁאֵינוֹ כָּל כָּךְ גָּדוֹל כְּמוֹ זֶה אַף עַל גַּב שֶׁיֵּשׁ בּוֹ תּוֹסֶפֶת אוֹתִיּוֹת. זֶהוּ הַשֵּׁם הַגָּדוֹל, וְלָכֵן בַּשֵּׁם הַזֶּה אָנוּ מוֹצִיאִים אָמֵן, שֶׁהוּא מִמֶּנּוּ. בָּזֶה הוֹלֵךְ אָמֵן בְּכָל הַזְּמַן, וּבְשֵׁם אַחֵר לֹא כָּךְ.</p>\n<p>אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ, שֶׁכַּאֲשֶׁר הַשֵּׁם הַזֶּה מִתְתַּקֵּן - הַכֹּל בִּשְׁלֵמוּת, וְכָל הָעוֹלָמוֹת שְׂמֵחִים בְּשִׂמְחָה. בַּשֵּׁם הַזֶּה כְּלוּלִים עֶלְיוֹנִים וְתַחְתּוֹנִים. בַּשֵּׁם הַזֶּה כְּלוּלִים שֵׁשׁ מֵאוֹת וּשְׁלֹשׁ עֶשְׂרֵה מִצְווֹת שֶׁל הַתּוֹרָה שֶׁהֵן הַכְּלָל שֶׁל כָּל הַסּוֹדוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים. הַכְּלָל שֶׁל עוֹלַם הַזָּכָר לְמַעְלָה, וְהַכְּלָל שֶׁל עוֹלַם הַנְּקֵבָה לְמַטָּה.</p>\n<p>וְכָל הַמִּצְווֹת כֻּלָּן פְּרָקִים וְאֵיבָרִים, לְהַרְאוֹת בָּהֶן אֶת סוֹד הָאֱמוּנָה. מִי שֶׁלֹּא יַשְׁגִּיחַ וְלֹא יִתְבּוֹנֵן בַּסּוֹדוֹת שֶׁל מִצְווֹת הַתּוֹרָה, לֹא יֵדַע וְלֹא יִתְבּוֹנֵן אֵיךְ מְתֻקָּנִים הָאֵיבָרִים בְּסוֹד עֶלְיוֹן. כָּל אֵיבְרֵי הַגּוּף מְתֻקָּנִים עַל הַסּוֹד שֶׁל מִצְווֹת הַתּוֹרָה, וְאַף עַל גַּב שֶׁיֵּשׁ אֵיבָרִים שֶׁהֵם גְּדוֹלִים וְעֶלְיוֹנִים, כֻּלָּם קְטַנִּים וּגְדוֹלִים, אִם נִטָּל מֵהֶם אֶחָד, אֲפִלּוּ הַקָּטָן בְּיוֹתֵר שֶׁל הָאָדָם, הוּא נִקְרָא בַּעַל מוּם. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן אוֹתוֹ שֶׁפּוֹגֵם אֲפִלּוּ מִצְוָה אַחַת מֵאוֹתָן מִצְווֹת הַתּוֹרָה, שֶׁמַּטִּיל מוּם בְּמָקוֹם שֶׁלֹּא צָרִיךְ.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (בראשית ב) וַיִּקַּח ה' אֱלֹהִים אֶת הָאָדָם וַיַּנִּחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ. וְשָׁנִינוּ, לְעָבְדָהּ וּלְשָׁמְרָהּ - אֵלּוּ קָרְבָּנוֹת, וְהַכֹּל אֶחָד. אֲבָל הַסּוֹד הַזֶּה שֶׁל מִצְווֹת הַתּוֹרָה, לְעָבְדָהּ - אֵלּוּ רְמַ\"ח אֵיבָרִים עֶלְיוֹנִים. וּלְשָׁמְרָהּ - אֵלּוּ שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה אֵיבָרִים תַּחְתּוֹנִים. אֵלֶּה הָעֶלְיוֹנִים שֶׁל זָכוֹר, וְאֵלֶּה הַתַּחְתּוֹנִים שֶׁל שָׁמוֹר, וְהַכֹּל אֶחָד.</p>\n<p>אַשְׁרֵי מִי שֶׁזּוֹכֶה לְהַשְׁלִים אוֹתָם. מִצְווֹת הַתּוֹרָה גּוֹרְמוֹת לָאָדָם לְהַשְׁלִים רוּחוֹ וְנִשְׁמָתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. הַתּוֹרָה מְזַכָּה אֶת הָאָדָם לָרֶשֶׁת שְׁנֵי עוֹלָמוֹת, עוֹלָם הַזֶּה וְעוֹלָם הַבָּא. כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, מִשְׁתַּדֵּל בַּחַיִּים. חַיִּים בָּעוֹלָם הַזֶּה, וְחַיִּים בָּעוֹלָם הַבָּא. נִצּוֹל מִכָּל הָעֳנָשִׁים הָרָעִים שֶׁלֹּא יְכוֹלִים לִשְׁלֹט עָלָיו. אִם בְּהִשְׁתַּדְּלוּת כָּךְ, כָּל שֶׁכֵּן מִי שֶׁעוֹשֶׂה מַעֲשֶׂה.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי אַבָּא הָיוּ שְׁרוּיִים בְּבֵית מְאָרְחֵיהֶם, וְקָמוּ בַּחֲצוֹת הַלַּיְלָה לְהִשְׁתַּדֵּל בַּתּוֹרָה. בַּת הַמְאָרֵחַ קָמָה וְהֵאִירָה לָהֶם נֵר, וְאַחַר כָּךְ עָמְדָה אַחֲרֵיהֶם לִשְׁמֹעַ דִּבְרֵי תוֹרָה.</p>"],[9522011764,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (משלי ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. כִּי נֵר מִצְוָה - כָּל מִי שֶׁמִּשְׁתַּדֵּל בָּעוֹלָם הַזֶּה בְּאוֹתָן מִצְווֹת הַתּוֹרָה, מִסְתַּדֵּר לְפָנָיו בְּכָל מִצְוָה וּמִצְוָה נֵר אֶחָד לְהָאִיר לוֹ בְּאוֹתוֹ הָעוֹלָם. וְתוֹרָה אוֹר - מִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה, זוֹכֶה לְאוֹתוֹ אוֹר עֶלְיוֹן שֶׁנִּדְלָק מִמֶּנּוּ הַנֵּר, שֶׁהֲרֵי נֵר בְּלִי אוֹר אֵינוֹ כְלוּם. אוֹר בְּלִי נֵר אַף כָּךְ לֹא יָכוֹל לְהָאִיר. נִמְצָא שֶׁכֻּלָּם צְרִיכִים זֶה אֶת זֶה. צָרִיךְ מַעֲשֶׂה לְתַקֵּן הַנֵּר, וְצָרִיךְ לִלְמֹד תּוֹרָה לְהָאִיר הַנֵּר. אַשְׁרֵי מִי שֵׁמִּתְעַסֵּק בָּהּ בָּאוֹר וּבְנֵר.</p>\n<p>וְדֶרֶךָֹ חַיִּים תּוֹכְחוֹת מוּסָר - דֶּרֶךְ חַיִּים לְהִכָּנֵס בָּהּ לָעוֹלָם הַבָּא, אוֹתָן תּוֹכָחוֹת שֶׁמְּקַבֵּל אָדָם לְהָסִיר אֶת עַצְמוֹ מִדֶּרֶךְ רָעָה וְלָלֶכֶת בְּדֶרֶךְ טוֹבָה. עוֹד וְדֶרֶךְ חַיִּים - אוֹתָם תּוֹכְחוֹת מוּסָר, שֶׁמֵּבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָאָדָם לְטַהֲרוֹ מֵחֲטָאָיו בְּאוֹתָן תּוֹכָחוֹת. אַשְׁרֵי מִי שֶׁמְּקַבֵּל אוֹתָן בִּרְצוֹן הַלֵּב.</p>\n<p>דָּבָר אַחֵר כִּי נֵר מִצְוָה - (תקון הגר) זֶה נֵר הַמְּנוֹרָה שֶׁל דָּוִד, שֶׁהוּא נֵר מִצְוָה תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁצְּרִיכָה לְהִתְתַּקֵּן תָּמִיד, וְאֵינָהּ מְאִירָה אֶלָּא מִתּוֹךְ תּוֹרָה שֶׁבִּכְתָב, שֶׁהֲרֵי אֵין לַתּוֹרָה שֶׁבְּעַל פֶּה אוֹר אֶלָּא מִתּוֹךְ תּוֹרָה שֶׁבִּכְתָב, שֶׁהִיא הָאוֹר לְהָאִיר.</p>\n<p>הִסְתַּכֵּל לַאֲחוֹרָיו וְרָאָה אֶת בַּת הַמְאָרֵחַ עוֹמֶדֶת מֵאַחֲרֵיהֶם. אָמַר, כִּי נֵר מִצְוָה, מַה זֶּה נֵר? זֶה הַנֵּר שֶׁהִיא מִצְוָה שֶׁנָּשִׁים זוֹכוֹת בָּהּ, וְהִיא נֵר שַׁבָּת. שֶׁאַף עַל גַּב שֶׁנָּשִׁים לֹא זוֹכוֹת בַּתּוֹרָה, הֲרֵי הַגְּבָרִים זוֹכִים בַּתּוֹרָה וּמְאִירִים אֶת הַנֵּר הַזֶּה שֶׁהַנָּשִׁים מְתַקְּנוֹת בַּמִּצְוָה הַזּוֹ. הַנָּשִׁים בַּתִּקּוּן שֶׁל הַנֵּר הַזֶּה - וְהַגְּבָרִים בַּתּוֹרָה לְהָאִיר לַנֵּר הַזֶּה, תִּקּוּן הַמִּצְוָה שֶׁהַנָּשִׁים הִתְחַיְּבוּ בָהֶם.</p>\n<p>שָׁמְעָה אוֹתָהּ אִשָּׁה וּבָכְתָה. בֵּין כָּךְ קָם אֲבִי הָאִשָּׁה שֶׁהָיָה שָׁם וְנִכְנַס בֵּינֵיהֶם, וְרָאָה אֶת בִּתּוֹ עוֹמֶדֶת מֵאַחֲרֵיהֶם וּבוֹכָה. שָׁאַל אוֹתָהּ אָבִיהָ, וְהִיא סָחָה לוֹ (רבי אבא) אֶת הַמַּעֲשֶׂה. הִתְחִיל אֲבִי הָאִשָּׁה אַף הוּא לִבְכּוֹת. אָמַר לוֹ רַבִּי יוֹסֵי, אוּלַי חֲתָנְךְ בַּעְלָהּ שֶׁל בִּתְּךְ לֹא זָכָה בַּתּוֹרָה? אָמַר לוֹ, וַדַּאי כָּךְ זֶה, וְעַל זֶה וַדַּאי אָנוּ בּוֹכִים אֲנִי וּבִתִּי תָּמִיד.</p>\n<p>וּבִשְׁבִיל שֶׁרָאִיתִי אוֹתוֹ יוֹם אֶחָד שֶׁמְּדַלֵּג מֵהָעֲלִיָּה הַזּוֹ לִשְׁמֹעַ קַדִּישׁ עִם הַצִּבּוּר, עָלָה בִרְצוֹנִי לָתֵת לוֹ אֶת בִּתִּי, וְתֵכֶף שֶׁהַצִּבּוּר יָצָא מִבֵּית הַכְּנֶסֶת נָתַתִּי לוֹ אֶת בִּתִּי. שֶׁאָמַרְתִּי, שֶׁבַּדִּלּוּג הַזֶּה שֶׁבָּא לִשְׁמֹעַ קַדִּישׁ, הוּא יִהְיֶה אָדָם גָּדוֹל בַּתּוֹרָה, וְאַף עַל גַּב שֶׁהוּא תִּינוֹק וְלֹא הִכַּרְתִּי אוֹתוֹ מִקֹּדֶם לָכֵן. וְעַכְשָׁו אֲפִלּוּ בִּרְכַּת הַמָּזוֹן אֵינוֹ יוֹדֵעַ, וְלֹא יָכֹלְתִּי לִלְמֹד עִמּוֹ בֵּין הַחֲבֵרִים שֶׁיִּלְמַד קְרִיאַת שְׁמַע אוֹ בִּרְכַּת הַמָּזוֹן.</p>\n<p>אָמַר לוֹ, הַעֲבִירֵנוּ בְאַחֵר, אוֹ אוּלַי יוֹלִיד בֵּן שֶׁיִּהְיֶה אִישׁ גָּדוֹל. בֵּינְתַיִם הוּא קָם וְדִלֵּג עֲלֵיהֶם וְיָשַׁב לִפְנֵיהֶם. הִסְתַּכֵּל בּוֹ רַבִּי יוֹסֵי, אָמַר, וַדַּאי אֲנִי רוֹאֶה בַּיֶּלֶד הַזֶּה שֶׁאוֹר הַתּוֹרָה יֵצֵא מִמֶּנּוּ לָעוֹלָם, אוֹ בֵּן שֶׁיָּקוּם מִמֶּנּוּ. צָחַק אוֹתוֹ יֶלֶד וְאָמַר, רַבּוֹתַי, אֹמַר לִפְנֵיכֶם דָּבָר אֶחָד.</p>\n<p>פָּתַח וְאָמַר, (איוב לב) צָעִיר אֲנִי לְיָמִים וְאַתֶּם יְשִׁישִׁים, עַל כֵּן זָחַלְתִּי וָאִירָא מֵחַוּת דֵּעִי אֶתְכֶם. בְּפָסוּק זֶה הֵעִירוּ עַמּוּדֵי עוֹלָם, אֲבָל אֱלִיהוּא שֶׁכָּתוּב בּוֹ מִמִּשְׁפַּחַת רָם, הֱעִירוֹ, שֶׁהֲרֵי מִזֶּרַע אַבְרָהָם הוּא בָּא, וְיָפֶה. אֲבָל אֱלִיהוּא הָיָה כֹּהֵן, וּמִזַּרְעוֹ שֶׁל יְחֶזְקֵאל הַנָּבִיא הָיָה. כָּתוּב כָּאן בֶּן בַּרַכְאֵל הַבּוּזִי, וְכָתוּב שָׁם (יחזקאל א) יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן.</p>\n<p>וְאִם תֹּאמַר, מִשּׁוּם שֶׁכָּתוּב בּוּזִי, בּוּז מִשְׁפָּחוֹת הָיָה - לֹא כָּךְ! חָזַר וְאָמַר מִמִּשְׁפַּחַת רָם, עֶלְיוֹן עַל הַכֹּל. לָמָּה נִקְרָא בּוּזִי? עַל שֶׁמְּבַזֶּה עַצְמוֹ לְמִי שֶׁגָּדוֹל מִמֶּנּוּ, וְלָכֵן עָלָה בְשֵׁם עֶלְיוֹן. בּוּזִי - זֶה שֶׁנִּקְרָא אָדָם שָׁלֵם בַּכֹּל מַה שֶּׁלֹּא נִקְרָא כָּךְ אָדָם אַחֵר. זֶהוּ שֶׁכָּתוּב וְאַתָּה בֶן אָדָם, וְעַל שֶׁעָלָה בַּשֵּׁם הַזֶּה נִקְרָא רָם, עֶלְיוֹן עַל הַכֹּל.</p>\n<p>וְעַל זֶה אָמַר צָעִיר אֲנִי לְיָמִים. לְיָמִים, מִיָּמִים הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לְיָמִים? אֶלָּא אָמַר, צָעִיר אֲנִי וְהִקְטַנְתִּי עַצְמִי לְיָמִים, לְגַבֵּי אָדָם שֶׁיֵּשׁ לוֹ יָמִים רַבִּים. מָה הַטַּעַם? מִשּׁוּם שֶׁאָמַרְתִּי שֶׁיָּמִים יְדַבֵּרוּ, וְעַל זֶה אֲנִי צָעִיר וְהִקְטַנְתִּי אֶת עַצְמִי אֶל יָמִים. וְאַתֶּם יְשִׁישִׁים, רָאִיתִי אֶתְכֶם יְשִׁישִׁים עַל כֵּן זָחַלְתִּי וָאִירָא. וָאִירָא מֵחַוֹּת דֵּעִי אֶתְכֶם. אַף אֲנִי אָמַרְתִּי יָמִים יְדַבֵּרוּ וְרֹב שָׁנִים יֹדִיעוּ חָכְמָה, וַדַּאי. אָכֵן רוּחַ הִיא בֶאֱנוֹשׁ וְנִשְׁמַת שַׁדַּי תְּבִינֵם. וְלָכֵן מִשּׁוּם שֶׁאֲנִי יֶלֶד, שַׂמְתִּי בִרְצוֹנִי שֶׁלֹּא לְדַבֵּר עַד שְׁנֵי חֳדָשִׁים, וְעַד הַיּוֹם הַזֶּה הֵם נִשְׁלְמוּ. וְעַכְשָׁו שֶׁאַתֶּם כָּאן, יֵשׁ לִפְתֹּחַ בַּתּוֹרָה לִפְנֵיכֶם.</p>\n<p>פָּתַח וְאָמַר, (משלי ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. כִּי נֵר מִצְוָה - זוֹהִי מִשְׁנָה, כְּמוֹ שֶׁנֶּאֱמַר (שמות כד) וְהַתּוֹרָה וְהַמִּצְוָה. וְהַתּוֹרָה - זוֹ תּוֹרָה שֶׁבִּכְתָב. וְהַמִּצְוָה - זוֹ מִשְׁנָה, שֶׁהִיא נֵר שֶׁעוֹמֵד לְהַדְלָקָה.</p>\n<p>נֵר, לָמָּה נִקְרָא נֵר? אֶלָּא כְּשֶׁמְּקַבֵּל מִבֵּין שְׁתֵּי זְרוֹעוֹת, רמ\"ח אֵיבָרִים עֶלְיוֹנִים, הִיא פּוֹתַחַת אֲלֵיהֶם שְׁתֵּי זְרוֹעוֹת שֶׁלָּהּ, וְאָז נִכְלָלוֹת שְׁתֵּי הַזְּרוֹעוֹת הַלָּלוּ בָהֶם וְנִקְרָאִים נֵר. וְתוֹרָה אוֹר, שֶׁמֵּאִיר לְאוֹתוֹ נֵר וְנִדְלֶקֶת מִמֶּנּוּ מִצַּד הָאוֹר הָרִאשׁוֹן שֶׁהוּא יָמִין, שֶׁהֲרֵי הַתּוֹרָה נִתְּנָה מֵאוֹתוֹ צַד הַיָּמִין שֶׁל הָאוֹר הָרִאשׁוֹן, שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, שֶׁנִּתְּנָה מִצַּד הַיָּמִין, וְאַף עַל גַּב שֶׁנִּכְלָל בָּהּ שְׂמֹאל, שֶׁהֲרֵי אָז הִיא שְׁלֵמוּת הַכֹּל.</p>"],[9522011765,"<p>הָאוֹר הַזֶּה נִכְלָל בְּמָאתַיִם וְשִׁבְעָה עוֹלָמוֹת שֶׁגְּנוּזִים בַּצַּד שֶׁל אוֹתוֹ הָאוֹר וּמִתְפַּשֵּׁט בְּכֻלָּם. תַּחַת הַכִּסֵּא הַטָּמִיר הָעֶלְיוֹן שׁוֹרִים אוֹתָם עוֹלָמוֹת מִצַּד אוֹתוֹ הַיָּמִין. שְׁלֹשׁ מֵאוֹת וַעֲשָׂרָה הֵם. מָאתַיִם וְשִׁבְעָה הֵם בְּצַד הַיָּמִין, וּמֵאָה וּשְׁלֹשָׁה הֵם בְּצַד הַשְּׂמֹאל. וְהֵם שְׁלֹשׁ מֵאוֹת וַעֲשָׂרָה. וְאֵלּוּ הֵם שֶׁמְּתַקֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד לַצַּדִּיקִים. וּמֵאֵלֶּה מִתְפַּשְּׁטִים כַּמָּה וְכַמָּה אוֹצְרוֹת הַחֶמְדָּה, וְכֻלָּם גְּנוּזִים כְּדֵי לְהִתְעַדֵּן מֵהֶם הַצַּדִּיקִים בָּעוֹלָם הַבָּא, וְעַל אֵלֶּה כָּתוּב (משלי ח) לְהַנְחִיל אֹהֲבַי יֵשׁ וְאֹצְרֹתֵיהֶם אֲמַלֵּא, וְעַל אֵלֶּה כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'.</p>\n<p>יֵ\"שׁ - אֵלֶּה שְׁלֹשׁ מֵאוֹת וַעֲשָׂרָה עוֹלָמוֹת שֶׁגְּנוּזִים תַּחַת הָעוֹלָם הַבָּא, (ועל) אוֹתָם מָאתַיִם וְשִׁבְעָה שֶׁהֵם מִצַּד הַיָּמִין נִקְרָאִים אוֹר רִאשׁוֹן, מִשּׁוּם שֶׁאֲפִלּוּ אוֹר הַשְּׂמֹאל נִקְרָא אוֹר. אֲבָל הָאוֹר הָרִאשׁוֹן עָתִיד לַעֲשׂוֹת תּוֹלָדוֹת לָעוֹלָם הַבָּא. וְאִם תֹּאמַר, לָעוֹלָם הַבָּא וְלֹא יוֹתֵר? אֶלָּא אֲפִלּוּ בְּכָל יוֹם וָיוֹם שֶׁאִם הָאוֹר הַזֶּה לֹא הָיָה, הָעוֹלָם לֹא יוּכַל לְהִתְקַיֵּם, שֶׁכָּתוּב (תהלים פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה.</p>"],[9522011766,"<p>הָאוֹר הַזֶּה זָרַע אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֶדְנוֹ, וְעָשָׂה אוֹתוֹ שׁוּרוֹת שׁוּרוֹת עַל יְדֵי הַצַּדִּיק הַזֶּה, שֶׁהוּא הַגַּנָּן שֶׁל הַגָּן, וְנָטַל אֶת הָאוֹר הַזֶּה וְזָרַע אוֹתוֹ זֶרַע אֱמֶת, וְעָשָׂה אוֹתוֹ שׁוּרוֹת שׁוּרוֹת בַּגָּן, וְהוֹלִיד וְהִצְמִיחַ וְעָשָׂה פֵרוֹת, וּמֵהֶם נִזּוֹן הָעוֹלָם. זֶהוּ שֶׁכָּתוּב אוֹר זָרֻעַ לַצַּדִּיק וְגוֹ'.</p>\n<p>וְכָתוּב, (ישעיה סא) וּכְגַנָּה זֵרוּעֶיהָ תַצְמִיחַ. מִי הֵם זֵרוּעֶיהָ? אֵלֶּה הֵם הַזְּרָעִים שֶׁל הָאוֹר הָרִאשׁוֹן שֶׁהוּא תָמִיד זָרוּעַ, וְעַכְשָׁו מוֹלִיד וְעוֹשֶׂה פֵרוֹת, וְעַכְשָׁו הוּא זָרוּעַ. בָּרִאשׁוֹנָה, בְּטֶרֶם שֶׁיֹּאכַל הָעוֹלָם אֶת הַפְּרִי הַזֶּה, הוֹלִיד הַזָּרוּעַ הַזֶּה וְנוֹתֵן פְּרִי וְלֹא שׁוֹכֵךְ. וְלָכֵן כָּל הָעוֹלָמוֹת נִזּוֹנוּ בְּסִפּוּקוֹ שֶׁל אוֹתוֹ הַגַּנָּן שֶׁנִּקְרָא צַדִּיק, שֶׁאֵינוֹ שׁוֹכֵךְ וְלֹא פוֹסֵק לְעוֹלָמִים.</p>\n<p>פְּרָט לַזְּמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת. וְאִם תֹּאמַר, בִּזְמַן הַגָּלוּת כָּתוּב, (איוב יד) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחֱרַב וְיָבֵשׁ, וְאֵיךְ עָשָׂה תוֹלָדוֹת? אֶלָּא כָּתוּב זָרֻעַ, וְהוּא תָּמִיד זָרוּעַ, וּמִיּוֹם שֶׁנִּפְסַק אוֹתוֹ נָהָר לֹא נִכְנַס לַגָּן (בגן) אוֹתוֹ הַגַּנָּן. וְאוֹתוֹ אוֹר שֶׁהוּא תָּמִיד זָרוּעַ, עוֹשֶׂה פֵרוֹת, וּמִמֶּנּוּ וּמֵעַצְמוֹ נִזְרָע כְּבָרִאשׁוֹנָה וְלֹא שׁוֹכֵךְ תָּמִיד, כְּמוֹ גַן שֶׁעוֹשֶׂה תוֹלָדוֹת, וּמֵאוֹתוֹ הַזָּרוּעַ נוֹפֵל בּוֹ בִּמְקוֹמוֹ, וּמֵעַצְמוֹ עוֹשֶׂה תוֹלָדוֹת כְּבָרִאשׁוֹנָה. וְאִם תֹּאמַר שֶׁאוֹתָם תּוֹלָדוֹת וּפֵרוֹת הָיוּ כְּמוֹ שֶׁהָיָה בִּזְמַן שֶׁהַגַּנָּן שָׁם - לֹא כָּךְ, אֲבָל לֹא נִמְנָע הַזָּרוּעַ הַזֶּה לְעוֹלָמִים.</p>\n<p>כְּמוֹ זֶה וְתוֹרָה אוֹר. הַתּוֹרָה שֶׁנִּתְּנָה מִצַּד אוֹתוֹ הָאוֹר הָרִאשׁוֹן, כָּךְ נִזְרָע תָּמִיד בָּעוֹלָם וְעוֹשֶׂה תוֹלָדוֹת וּפֵרוֹת וְלֹא שׁוֹכֵךְ לְעוֹלָמִים, וּמֵאוֹתוֹ הַפְּרִי שֶׁלּוֹ נִזּוֹן הָעוֹלָם.</p>\n<p>וְדֶרֶךָ חַיִּים תּוֹכְחוֹת מוּסָר. שְׁנֵי דְרָכִים הֵם, אֶחָד דֶּרֶךְ הַחַיִּים, וְאֶחָד בְּהֵפֶךְ מִמֶּנּוּ. מַהוּ הַסִּימָן שֶׁל דֶּרֶךְ חַיִּים? תּוֹכְחוֹת מוּסָר. שֶׁכַּאֲשֶׁר רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁמֹר אֶת דֶּרֶךְ הַחַיִּים הַזּוֹ, הוּא שָׂם עָלָיו אוֹתוֹ הַמַּלְקֶה וְעוֹשֶׂה תוֹכְחוֹת מוּסָר לִבְנֵי אָדָם, וּמִיהוּ? זֶה שֶׁכָּתוּב (בראשית ג) וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמֹר אֶת דֶּרֶךְ הַחַיִּים. וְלָכֵן דֶּרֶךְ חַיִּים הִיא תּוֹכְחוֹת מוּסָר. וּמִי שֶׁיֵּשׁ בּוֹ תּוֹכָחוֹת, וַדַּאי שֶׁמְּעִירִים אוֹתוֹ לָלֶכֶת בְּאוֹתָהּ דֶּרֶךְ חַיִּים שֶׁשָּׁם מַתְחִיל תּוֹכְחוֹת מוּסָר.</p>\n<p>הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ, אֶלָּא הַכֹּל הוּא סוֹד הָאֱמוּנָה שֶׁל הַפָּסוּק הַזֶּה. כִּי נֵר מִצְוָה - זֶה סוֹד שֶׁל שָׁמוֹר. וְתוֹרָה אוֹר - זֶה סוֹד שֶׁל זָכוֹר. וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר - אֵלֶּה גְּזֵרוֹת וָעֳנָשִׁים שֶׁל הַתּוֹרָה, וְהַכֹּל סוֹד הָאֱמוּנָה. וְצָרִיךְ זֶה אֶת זֶה, וְלִהְיוֹת סוֹד שֶׁל הַכֹּל כָּרָאוּי.</p>"],[9522011767,"<p>וְעַל הַסּוֹד הַזֶּה שֶׁל הָאוֹר הַזֶּה שֶׁדּוֹלֵק וּמֵאִיר לַנֵּר הַזֶּה, כָּתוּב בּוֹ בְּאַהֲרֹן (במדבר ה) בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת, מִשּׁוּם שֶׁהוּא בָּא מִצַּד הָאוֹר הַזֶּה. בָּאוֹר הַזֶּה כָּתוּב (בראשית א) יְהִי אוֹר וַיְהִי אוֹר. כֵּיוָן שֶׁאָמַר יְהִי אוֹר, לָמָּה כָּתוּב וַיְהִי אוֹר, שֶׁהֲרֵי בְּוַיְהִי כֵן מַסְפִּיק? אֶלָּא יְהִי אוֹר - זֶה הָאוֹר הָרִאשׁוֹן, שֶׁהוּא יָמִין, וְהוּא לְקֵץ הַיָּמִין. וַיְהִי אוֹר - שֶׁמִּיָּמִין יוֹצֵא שְׂמֹאל, וּמִסּוֹד הַיָּמִין יוֹצֵא שְׂמֹאל, וְעַל זֶה וַיְהִי אוֹר, זֶה שְׂמֹאל.</p>\n<p>מִכָּאן שֶׁוַּיְהִי הָרִאשׁוֹן שֶׁל הַתּוֹרָה הָיָה בְּצַד הַשְּׂמֹאל, וְלָכֵן אֵינוֹ סִימַן בְּרָכָה. מָה הַטַּעַם? מִשּׁוּם שֶׁבּוֹ (שממנו) יָצָא אוֹתוֹ חֹשֶׁךְ שֶׁהֶחְשִׁיךְ אֶת פְּנֵי הָעוֹלָם. וְסִימָן זֶה כַּאֲשֶׁר הִתְגַּלָּה הַסּוֹד שֶׁל עֵשָׂו וּמַעֲשֵׂהוּ, זֶה הָיָה בַּוַּיְהִי הַזֶּה, שֶׁכָּתוּב (שם כה) וַיְהִי עֵשָׂו אִישׁ יֹדֵעַ צַיִד. הִתְקַיֵּם בְּוַיְהִי אִישׁ יֹדֵעַ צַיִד, לְפַתּוֹת אֶת בְּנֵי הָעוֹלָם שֶׁלֹּא יֵלְכוּ בְּדֶרֶךְ יְשָׁרָה.</p>\n<p>וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב - זֶהוּ הָעַמּוּד שֶׁעוֹמֵד בָּאֶמְצַע, וְעוֹמֵד וְאוֹחֵז בְּצַד זֶה וּבְצַד זֶה. כְּשֶׁהָיְתָה שְׁלֵמוּת שֶׁל שְׁלֹשֶׁת הַצְּדָדִים, כָּתוּב בּוֹ כִּי טוֹב, מַה שֶּׁלֹּא הָיָה בָּאֲחֵרִים הַלָּלוּ, מִשּׁוּם שֶׁלֹּא הָיְתָה שְׁלֵמוּת עַד הָאוֹר הַשְּׁלִישִׁי שֶׁהִשְׁלִים אֶת כָּל הַצְּדָדִים, וְכֵיוָן שֶׁבָּא הַשְּׁלִישִׁי הַזֶּה, אָז הִפְרִיד מַחֲלֹקֶת שֶׁל יָמִין וּשְׂמֹאל, שֶׁכָּתוּב וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ.</p>\n<p>וְעַל שֶׁהֵן חָמֵשׁ דְּרָגוֹת שֶׁנִּפְרְדוּ וְנִמְשְׁכוּ מֵהָאוֹר הָרִאשׁוֹן הַזֶּה, כָּתוּב חָמֵשׁ פְּעָמִים אוֹר, וְכֻלָּם הָיוּ מִצַּד הַיָּמִין וְנִכְלְלוּ בוֹ. וּכְשֶׁנִּכְלְלוּ בְּצַד שְׂמֹאל, נִכְלְלוּ בְּסוֹד שֶׁל מַיִם שֶׁנּוֹטֵל בְּיָמִין (מימין), וְלָכֵן כָּתוּב מַיִם חָמֵשׁ פְּעָמִים. וּכְשֶׁנִּשְׁלְמוּ בְּסוֹד הָאֶמְצַע, כָּתוּב רָקִיעַ חָמֵשׁ פְּעָמִים, וְעַל זֶה שְׁלֹשָׁה הֵם: אוֹר, מַיִם, רָקִיעַ. כְּנֶגֶד שְׁלֹשׁ הַדְּרָגוֹת הַלָּלוּ, שֶׁכֻּלָּן חָמֵשׁ דְּרָגוֹת נִכְלְלוּ בָהֶם, וְעַל זֶה בְּכֻלָּם כָּתוּב חָמֵשׁ פְּעָמִים בְּכָל אֶחָד וְאֶחָד.</p>\n<p>כָּאן סוֹד הַסּוֹדוֹת בְּאֵלּוּ הַשְּׁלֹשָׁה, הִצְטַיֵּר וְנֶחְקַק בְּחִקּוּקֵי הַסּוֹד שֶׁל דְּמוּת הָאָדָם, שֶׁהוּא אוֹר בָּרִאשׁוֹנָה, וְאַחַר כָּךְ מַיִם. וְאַחַר כָּךְ מִתְפַּשֵּׁט בְּתוֹכָם רָקִיעַ, שֶׁהוּא חִקּוּק שֶׁל חֲקִיקַת דְּמוּת הָאָדָם.</p>\n<p>כְּמוֹ שֶׁחָקוּק צִיּוּר שֶׁל דְּמוּת אָדָם בְּתוֹלַדְתּוֹ, שֶׁהֲרֵי בְּתוֹלֶדֶת הָאָדָם בַּהַתְחָלָה זֶרַע, שֶׁהוּא אוֹר, שֶׁהֲרֵי הָאוֹר שֶׁל כָּל אֵיבְרֵי הַגּוּף הוּא אוֹתוֹ זֶרַע, וְלָכֵן הוּא אוֹר, וְאוֹתוֹ אוֹר נִקְרָא זֶרַע, שֶׁכָּתוּב אוֹר זָרֻעַ, אוֹתוֹ זֶרַע מַמָּשׁ. אַחַר כָּךְ אוֹתוֹ זֶרַע, שֶׁהוּא אוֹר, מִתְפַּשֵּׁט וְנַעֲשֶׂה מַיִם, בַּלַּחוּת שֶׁלּוֹ נֶחְקָק יוֹתֵר, וּמִתְפַּשֵּׁט הִתְפַּשְּׁטוּת בְּתוֹךְ אוֹתָם הַמַּיִם הִתְפַּשְּׁטוּת הַגּוּף לְכָל הַצְּדָדִים. כֵּיוָן שֶׁמִּצְטַיֵּר וְנֶחְקָק צִיּוּר וּדְמוּת הַגּוּף, נִקְרְשָׁה אוֹתָהּ הִתְפַּשְּׁטוּת וְנִקְרֵאת רָקִיעַ, וְזֶהוּ רָקִיעַ בְּתוֹךְ הַמָּיִם. וְאַחַר שֶׁהִקְרִישׁ, כָּתוּב וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. שֶׁהֲרֵי הִקְרִישָׁה אוֹתָהּ הַלַּחוּת (שהשפיע ונשארה אותה הפסלת) שֶׁל הַגּוּף שֶׁהָיָה בְּתוֹךְ אוֹתָם הַמַּיִם.</p>\n<p>כֵּיוָן שֶׁנִּבְרַר הַגּוּף וְהִתְנַקָּה בְּנִקָּיוֹן, אוֹתָהּ לַחוּת שֶׁשָּׁפְעָה וְנִשְׁאֲרָה, הָיְתָה פְּסֹלֶת שֶׁנֶּעֶשְׂתָה תּוֹךְ הַהִתּוּךְ, וְהֵם מַיִם הָרָעִים הָעֲכוּרִים, וּמֵהֶם נַעֲשֶׂה פְּסֹלֶת, מְקַטְרֵג לְכָל הָעוֹלָם, זָכָר וּנְקֵבָה. אַחַר כָּךְ כְּשֶׁיָּרְדוּ אוֹתָם מַיִם עֲכוּרִים וְהִתְהַתְּכוּ לְמַטָּה בְּצַד שְׂמֹאל, יָצְאוּ (ששפע ונשאר, נעשה פסלת מקטרג לכל העולם, זכר ונקבה, והם המים הרעים העכורים. ואחר כך כאשר ירדו אותם מים עכורים והתהתכו למטה בצד שמאל ויצאו) לְקַטְרֵג לְכָל הָעוֹלָם. אַשְׁרֵי מִי שֶׁנִּצָּל מֵהֶם.</p>\n<p>כֵּיוָן שֶׁיּוֹצֵא הַמְקַטְרֵג, כָּתוּב יְהִי מְאֹרֹת חָסֵר ו', וְנִמְשְׁכָה אַסְכָּרָה לַתִּינוֹקוֹת, וְחָסֵר אוֹר הַלְּבָנָה. אַחַר כָּךְ, וְהָיוּ לִמְאוֹרֹת, בַּשְּׁלֵמוּת שֶׁל שְׁנֵיהֶם כְּאֶחָד. בְּמִי? בְּאוֹתוֹ רְקִיעַ הַשָּׁמַיִם, שֶׁהֲרֵי כְּשֶׁעוֹלָה וּמִתְחַבֶּרֶת בְּאוֹתוֹ רְקִיעַ הַשָּׁמַיִם, אֲזַי וְהָיוּ לִמְאוֹרֹת, אוֹרוֹת שְׁלֵמִים שְׁנֵיהֶם כְּאֶחָד שֶׁלֹּא פְגוּמִים כְּלָל.</p>\n<p>הִתְחִיל לִצְחֹק הַיֶּלֶד הַזֶּה וְשָׂמַח. אָמַר לָהֶם, זֶה שֶׁאָמַרְתִּי שֶׁנִּבְרַר כָּאן סוֹד שֶׁל אָדָם בָּאוֹר שֶׁל אוֹתוֹ (שהוא) הַזֶּרַע, וְאַחַר כָּךְ נַעֲשָׂה מַיִם, וּמִתּוֹךְ אוֹתָם הַמַּיִם מִתְפַּשֵּׁט רָקִיעַ, דְּיוֹקָן שֶׁל אָדָם, כְּמוֹ שֶׁעוֹרַרְנוּ. מֵילָא כְּשֶׁזֶּה נַעֲשֶׂה בְּתוֹךְ מְעִי הָאִשָּׁה, שֶׁהֲרֵי לֹא מִצְטַיֵּר הַזֶּרַע אֶלָּא בְּתוֹךְ מְעִי הַנְּקֵבָה לְהִתְפַּשֵּׁט בָּהּ דְּיוֹקָן שֶׁל אָדָם, וְכָאן אִם אֵלֶּה חָמֵשׁ דְּרָגוֹת הֵם דְּיוֹקָן שֶׁל אָדָם, בְּאֵיזֶה מָקוֹם מִצְטַיֵּר וּמִתְפַּשֵּׁט הַדְּיוֹקָן הַזֶּה בְּתוֹךְ הַמַּיִם הַלָּלוּ?</p>\n<p>אִם תֹּאמַר בְּתוֹךְ הַנְּקֵבָה הֵם הָיוּ, זֶה הָעוֹלָם הַבָּא - לֹא כָּךְ! שֶׁהֲרֵי לֹא הִצְטַיֵּר צִיּוּר וּדְמוּת עַד שֶׁיּוֹצְאוֹת הָאוֹתִיּוֹת לַחוּץ, וְאַחַר כָּךְ נִגְלְמוּ. וְעוֹד, שֶׁהֲרֵי הָעוֹלָם הַבָּא הָיָה הָאֻמָּן, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ. הֲרֵי הָאֻמָּן הוּא הָיָה.</p>\n<p>אִם תֹּאמַר בַּנְּקֵבָה שֶׁלְּמַטָּה - לֹא כָּךְ, שֶׁהֲרֵי טֶרֶם הָיְתָה! וּכְשֶׁיָּצְאָה דְמוּת אָדָם, נְקֵבָתוֹ יָצְאָה עִמּוֹ. הֲרֵי לֹא הִצְטַיֵּר דְּיוֹקָן שֶׁל אָדָם בָּהּ. אִם כָּךְ, בְּאֵיזֶה מָקוֹם הִצְטַיֵּר וְנֶחְקַק הַזֶּרַע הַזֶּה לִהְיוֹת חֲקִיקָתוֹ שֶׁל דְּמוּת אָדָם?</p>\n<p>אֶלָּא זֶה סוֹד עֶלְיוֹן. אָדָם הָרִאשׁוֹן הִצְטַיֵּר וְנֶחְקַק בְּלִי נְקֵבָה. הָאָדָם הַשֵּׁנִי מִכֹּחַ וְזֶרַע שֶׁל זֶה נֶחְקַק וְהִצְטַיֵּר בְּתוֹךְ הַנְּקֵבָה.</p>\n<p>אָדָם הָרִאשׁוֹן, חֲקִיקָה שֶׁל צִיּוּר וּדְמוּת הַגּוּף, לֹא הָיָה בַּנְּקֵבָה, וּבְלִי צִיּוּר כְּלָל הָיָה. וְהִצְטַיֵּר וְנֶחְקָק לְמַטָּה מֵהָעוֹלָם הַבָּא, בְּלִי זָכָר וּבְלִי נְקֵבָה, אוֹתָן אוֹתִיּוֹת נִגְלְמוּ בְּתוֹךְ הַמִּדָּה, וְהִצְטַיֵּר וְנֶחְקַק בָּהֶן סוֹד שֶׁל אָדָם. וְהָאוֹתִיּוֹת בְּדֶרֶךְ יְשָׁרָה בַּסִּדּוּר שֶׁלָּהֶן, מִסּוֹד שֶׁל הָאוֹר הָרִאשׁוֹן, הִתְחִילוּ לְהֵחָקֵק וּלְהִצְטַיֵּר (אותיות), וְנִזְרַע הָאוֹר הַזֶּה בְּתוֹכוֹ תּוֹךְ הַמִּדָּה. כְּשֶׁהִגִּיעַ לְתוֹךְ הַמִּדָּה וְהָפַךְ לְמַיִם בְּתוֹךְ מַיִם, הִתְפַּשֵּׁט הָרָקִיעַ בְּצִיּוּר שֶׁל אָדָם דְּמוּת כָּרָאוּי.</p>\n<p>לְאַחַר שֶׁהִתְקַשְּׁטָה הַנְּקֵבָה אֵלָיו וְחָזְרוּ לִהְיוֹת פָּנִים בְּפָנִים, הַדְּמוּת הַזּוֹ שֶׁל אָדָם נִכְנְסָה בִּתְשׁוּקָה אֵצֶל הַנְּקֵבָה, וְשָׁם נֶחְקַק וְהִצְטַיֵּר כְּמוֹ הַצּוּרָה שֶׁלּוֹ, וְעָלָיו כָּתוּב (בראשית ה) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וְגוֹ'. זֶה הִצְטַיֵּר בְּתוֹךְ הַנְּקֵבָה מַה שֶּׁלֹּא הָיָה אוֹתוֹ הָרִאשׁוֹן, שֶׁהִצְטַיֵּר אוֹתוֹ רִאשׁוֹן בְּתוֹכוֹ בִּמְדִידָה בְּתוֹךְ הַמִּדָּה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522011768,"<p>כְּמוֹ זֶה לְמַטָּה. מַה כָּתוּב לְמַטָּה? (שם ב) וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן. הִתְחִילָה לְהוֹלִיד קוֹף בְּמֵעֶיהָ בְּכֹחַ וְסִיּוּעַ שֶׁל אָדָם, אַחַר שֶׁקִּבְּלָה זֻהֲמָה מֵהַקּוֹף הַזֶּה, וְלָכֵן לֹא כָתוּב כָּאן וַיּוֹלֶד, אֶלָּא יָדַע וַתַּהַר וַתֵּלֶד, וְיָצְאָה הַפְּסֹלֶת בְּתוֹךְ הַנְּקֵבָה.</p>\n<p>וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, וּבָזֶה גַּם לֹא כָתוּב וַיּוֹלֶד, וְאַף עַל גַּב שֶׁמִּצַּד הַזָּכָר הוּא הָיָה. אֲבָל הַמְקַטְרֵג תָּשַׁשׁ וְשָׁבַר אֶת כֹּחוֹ, שֶׁהֲרֵי בָּאוֹת קוֹף הִתְחילוּ הָאוֹתִיּוֹת לְהוֹלִיד.</p>\n<p>כֵּיוָן שֶׁנִּבְרְרָה הַפְּסֹלֶת, הִתְחִילוּ הָאוֹתִיּוֹת לְהוֹלִיד מִסּוֹד הָאוֹת ש\"ת תִּקּוּן שֶׁל זָכָר וּנְקֵבָה בְּהַסְכָּמָה כְּאֶחָד. וְאָז כָּתוּב, וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, וְלֹא כָתוּב וַתִּקְרָא. וַיִּקְרָא הוּא, וְלֹא הִיא. הוּא קָרָא שְׁמוֹ שֵׁת. תִּקּוּן זָכָר וּנְקֵבָה כְּאֶחָד שֶׁהָיוּ בְהַסְכָּמָה אַחַת.</p>\n<p>עוֹד הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת, וְחָזְרוּ לְהוֹלִיד אָלֶף שֶׁל אָדָם, וְהֵם אוֹתִיּוֹת בַּמָּקוֹם שֶׁהוּא הַסִּיּוּם שֶׁל שְׁמוֹ, וּמִיהוּ? נ'. וְאַחַר כָּךְ ו' וְלֹא ה', שֶׁהֲרֵי הִתְעַבְּרָה (הולידה) בְּהֶבֶל. וְלָכֵן נָטַל אוֹת אַחֶרֶת אַחֲרָיו ו', סִיֵּם בָּרֵאשִׁית שֶׁל שֵׁת ש', וְנִקְרָא אֱנוֹשׁ.</p>\n<p>אֱנוֹשׁ, מַה בֵּין הַשֵּׁם הַזֶּה לַשֵּׁם שֶׁל אָדָם? אֶלָּא אֱנוֹשׁ לֹא הָיָה בְתֹקֶף, הוּא הָיָה בְּתִקּוּנָם שֶׁל הָרִאשׁוֹנִים, (תהלים ח) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ. וְכָתוּב (איוב ז) מָה אֱנוֹשׁ כִּי תְגַדְּלֶנּוּ וְגוֹ', וַתִּפְקְדֶנּוּ לִבְקָרִים לִרְגָעִים תִּבְחָנֶנּוּ. וְעַל זֶה כָּתוּב (ישעיה נג) וַה' חָפֵץ דַּכְּאוֹ הֶחֱלִי, שֶׁבֶר הַגּוּף וְכֹחַ הַנֶּפֶשׁ הוֹרִישׁ שֵׁת לֶאֱנוֹשׁ יְרֻשָּׁה שֶׁהָיְתָה לוֹ לְקַבֵּל. וְאַף הוּא הוֹרִישׁ לִבְנוֹ כָּךְ.</p>\n<p>עוֹד הִתְגַּלְגְּלוּ הָאוֹתִיּוֹת לְתַקֵּן אֶת הֶעָקֹם, וְחָזְרו לְהוֹלִיד אֶת קֵינָן, זֶה הַתִּקּוּן שֶׁל קַיִן וְהִתְתַּקֵּן תַּחְתָּיו, וְחָזְרוּ הָאוֹתִיּוֹת לְבַשֵּׂם אֶת הָעוֹלָמוֹת מֵהָעַקְמִימוּת שֶׁהָיְתָה. מַהֲלַלְאֵל, מ' סוֹף שֶׁל אוֹתִיּוֹת אָדָם, ה' וְל' תִּקּוּן שֶׁל הָאוֹתִיּוֹת שֶׁל הֶבֶל, וּמִשּׁוּם שֶׁלֹּא הִרְשִׁיעַ כְּמוֹ קַיִן, לֹא הִתְחַלְּפוּ הָאוֹתִיּוֹת מִשְּׁמוֹ פְּרָט לְאַחַת, שֶׁבִּמְקוֹם ב' הָיְתָה א' לִהְיוֹת תִּקּוּן יוֹתֵר.</p>\n<p>עֵד כָּאן הִתְבַּשֵּׂם הָעוֹלָם וְהִתְתַּקֵּן הָעֹקֶם מֵהָרֵאשִׁית שֶׁל אֱנוֹשׁ, פְּרָט לְחֶטְאוֹ שֶׁל אָדָם שֶׁלֹּא הִתְבַּשֵּׂם עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי. אֲבָל הַתִּקּוּן שֶׁל הָעַקְמִימוּת שֶׁל קַיִן וְהֶבֶל הִתְתַּקֵּן וְהִתְבַּשֵּׂם, אֲבָל הָעוֹלָם הָיָה בְּצַעַר וְעִצָּבוֹן עַד שֶׁבָּא נֹחַ, שֶׁכָּתוּב (בראשית ה) זֶה יְנַחֲמנוּ מִמַּעֲשֵׂנוּ וּמֵעִצְּבוֹן יָדֵינוּ מִן הָאֲדָמָה אֲשֶׁר אֵרֲרָהּ ה'. וְחֶטְאוֹ שֶׁל אָדָם לֹא הִתְבַּשֵּׂם עַד שֶׁעָמְדוּ יִשְׂרָאֵל עַל הַר סִינַי וְקִבְּלוּ תוֹרָה, וּכְשֶׁיִּשְׂרָאֵל קִבְּלוּ תוֹרָה, אֲזַי הַנֵּר וְהָאוֹר הִתְתַּקְּנוּ כְאֶחָד.</p>\n<p>וְעַכְשָׁו רַבּוֹתַי, אֲנִי מִבָּבֶל, וּבְנוֹ שֶׁל רַב סַפְרָא אֲנִי, וְלֹא זָכִיתִי לְהִוָּדַע לְאָבִי, וְנִטְרַדְתִּי לְכָאן וּפָחַדְתִּי, שֶׁהֲרֵי יוֹשְׁבֵי הָאָרֶץ הַזּוֹ הֵם אֲרָיוֹת בַּתּוֹרָה, וְקִבַּלְתִּי עָלַי שֶׁלֹּא אֹמַר דִּבְרֵי תוֹרָה לִפְנֵי אִישׁ עַד שְׁנֵי חֳדָשִׁים, וְהַיּוֹם הַזֶּה הֵם נִשְׁלְמוּ. אַשְׁרֵי חֶלְקִי שֶׁנִּפְגַּשְׁנוּ פֹּה. הֵרִים רַבִּי יוֹסֵי אֶת קוֹלוֹ וּבָכָה, וְקָמוּ כֻלָּם וּנְשָׁקוּהוּ בְרֹאשׁוֹ. אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי חֶלְקֵנוּ שֶׁזָּכִינוּ בַּדֶּרֶךְ הַזּוֹ לִשְׁמֹעַ דִּבְרֵי עַתִּיק הַיָּמִים מִפִּיךְ, מַה שֶּׁלֹּא זָכִינוּ לִשְׁמֹעַ עַד עַכְשָׁו.</p>\n<p>יָשְׁבוּ כֻלָּם. אָמַר לָהֶם, רַבּוֹתַי, מִשֶּׁרָאִיתִי אֶת הַצַּעַר שֶׁל חָמִי וּבִתּוֹ שֶׁדְּחוּקִים וּמִצְטַעֲרִים בְּנַפְשָׁם שֶׁלֹּא יָדַעְתִּי אֶת בִּרְכַּת הַמָּזוֹן, אָמַרְתִּי לָהֶם, שֶׁעַד שֶׁאֵדַע אֶת בִּרְכַּת הַמָּזוֹן לֹא אֶתְחַבֵּר עִם אִשְׁתִּי כְּדֶרֶךְ כָּל הָעוֹלָם, וְאַף עַל גַּב שֶׁיָּכֹלְתִּי לְשַׁמֵּשׁ בָּהּ בְּלִי חֵטְא, אֵינִי רוֹצֶה לַעֲבֹר עַל דַּעְתָּם, הוֹאִיל וְלֹא יָכֹלְתִּי לוֹמַר דָּבָר עַד שְׁנֵי חֳדָשִׁים. שָׂמְחוּ רַבִּי חִיָּיא וְרַבִּי יוֹסֵי וְחָמִיו וּבִתּוֹ, וּבָכוּ מֵרֹב שִׂמְחָה. אָמַר רַבִּי יוֹסֵי, בְּבַקָּשָׁה מִמְּךְ, כֵּיוָן שֶׁהִתְחַלְתָּ, הָאֵר לָנוּ אֶת הַיּוֹם. אַשְׁרֵי חֶלְקֵנוּ בַּדֶּרֶךְ הַזּוֹ!</p>"],[9522011769,"<p>פָּתַח אוֹתוֹ יֶלֶד בְּבִרְכַּת הַמָּזוֹן וְאָמַר, כָּתוּב אֶחָד אוֹמֵר וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךְ, וְכָתוּב אֶחָד אוֹמֵר (דברים יד) וְשָׂמַחְתָּ לִפְנֵי ה' אֱלֹהֶיךְ. הַפְּסוּקִים הַלָּלוּ כְּשֶׁיִּשְׂרָאֵל הָיוּ שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה וְנִרְאוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּבֵית הַמִּקְדָּשׁ, הָיוּ מִתְקַיְּמִים. עַכְשָׁו אֵיךְ מִתְקַיְּמִים? מִי יָכוֹל לֶאֱכֹל לִפְנֵי ה' וְלִשְׂמֹחַ לִפְנֵי ה'?</p>\n<p>אֶלָּא וַדַּאי כָּךְ הוּא. בָּרִאשׁוֹנָה כְּשֶׁיָּשַׁב אָדָם עַל שֻׁלְחָנוֹ לֶאֱכֹל, מְבָרֵךְ עַל הַלֶּחֶם הַמּוֹצִיא. מָה הַטַּעַם הַמּוֹצִיא וְלֹא מוֹצִיא, שֶׁהֲרֵי כָּתוּב בּוֹרֵא הַשָּׁמַיִם, וְלֹא כָתוּב הַבּוֹרֵא. עוֹשֶׂה אֶרֶץ, וְלֹא כָתוּב הָעוֹשֶׂה אֶרֶץ. מָה הַטַּעַם כָּאן הַמּוֹצִיא?</p>\n<p>אֶלָּא כָּל הַדְּבָרִים שֶׁהֵם מִסּוֹד הָעוֹלָם הָעֶלְיוֹן הַנִּסְתָּר, מִסְתַּתֶּרֶת ה' מִשָּׁם, לְהַרְאוֹת שֶׁהֲרֵי מֵעוֹלָם גָּנוּז וְנִסְתָּר הוּא. וְכָל הַדְּבָרִים שֶׁהֵם מֵהָעוֹלָם הַתַּחְתּוֹן שֶׁנִּתְגַּלָּה יוֹתֵר כָּתוּב בְּה', שֶׁכָּתוּב (ישעיה מ) הַמּוֹצִיא בְּמִסְפָּר צְבָאָם, (עמוס ט) הַקֹּרֵא לְמֵי הַיָּם. כֻּלָּם הֵם מִסּוֹד הָעוֹלָם הַתַּחְתּוֹן, וְאִם נִכְתָּב בַּשֵּׁם הוּא בְּה', כְּמוֹ הָאֵל הַגָּדוֹל. וְכָאן שֶׁהוּא בְּדֶרֶךְ נִסְתָּר (בגלוי) מִסּוֹד הָעוֹלָם הַתַּחְתּוֹן הוּא, כֵּיוָן שֶׁמְּבָרֵךְ אָדָם, שְׁכִינָה בָּאָה לְפָנָיו.</p>\n<p>וּמַה שֶּׁאָמַר וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךְ, כָּאן נִכְלָל לְדַבֵּר בְּדִבְרֵי תוֹרָה, שֶׁכָּךְ צָרִיךְ, הוֹאִיל וְהַקָּדוֹשׁ בָּרוּךְ הוּא לְפָנָיו, לְקַיֵּם אֶת הַכָּתוּב, (יחזקאל מא) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה'. וְכָתוּב (דברים יד) וְאָכַלְתָּ שָּׁם לִפְנֵי ה' אֱלֹהֶיךְ.</p>\n<p>הוֹאִיל וְעוֹמֵד אָדָם לִפְנֵי רִבּוֹנוֹ, צָרִיךְ גַּם לְרַחֵם עַל הָעֲנִיִּים, לָתֵת לָהֶם כְּמוֹ שֶׁהוּא נָתַן לוֹ לֶאֱכֹל, (ומי שאוכל לפני המלך הקדוש, צריך) כְּמִי שֶׁאוֹכֵל לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְצָרִיךְ שֶׁלֹּא יִמָּצֵא בַּלְעָן עַל שֻׁלְחָנוֹ, שֶׁהֲרֵי בַּלְעָנוּת הִיא מֵהַצַּד הָאַחֵר, וְסוֹד זֶה - (בראשית כה) הַלְעִיטֵנִי נָא, דֶּרֶךְ בַּלְעָנוּת, וְכָךְ צָרִיךְ לַצַּד הָאַחֵר, וְכָתוּב (משלי יג) וּבֶטֶן רְשָׁעִים תֶּחְסָר. וְעַל זֶה וְאָכַלְתָּ לִפְנֵי ה' אֱלֹהֶיךְ כָּתוּב, וְלֹא לִפְנֵי הַצַּד הָאַחֵר. וְצָרִיךְ שֶׁלֹּא יִתְעַסֵּק בִּדְבָרִים בְּטֵלִים וּבְצָרְכֵי סְעוּדָה (יפה), וְצָרִיךְ לְהִתְעַסֵּק בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי כְּשֶׁדִּבְרֵי תוֹרָה נֶאֱמָרִים עַל שֻׁלְחָן, נוֹתֵן אוֹתוֹ הָאָדָם כֹּחַ לְרִבּוֹנוֹ.</p>\n<p>וְשָׂמַחְתָּ לִפְנֵי ה' אֱלֹהֶיךְ - זוֹהִי כּוֹס שֶׁל בְּרָכָה. כְּשֶׁמְּבָרֵךְ אָדָם בְּכוֹס שֶׁל בְּרָכָה, צָרִיךְ לִשְׂמֹחַ וּלְהַרְאוֹת שִׂמְחָה וְלֹא עֶצֶב כְּלָל. כֵּיוָן שֶׁנּוֹטֵל אָדָם כּוֹס שֶׁל בְּרָכָה, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד עַל גַּבּוֹ, וְהוּא צָרִיךְ לַעֲטֹף רֹאשׁוֹ בְּשִׂמְחָה וּלְבָרֵךְ עַל הַכּוֹס בְּמוֹשַׁב שְׁלֹשׁה: נְבָרֵךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ.</p>\n<p>וּבְטוּבוֹ חָיִינוּ, זֶה צָרִיךְ רָצוֹן לְמַעְלָה אֶל עַתִּיק הָעַתִּיקִים, וְעַל זֶה הִיא בְּדֶרֶךְ נִסְתָּר. וּבְטוּבוֹ, וְלֹא מִטּוּבוֹ. וּבְטוּבוֹ, זֶה הַיָּמִין (מינו) הָעֶלְיוֹן, וּמִטּוּבוֹ זוֹ דַּרְגָּה אַחֶרֶת שֶׁבָּאָה מִצַּד הַיָּמִין, וְהִיא דַּרְגָּה לְמַטָּה מִמֶּנּוּ, מִשּׁוּם שֶׁבְּאוֹתוֹ הַטּוֹב נִבְנָה הָעוֹלָם וּבוֹ נִזּוֹן.</p>\n<p>לָמָּה נִקְרָא טוֹב וְלָמָּה נִקְרָא חֶסֶד? הַטּוֹב הוּא כְּשֶׁכּוֹלֵל הַכֹּל בְּתוֹכוֹ וְלֹא מִתְפַּשֵּׁט לָרֶדֶת לְמַטָּה. חֶסֶד - כְּשֶׁיּוֹרֵד לְמַטָּה וְעוֹשֶׂה טוֹב בְּכָל הַבְּרִיּוֹת, בַּצַּדִּיקִים וּבָרְשָׁעִים, וְלֹא חוֹשֵׁשׁ, וְאַף עַל גַּב שֶׁדַּרְגָּה אַחַת הִיא. מִנַּיִן לָנוּ? שֶׁכָּתוּב (תהלים סג) אַךְ טוֹב וָחֶסֶד יִרְדְּפוּנִי. אִם טוֹב, לָמָּה חֶסֶד? וְאִם חֶסֶד, לָמָּה טוֹב, שֶׁהֲרֵי בְּאֶחָד מַסְפִּיק? אֶלָּא טוֹב כּוֹלֵל הַכֹּל בְּתוֹכוֹ, וְלֹא הִתְפַּשֵּׁט לְמַטָּה. חֶסֶד יוֹרֵד וּמִתְפַּשֵּׁט לְמַטָּה וְזָן לְכָל הַצַּדִּיקִים וְהָרְשָׁעִים כְּאֶחָד.</p>\n<p>וְכָאן, כֵּיוָן שֶׁאָמַר וּבְטוּבוֹ חָיִינוּ, חָזַר וְאָמַר, הַזָּן אֶת הָעוֹלָם כֻּלּוֹ בְּטוּבוֹ בְּחֶסֶד, זֶהוּ שֶׁכָּתוּב (תהלים קלו) נוֹתֵן לֶחֶם לְכָל בָּשָׂר כִּי לְעוֹלָם חַסְדּוֹ. וְעַל זֶה הַזָּן אֶת הַכֹּל, לַצַּדִּיקִים וְלָרְשָׁעִים, לַכֹּל. זֶה נִקְרָא בִּרְכַּת יָמִין. הַשְּׂמֹאל אֵינוֹ בְּבִרְכַּת הַמָּזוֹן, וְלָכֵן שְׂמֹאל לֹא תְסַיַּע לַיָּמִין.</p>\n<p>שֶׁכֵּיוָן שֶׁבֵּרַךְ בְּרָכָה, יָמִין (היין), צָרִיךְ לְדַבֵּק אֶת אֶרֶץ הַחַיִּים בַּיָּמִין, לְהִזּוֹן מִשָּׁם וּלְפַרְנֵס וְלָתֵת מָזוֹן לַכֹּל, וְלָכֵן הַשְּׁנִיָּה בִּרְכַּת הָאָרֶץ, וְצָרִיךְ לְהַזְכִּיר בָּהּ בְּרִית וְתוֹרָה: וְעַל בְּרִיתְךְ שֶׁחָתַמְתָּ בִּבְשָׂרֵנוּ, וְעַל תּוֹרָתְךְ שֶׁלִּמַּדְתָּנוּ. לְהַרְאוֹת שֶׁמֵּאוֹתוֹ טוֹב נִזּוֹן בְּרִית וְתוֹרָה, שֶׁהוּא הַתִּקּוּן שֶׁל הַטּוֹב הַזֶּה.</p>\n<p>מִכָּאן לָמַדְנוּ שֶׁנָּשִׁים פְּטוּרוֹת מִבִּרְכַּת הַמָּזוֹן לָצֵאת יְדֵי חוֹבָה, שֶׁהֲרֵי אֵין בָּהֶן תּוֹרָה וּבְרִית. וְלַחְתֹּם עַל הָאָרֶץ וְעַל הַמָּזוֹן, זֶה שֶׁדְּבֵקוּת כְּאֶחָד בְּחֶסֶד. עַל הָאָרֶץ - זוֹהִי אֶרֶץ הַחַיִּים. וְעַל הַמָּזוֹן - זֶהוּ חֶסֶד. הֲרֵי כְּלוּלִים זֶה בָּזֶה בִּדְבֵקוּת אַחַת.</p>\n<p>הִתְפַּשְּׁטוּת הַטּוֹב הִיא הוֹדָאָה שֶׁנִּקְרֵאת חֶסֶ\"ד, וְעַל זֶה הוּא אוֹמֵר נוֹדֶה לְךְ עַל כָּךְ וְעַל כָּךְ נִסִּים וְאוֹתוֹת שֶׁנַּעֲשׂוּ מִצַּד הַטּוֹב. וְאִם תֹּאמַר, וַהֲרֵי כָּתוּב נְעִמוֹת בִּימִינְךְ נֶצַח, זֶהוּ מִצַּד הַיָּמִין - לֹא כָּךְ, אֶלָּא כָּל אֶחָד וְאֶחָד מַרְאֶה עַל אוֹתוֹ מָקוֹם שֶׁיָּצָא מִמֶּנּוּ.</p>\n<p>וְאִם תֹּאמַר, נֶצַח בְּיָמִין - הֲרֵי כָּתוּב נְעִמוֹת, וְכָתוּב (שמואל ב כג) וּנְעִים זְמִרוֹת יִשְׂרָאֵל, (בימינך נצח) וְזֶה שְׂמֹאל, וְכָל שְׂמֹאל נִכְלָל בְּסוֹד הַיָּמִין. אֲבָל הוֹדָאָה, מוֹדֶה עַל הַיָּמִין, לְהַרְאוֹת שֶׁהֲרֵי מִמֶּנּוּ יָצָא, וְזוֹ הִתְפַּשְּׁטוּת הַטּוֹב שֶׁהִתְפַּשֵּׁט בְּאֶרֶץ הַחַיִּים.</p>\n<p>מָה הַטַּעַם אֵין כָּאן שְׂמֹאל? מִשּׁוּם שֶׁאֵין לוֹ חֵלֶק לַצַּד הָאַחֵר בִּמְזוֹנָם שֶׁל יִשְׂרָאֵל. וְאִם מִתְעוֹרֵר שְׂמֹאל, יִתְעוֹרֵר עִמּוֹ הַצַּד הָאַחֵר, וַהֲרֵי הוּא מָכַר בְּכוֹרָתוֹ וְחֶלְקוֹ לְיַעֲקֹב אָבִינוּ. וַהֲרֵינוּ נוֹתְנִים לוֹ חֶלְקוֹ לְאוֹתוֹ מְקַטְרֵג בַּזֻּהֲמָה שֶׁל מַיִם אַחֲרוֹנִים, וְאִם אֵין זֻהֲמָה, הֲרֵי חֶלְקוֹ בְּאוֹתוֹ מַאֲכָל שֶׁקָּרְבוּ בוֹ יָדַיִם.</p>\n<p>וְלָכֵן אֵין לוֹ חֵלֶק עִמָּנוּ. וְהוֹאִיל וְאֵין לוֹ חֵלֶק עִמָּנוּ, שֶׁהֲרֵי נָטַל חֶלְקוֹ, אֵין לָנוּ לְהָעִיר הַשְּׂמֹאל כְּלָל, שֶׁלֹּא יִתְעוֹרֵר הַמְקַטְרֵג לִטֹּל שְׁנֵי חֲלָקִים, אֶחָד לְמַטָּה וְאֶחָד לְמַעְלָה, כְּמוֹ בְכוֹר. שֶׁהֲרֵי מָכַר אֶת בְּכוֹרָתוֹ לְיַעֲקֹב אָבִינוּ - חֶלְקוֹ לְמַטָּה, וְאֵין לוֹ לְמַעְלָה כְּלוּם. יִשְׂרָאֵל נוֹטְלִים לְמַעְלָה, וְעֵשָׂו נוֹטֵל לְמַטָּה, וְעַל זֶה לֹא יִקְרַב הַשְּׂמֹאל כְּלָל בְּבִרְכַּת הַמָּזוֹן.</p>\n<p>כֵּיוָן שֶׁמִּתְבָּרֶכֶת אֶרֶץ הַחַיִּים הַזּוֹ מִצַּד הַיָּמִין וּמְקַבֶּלֶת מָזוֹן, אֲזַי מְבַקְשִׁים רַחֲמִים עַל הַכֹּל. רַחֵם ה' אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמָּךְ וְעַל יְרוּשָׁלַיִם עִירָךְ וְגוֹ'. שֶׁהֲרֵי מֵאוֹתוֹ מָזוֹן וְסִפּוּק שֶׁל אֶרֶץ הַחַיִּים נִזְכֶּה בָּהּ אֲנַחְנוּ וּבֵית הַמִּקְדָּשׁ, שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ לְמַטָּה בְּאוֹתָם רַחֲמִים.</p>\n<p>וּבְשַׁבָּת, כְּשֶׁהַדִּין לֹא נִמְצָא לִהְיוֹת נֶצַח וְהוֹד כְּלַל הַחֲסָדִים, אוֹמֵר רְצֵה וְהַחֲלִיצֵנוּ, לִהְיוֹת שְׁנֵיהֶם, (ישעיה נד) חַסְדֵי דָוִד הַנֶּאֱמָנִים, וְעַל זֶה אַל תְּהִי צָרָה וְיָגוֹן וְכוּ', שֶׁהֲרֵי רְצֵה וּמוֹדִים הֵם חַסְדֵי דָוִד, וְשִׂים שָׁלוֹם שֶׁאָמַרְנוּ בַּתְּפִלָּה בְּבִרְכַּת עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו הוּא בְרַחֲמָיו יַעֲשֶׂה שָׁלוֹם עָלֵינוּ.</p>\n<p>הַטוֹב וְהַמֵּטִיב, שֶׁהַכֹּל בָּא מִצַּד הַיָּמִין וְלֹא מִצַּד הַשְּׂמֹאל כְּלוּם. מִי שֶׁמְּבָרֵךְ בִּרְכַּת הַמָּזוֹן, הוּא נוֹטֵל בְּרָכוֹת בָּרִאשׁוֹנָה מִכֻּלָּם, וּמִתְבָּרֵךְ בַּכְּלָל שֶׁל בִּרְכַּת הַמָּזוֹן, וְעַל זֶה יֵשׁ לוֹ אֹרֶךְ חַיִּים. מִי שֶׁנּוֹטֵל כּוֹס שֶׁל בְּרָכָה וּמְבָרֵךְ עָלָיו, כָּתוּב (תהליםקטז) כּוֹס יְשׁוּעוֹת אֶשָּׂא. מִי הַיְשׁוּעוֹת? זֶה הַיָּמִין, שֶׁהוּא מוֹשִׁיעַ מִכָּל הַמְקַטְרְגִים שֶׁל הָעוֹלָם, שֶׁכָּתוּב (הושיעה לו ימינו) וַתּוֹשַׁע לוֹ יְמִינוֹ, וְכָתוּב (תהלים ס) הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי.</p>\n<p>בֵּין כָּךְ הֵאִיר הַיּוֹם, קָמוּ כֻלָּם וּנְשָׁקוּהוּ. אָמַר רַבִּי יוֹסֵי, וַדַּאי יוֹם מִשְׁתֶּה הוּא הַיּוֹם הַזֶּה, וְלֹא נֵצֵא מִכָּאן עַד שֶׁיַּעֲשֶׂה מִשְׁתֶּה לְכָל הָעִיר. זֶהוּ מִשְׁתֶּה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בּוֹ. לָקְחוּ אֶת אִשְׁתּוֹ וּבֵרְכוּ אוֹתָהּ בְּכַמָּה בְרָכוֹת. עָשׂוּ שֶׁאָבִיהָ יְתַקֵּן בַּיִת אַחֵר לַשִּׂמְחָה, כִּנְּסוּ אֶת כָּל אַנְשֵׁי הָעִיר לְאוֹתָהּ שִׂמְחָה, וְקָרְאוּ לָהּ כַּלָּה, וְשָׂמְחוּ עִמָּם כָּל אוֹתוֹ הַיּוֹם, וְהוּא שָׂמַח עִמָּם בְּדִבְרֵי תוֹרָה.</p>"],[9522011770,"<p>פָּתַח הוּא עַל הַשֻּׁלְחָן וְאָמַר, וְעָשִׂיתָ אֶת הַקְּרָשִׁים לַמִּשְׁכָּן עֲצֵי שִׁטִּים עֹמְדִים. כָּתוּב כָּאן עֹמְדִים, וְכָתוּב שָׁם (ישעיהו) שְׂרָפִים עֹמְדִים. מַה לְּהַלָּן שְׂרָפִים, אַף כָּאן גַּם שְׂרָפִים. אֵלּוּ הַקְּרָשִׁים עוֹמְדִים בְּתִקּוּנֵי כַלָּה וְסוֹבְבִים סְבִיב הַחֻפָּה, לְהַשְׁרוֹת בְּאוֹתָהּ חֻפָּה רוּחַ עֶלְיוֹנָה (סוד עליון). כְּמוֹ כֵן הַכַּלָּה לְמַטָּה צָרִיךְ לְתַקֵּן חֻפָּה לְכַסּוֹתָהּ בְּתִקּוּנֵי יֹפִי לִכְבוֹד כַּלָּה אַחֶרֶת שֶׁבָּאָה לִשְׁרוֹת שָׁם בְּשִׂמְחָה לַכַּלָּה הַתַּחְתּוֹנָה.</p>\n<p>וּמִשּׁוּם כְּבוֹד אוֹתָהּ הַכַּלָּה הָעֶלְיוֹנָה צָרִיךְ לַעֲשׂוֹת כִּסּוּי שֶׁל יֹפִי בְּכָל תִּקּוּנֵי יֹפִי, לְזַמֵּן אֶת הַכַּלָּה הָעֶלְיוֹנָה לְאוֹתָהּ שִׂמְחָה. כְּמוֹ זֶה בְּכָל מִילָה שֶׁל הַבְּרִית לְמַטָּה צָרִיךְ לְתַקֵּן כִּסֵּא אַחֵר בְּיֹפִי לְבַעַל הַקִּנְאָה שֶׁל אוֹת הַבְּרִית שֶׁבָּא לְשָׁם. אַף כָּאן בְּכָל חֻפָּה צָרִיךְ תִּקּוּנֵי יֹפִי לְכַסּוֹת אֶת הַחֻפָּה לִכְבוֹד הַכַּלָּה סְתָם.</p>\n<p>שֶׁהֲרֵי זוֹ כְּמוֹ שֶׁזּוֹ עוֹמֶדֶת. זוֹ עוֹלָה בְּשֶׁבַע בְּרָכוֹת, וְזוֹ עוֹלָה בְּשֶׁבַע בְּרָכוֹת. וּכְשֶׁעוֹלָה בְּשֶׁבַע בְּרָכוֹת, אָז נִקְרֵאת כַּלָּה. וְלָכֵן אָסוּר לְשַׁמֵּשׁ בָּהּ עַד שֶׁנִּכְלֶלֶת בְּאוֹתָן שֶׁבַע בְּרָכוֹת כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>אוֹתָן שֶׁבַע בְּרָכוֹת יוֹרֶשֶׁת הַכַּלָּה מֵרוּחַ (מסוד) עֶלְיוֹנָה, מָקוֹם שֶׁכָּל הַבְּרָכוֹת שׁוֹפְעוֹת מִשָּׁם. שֵׁשׁ בְּרָכוֹת הֵן שֶׁהַכַּלָּה מִתְבָּרֶכֶת מֵהֶן, וְאַתָּה אָמַרְתָּ שֶׁהֵן שֶׁבַע? אֶלָּא הַשְּׁבִיעִית הִיא שֶׁמְּקַיֶּמֶת אֶת כֻּלָּן.</p>\n<p>רֹב הַבְּרָכוֹת עַל הַיַּיִן לָמָּה? אֶלָּא שֶׁהוּא הַצַּד שֶׁמְּשַׂמֵּחַ אֶת הַכֹּל עַל אוֹתוֹ יַיִן שֶׁמְּשֻׁמָּר בַּעֲנָבָיו תָּמִיד. וּמִשּׁוּם כָּךְ הַבְּרָכָה הָרִאשׁוֹנָה שֶׁל אוֹתָן הַשֶּׁבַע הִיא סוֹד שֶׁל הַיַּיִן, יַיִן עוֹשֶׂה פְרִי (שמחה) בֵּין לְמַעְלָה בֵּין לְמַטָּה. גֶּפֶן נוֹטֶלֶת הַכֹּל, וּמוֹצִיאָה פְרִי לָעוֹלָם, וְהִתְעוֹרְרוּת שֶׁל שִׂמְחָה הִיא מִשְּׂמֹאל, שֶׁכָּתוּב (שירב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וְאוֹתוֹ עֵץ חַיִּים עוֹשֶׂה פֵרוֹת וְנִצָּנִים (באותה גפן) בַּהִתְעוֹרְרוּת הַזּוֹ, וְזוֹהִי הַבְּרָכָה הָרִאשׁוֹנָה שֶׁל הַכֹּל. (בורא פרי הגפן).</p>\n<p>הַשְּׁנִיָּה, שֶׁהַכֹּל בָּרָא לִכְבוֹדוֹ, הַסּוֹד שֶׁל הַבְּרִית הַקְּדוֹשָׁה, שִׂמְחַת הַחִבּוּר, שֶׁנּוֹטֵל אֶת כָּל הַבְּרָכוֹת מִסּוֹד הַיָּמִין לַעֲשׂוֹת פֵּרוֹת בְּאוֹתָהּ גֶּפֶן, שֶׁהֲרֵי בָּרִאשׁוֹנָה אוֹתוֹ פְּרִי (שמחה) יוֹרֵד מִלְמַעְלָה דֶּרֶךְ הָאֵיבָרִים, וְשׁוֹפֵעַ לַבְּרִית הַקְּדוֹשָׁה לְהַשְׁפִּיעָהּ בְּאוֹתָהּ הַגֶּפֶן, וְזֶה מִצַּד הַיָּמִין, שֶׁהֲרֵי אֵין פְּרִי נִמְצָא אֶלָּא בַּיָּמִין. הַשְּׂמֹאל מִתְעוֹרֵר וְהַיָּמִין עוֹשֶׂה.</p>\n<p>אַחַר כָּךְ נִכְלָל הַשְּׂמֹאל בַּיָּמִין וְהַיָּמִין בַּשְּׂמֹאל לִהְיוֹת סוֹד שֶׁל אָדָם, וְלָכֵן הַשְׁלִישִׁית הִיא יוֹצֵר הָאָדָם. וְעַל זֶה יַעֲקֹב, שֶׁהוּא עַמּוּד הָאֶמְצָעִי, דְּמוּתוֹ שֶׁל אָדָם הוּא הָיָה.</p>\n<p>הָרְבִיעִית הִיא עַמּוּד אֶחָד שֶׁל יֶרֶךְ יָמִין. הַחֲמִישִׁית - שׂוֹשׂ תָּשִׂישׂ וְתָגֵל עֲקֶרֶת הַבַּיִת בְּשִׂמְחָה בְּקִבּוּץ וְכִנּוּס בָּנֶיהָ מֵאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְזֶה סוֹד שֶׁל יָרֵךְ אַחֶרֶת שֶׁמִּתְחַבֶּרֶת בְּיֶרֶךְ שְׂמֹאל לָלֶכֶת וְלִכְנֹס אֶת כָּל הַצְּדָדִים, וְכִנּוּס הַבָּנִים, וְאַהֲבָה לְהַכְנִיסָם בֵּין הַבִּרְכַּיִם.</p>\n<p>וּבְאוֹתָם הַשְּׁנַיִם שֶׁהַנְּבִיאִים שׁוֹרִים בְּתוֹכָם, שִׂמְחַת עֲקֶרֶת הַבַּיִת. מָה הַטַּעַם? מִשּׁוּם שֶׁהֲרֵי שְׁתֵּי עֲרָבוֹת לֹא עוֹשׂוֹת נִצָּנִים וּפֵרוֹת, וְכִנּוּס הַבָּנִים אֲלֵיהֶם הֵם פֵּרוֹת וְנִצָּנִים שֶׁלָּהֶם, וְלֹא מְעִירִים כִּנּוּס שֶׁל בָּנֶיהָ אֵלֶיהָ, רַק בַּנְּבִיאִים.</p>\n<p>בְּרָכָה שִׁשִּׁית - שַׂמֵּחַ תְּשַׂמַּח רֵעִים הָאֲהוּבִים, מָקוֹם שֶׁל רָצוֹן וְשִׂמְחָה וְאַחֲוָה נִמְצָאִים, הָעַמּוּד שֶׁל כָּל הָעוֹלָם שֶׁנִּקְרָא צַדִּיק, וְצַדִּיק וְצֶדֶק הֵם רֵעִים וַאֲהוּבִים שֶׁלֹּא זָזִים זֶה מִזֶּה. עַד כָּאן שֵׁשׁ בְּרָכוֹת שֶׁכַּלָּה מִתְבָּרֶכֶת מֵהֶן.</p>\n<p>הַבְּרָכָה הַשְּׁבִיעִית מְקַיֶּמֶת הַכֹּל, וּמֵהַשְּׁבִיעִית הַזּוֹ הַכֹּל מִתְבָּרְכִים וַדַּאי, כְּלָל שֶׁל עֶשֶׂר אֲמִירוֹת, מִשּׁוּם שֶׁזּוֹ כּוֹלֶלֶת מַעְלָה וּמַטָּה, וְלָכֵן כְּלוּלִים בְּזוֹ עֲשָׂרָה מִינֵי שִׂמְחָה: שָׂשׂוֹן, שִׂמְחָה, חָתָן, (וכלה, גילה, דיצה, אהבה, ואחוה, שלום) וְכַלָּה, אַהֲבָה, אַחֲוָה, גִּילָה, רִנָּה, דִּיצָה, חֶדְוָה, שָׁלוֹם וְרֵעוּת. לִהְיוֹת הַכַּלָּה שְׁלֵמוּת הַכֹּל.</p>\n<p>אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהֵם זָכוּ לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, עֲלֵיהֶם כָּתוּב (שמואל ב ז) וּמִי כְעַמְּךְ כְּיִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. שָׂמְחוּ כֻלָּם כָּל אוֹתוֹ יוֹם בְּדִבְרֵי תוֹרָה, וְכָל בְּנֵי הָעִיר עָשׂוּ אוֹתוֹ רֹאשׁ עֲלֵיהֶם. לְיוֹם אַחֵר קָמוּ רַבִּי יוֹסֵי וְרַבִּי חִיָּיא, וּבֵרְכוּ אוֹתָם וְהָלְכוּ לְדַרְכָּם.</p>\n<p>כְּשֶׁהִגִּיעוּ לְרַבִּי שִׁמְעוֹן, הֵרִים עֵינָיו וְרָאָה אוֹתָם. אָמַר, מִסְתַּכֵּל הָיִיתִי בָכֶם הַיּוֹם הַזֶּה, וְרָאִיתִי אֶתְכֶם שְׁנֵי יָמִים וְלַיְלָה שֶׁהֱיִיתֶם בְּמִשְׁכָּנוֹ שֶׁל אוֹתוֹ נַעַר מְטַטְרוֹן, וְאוֹתוֹ נַעַר הָיָה מְלַמֵּד אֶתְכֶם סוֹדוֹת עֶלְיוֹנִים בְּשִׂמְחַת הַתּוֹרָה. אַשְׁרֵי חֶלְקְכֶם בָּנַי!</p>\n<p>סִדְּרוּ כֻלָּם אֶת הַדְּבָרִים לְפָנָיו, וְסָחוּ לוֹ אֶת הַמַּעֲשֶׂה. אָמַר לָהֶם, אַשְׁרֵיכֶם וְאַשְׁרֵי חֶלְקִי, שֶׁהֲרֵינִי נִזְכָּר יוֹם אֶחָד שֶׁהָיָה הוֹלֵךְ עִמִּי בַּדֶּרֶךְ רַב סַפְרָא אָבִיו, וּבֵרַכְתִּי אוֹתוֹ כַּאֲשֶׁר נִפְרַד מִמֶּנִּי שֶׁיִּהְיֶה לוֹ בֵּן אַרְיֵה בַּתּוֹרָה, וְלֹא בֵרַכְתִּי אוֹתוֹ שֶׁהוּא יִזְכֶּה בּוֹ. אַשְׁרֵי חֶלְקְכֶם בָּנַי, עֲלֵיכֶם כָּתוּב (ישעיה נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה'.</p>\n<p>דָּבָר אַחֵר וְכָל בָּנַיִךְ לִמּוּדֵי ה' - וְכִי כָּל הַבָּנִים שֶׁהֵם שֶׁל יִשְׂרָאֵל, אֶת כֻּלָּם מְלַמֵּד הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה? כֵּן. שֶׁהֲרֵי בְּשָׁעָה שֶׁאוֹתָם תִּינוֹקוֹת לוֹמְדִים תּוֹרָה, הַשְּׁכִינָה בָּאָה וְנוֹתֶנֶת לָהֶם כֹּחַ וְחֹזֶק לִלְמֹד תּוֹרָה. שֶׁאִלְמָלֵא סִיּוּעוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵין אוֹתָם הַתִּינוֹקוֹת יְכוֹלִים לִסְבֹּל.</p>"],[9522011771,"<p>רַבִּי שִׁמְעוֹן הָיָה מָצוּי יוֹם אֶחָד לְיַד הַפֶּתַח שֶׁל לוֹד, וְרַבִּי חִיָּיא עִמּוֹ. פָּגַשׁ בּוֹ תִּינוֹק אֶחָד. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה (יעורר) בָּעוֹלָם עַכְשָׁו לְיָמִים מְעַטִּים גִּלְגּוּל גָּדוֹל לְמַלְכֵי הָאָרֶץ אֵלֶּה בְּאֵלֶּה. וַדַּאי שֶׁבְּעוֹד שֶׁהֵם מְצִיקִים אֵלֶּה לְאֵלֶּה, יִשְׂרָאֵל יִהְיוּ בְּתוֹךְ רְוָחָה.</p>\n<p>אָמַר אוֹתוֹ תִינוֹק, וַהֲרֵי בְּיוֹם זֶה הִתְחִילָה הִתְעוֹרְרוּת זוֹ, שֶׁהֲרֵי בְּיוֹם זֶה דָּמִים רַבִּים נִשְׁפָּכִים בָּעוֹלָם. אָמַר לוֹ רַבִּי חִיָּיא, מִנַּיִן לוֹ לְזֶה הַתִּינוֹק? אָמַר רַבִּי שִׁמְעוֹן, לִפְעָמִים נְבוּאָה נוֹפֶלֶת בְּפִי הַתִּינוֹקוֹת וּמִתְנַבְּאִים יוֹתֵר מֵאַחַד הַנְּבִיאִים.</p>\n<p>אָמַר אוֹתוֹ תִינוֹק, וְכִי תְמִיהָה הִיא שֶׁתִּהְיֶה לַתִּינוֹקוֹת נְבוּאָה?! וַהֲרֵי הוּא פָּסוּק שָׁלֵם. מִנַּיִן לָנוּ? שֶׁכָּתוּב וְכָל בָּנַיִךְ לִמּוּדֵי ה'. הֵם וַדַּאי לִמּוּדֵי ה', וּנְבוּאָה יוֹצֵאת מֵהֶם, מַה שֶּׁאֵין כֵּן לְכָל הָעוֹלָם, אֶלָּא לְיִשְׂרָאֵל לְבַדָּם, שֶׁכָּתוּב בָּהֶם וְכָל בָּנַיִךְ לִמּוּדֵי ה', וּמִשּׁוּם כָּךְ יוֹצֵאת מֵהֶם נְבוּאָה. בָּא רַבִּי שִׁמְעוֹן וּנְשָׁקוֹ. אָמַר, מִיָּמַי לֹא שָׁמַעְתִּי אֶת זֶה, רַק עַכְשָׁו.</p>"],[9522011772,"<p>זוֹ מִצְוַת הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, וְעָשִׂיתָ אֶת הַקְּרָשִׁים לַמִּשְׁכָּן עֲצֵי שִׁטִּים עֹמְדִים. (הכל כדגמא העליונה) (פתח רבי יצחק) וְכָתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם וְגוֹ'. מַעֲשֵׂה הַמִּשְׁכָּן בְּאוֹתָם קְרָשִׁים כְּמוֹ אוֹתָם הַשְּׂרָפִים, (במקום זה) אֵלֶּה עוֹמְדִים וְאֵלֶּה עוֹמְדִים.</p>\n<p>וְאִם תֹּאמַר, וַהֲרֵי כָּל חֵילוֹת הַשָּׁמַיִם כֻּלָּם עוֹמְדִים, כְּמוֹ שֶׁנֶּאֱמַר וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה, וְכָתוּב וְכָל צְבָא הַשָּׁמַיִם עֹמְדִים עָלָיו וְגוֹ', שֶׁהֲרֵי כָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים אֵין לָהֶם כְּרָעַיִם, וְכֻלָּם עוֹמְדִים בְּקִימָה? אֶלָּא וַדַּאי כֻּלָּם עוֹמְדִים, וְלִפְעָמִים אֵלֶּה נִקְרָאִים שְׂרָפִים, וְלִפְעָמִים עוֹלִים בְּשֵׁם אַחֵר, אֲבָל אֵלֶּה כֻּלָּם עוֹמְדִים בְּשֵׁם אֶחָד.</p>"],[9522011773,"<p>וּפָסוּק זֶה פֵּרְשׁוּהוּ, (רבי יצחק פתח) כָּתוּב (תהליםכג) מִזְמוֹר לְדָוִד ה' רֹעִי לֹא אֶחְסָר. הֲרֵי נִתְבָּאֵר, מַה בֵּין מִזְמוֹר לְדָוִד וּבֵין לְדָוִד מִזְמוֹר? וְכָאן שְׁכִינָה קָדְמָה וּבָאָה וְשָׁרְתָה עָלָיו בָּרִאשׁוֹנָה. ה' רֹעִי, וְכִי לָמָּה שְׁכִינָה קָדְמָה לְכָאן, וַהֲרֵי דָּוִד צָרִיךְ לְהַקְדִּים (לעורר) בָּרִאשׁוֹנָה, הוֹאִיל וּמְבַקֵּשׁ מְזוֹנוֹ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>אֶלָּא וַדַּאי שְׁכִינָה קָדְמָה וּבָאָה וְשָׁרְתָה עָלָיו וְהֵעִירָה אוֹתוֹ לְשַׁבֵּחַ לַמֶּלֶךְ אֶת הַשֶּׁבַח הַזֶּה וּלְבַקֵּשׁ מְזוֹנוֹת מִלִּפְנֵי הַמֶּלֶךְ, שֶׁהֲרֵי כָּךְ צָרִיךְ עַל דָּבָר שֶׁל מָזוֹן שֶׁהִיא רוֹצָה וְהָרָצוֹן שֶׁלָּהּ, שֶׁכָּל בְּנֵי הָעוֹלָם יְבַקְשׁוּ מְזוֹנוֹת. מִשּׁוּם שֶׁכַּאֲשֶׁר הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְהוֹרִיד מְזוֹנוֹת לָעוֹלָם, הִיא נוֹטֶלֶת בָּרִאשׁוֹנָה, וְעָלֶיהָ יוֹרְדִים מְזוֹנוֹת לְכָל הָעוֹלָמוֹת. וּמִשּׁוּם כָּךְ הִיא הִקְדִּימָה לְדָבָר זֶה שֶׁל מְזוֹנוֹת, וְשָׁרְתָה עַל דָּוִד.</p>\n<p>ה' רֹעִי - ה' הָרוֹעֶה שֶׁלִּי. כָּרוֹעֶה הַזֶּה שֶׁמַּנְהִיג צֹאנוֹ בְּמָקוֹם שֶׁל דְּשָׁאִים וַעֲשָׂבִים שֶׁלֹּא חָסְרוּ דָבָר, אַף כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא הָרוֹעֶה שֶׁלִּי לָזוּן אוֹתִי בְּכָל מַה שֶּׁאֲנִי צָרִיךְ. דָּבָר אַחֵר ה' רֹעִי - שָׁנִינוּ שֶׁקָּשִׁים מְזוֹנוֹת שֶׁל אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ קְרִיעַת יַם סוּף. כָּאן הֵם שְׁנֵי גְוָנִים, וּשְׁנֵיהֶם בְּדֶרֶךְ אֱמֶת.</p>"],[9522011774,"<p>אֶחָד בִּשְׁבִיל שֶׁכָּל מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין וֶאֱמֶת, וְעַל הַדִּין וְהָאֱמֶת מִתְקַיֵּם כָּל הָעוֹלָם, וּבְכָל יוֹם וָיוֹם וּבְכָל זְמַן וּזְמַן דָּן אֶת כָּל הָעוֹלָם בְּדִין, אֶת הַצַּדִּיקִים וְאֶת הָרְשָׁעִים וְאֶת כָּל בְּנֵי הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים יא) כִּי צַדִּיק ה' צְדָקוֹת אָהֵב. וּכְשֶׁהוּא דָּן בְּנֵי אָדָם וְרוֹאֶה בְּנֵי אָדָם כַּמָּה רְשָׁעִים וְכַמָּה חַטָּאִים לְפָנָיו, אָז קָשֶׁה בְעֵינָיו לָתֵת לָהֶם מָזוֹן בְּכָל זְמַן, כִּי יֵשׁ לוֹ לָזוּן אֶת הָרְשָׁעִים וְאֶת אוֹתָם שֶׁחוֹטְאִים.</p>\n<p>וְהוּא עוֹשֶׂה עִמָּהֶם לִפְנִים מִשּׁוּרַת הַדִּין, וְזָן וּמְפַרְנֵס אוֹתָהּ כְּפִי הַחֶסֶד הָעֶלְיוֹן שֶׁנִּמְשָׁךְ וְנִשְׁפָּע עַל כָּל (העמים ובני) בְּנֵי הָעוֹלָם, וּבוֹ הוּא זָן וּמְפַרְנֵס אֶת הַכֹּל, אֶת הַצַּדִּיקִים וְאֶת הַחֲסִידִים וְאֶת הָרְשָׁעִים, וְאֶת כָּל אוֹתָם בְּנֵי הָעוֹלָם, וְאֶת כָּל הַחַיּוֹת וּבַהֲמוֹת הַשָּׂדֶה וְעוֹפוֹת הַשָּׁמַיִם, מִקַּרְנֵי רְאֵמִים וְעַד בֵּיצֵי כִנִּים, וְלֹא נִשְׁאָר בָּעוֹלָם מִי שֶׁאֵינוֹ זָן וּמְפַרְנֵס אֶת הַכֹּל, אַף עַל גַּב שֶׁקָּשֶׁה לְפָנָיו, לְפִי מַעֲשֵׂי בְּנֵי הָעוֹלָם, כִּקְרִיעַת יַם סוּף.</p>\n<p>וְכִי קְרִיעַת יַם סוּף קָשֶׁה לְפָנָיו, וַהֲרֵי כָּתוּב (נחום א) גּוֹעֵר בַּיָּם וַיַּבְּשֵׁהוּ, (עמוס ט) הַקֹּרֵא לְמֵי הַיָּם וַיִּשְׁפְּכֵם עַל פְּנֵי הָאָרֶץ, וַהֲרֵי כֵּיוָן שֶׁעָלָה רָצוֹן לְפָנָיו, הַכֹּל לְפָנָיו כְּאַיִן הוּא חָשׁוּב, וְאַתָּה אָמַרְתָּ שֶׁקְּרִיעַת יַם סוּף קָשֶׁה לְפָנָיו?!</p>\n<p>אֶלָּא, בִּזְמַן שֶׁיִּשְׂרָאֵל עָבְרוּ לַיָּם וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִקְרֹעַ לָהֶם אֶת יַם סוּף, בָּא רַהַב, אוֹתוֹ מְמֻנֶּה עַל מִצְרַיִם, וּבִקֵּשׁ דִּין מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר לְפָנָיו, רִבּוֹן הָעוֹלָם, לָמָּה אַתָּה רוֹצֶה לַעֲשׂוֹת דִּין עַל מִצְרַיִם וְלִקְרֹעַ אֶת הַיָּם לְיִשְׂרָאֵל, הֲרֵי כֻּלָּם רְשָׁעִים לְפָנֶיךְ, וְכָל דַּרְכְּךְ בְּדִין וֶאֱמֶת? אֵלֶּה עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְאֵלֶּה עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. אֵלּוּ בְּגִלּוּי עֲרָיוֹת, וְאֵלּוּ בְּגִלּוּי עֲרָיוֹת. אֵלּוּ שׁוֹפְכֵי דָמִים, וְאֵלּוּ שׁוֹפְכֵי דָמִים.</p>\n<p>בְּאוֹתָהּ שָׁעָה הָיָה קָשֶׁה לְפָנָיו לַעֲבֹר עַל דֶּרֶךְ הַדִּין. וַהֲרֵי יִשְׂרָאֵל הָיוּ נוֹסְעִים עַל הַיָּם, שֶׁכָּתוּב (שמות יד) וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִסָּעוּ. וְהָיָה קָשֶׁה לְפָנָיו לַעֲבֹר עַל הַדִּין וְלִקְרֹעַ לָהֶם אֶת יַם סוּף, וְאִלְמָלֵא שֶׁהִשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּזְכוּת אַבְרָהָם שֶׁהִקְדִּים בַּבֹּקֶר לַעֲשׂוֹת מִצְוַת רִבּוֹנוֹ וּרְצוֹנוֹ, כַּכָּתוּב (בראשית כב) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר - כֻּלָּם הָיוּ אוֹבְדִים בַּיָּם, מִשּׁוּם שֶׁבְּכָל אוֹתוֹ הַלַּיְלָה הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין עַל יִשְׂרָאֵל.</p>\n<p>שֶׁשָּׁנִינוּ, מַה שֶּׁכָּתוּב וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלַּיְלָה, מְלַמֵּד שֶׁבָּאוּ מַלְאָכִים עֶלְיוֹנִים לְשַׁבֵּחַ בְּאוֹתוֹ לַיְלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָמַר לָהֶם: וְכִי (בני) מַעֲשֵׂי יָדַי טוֹבְעִים בַּיָּם וְאַתֶּם מְשַׁבְּחִים לְפָנַי?! מִיָּד - וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלַּיְלָה. מַה כָּתוּב? וַיְהִי בְּאַשְׁמֹרֶת הַבֹּקֶר. הִשְׁגִּיחַ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּזְכוּת אַבְרָהָם שֶׁהִקְדִּים בַּבֹּקֶר לַעֲשׂוֹת רְצוֹן רִבּוֹנוֹ, כַּכָּתוּב וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר. אָז חָזַר הַיָּם, וּבָרְחוּ הַמַּיִם מִלִּפְנֵי יִשְׂרָאֵל.</p>\n<p>שֶׁכָּתוּב, וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. וְשָׁנִינוּ, לְאֵיתָנוֹ - לִתְנָאוֹ, לְאוֹתוֹ תְנַאי שֶׁהִתְנָה עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁבָּרָא אֶת הָעוֹלָם. לְאֵיתָנוֹ, כָּתוּב כָּאן לְאֵיתָנוֹ, וְכָתוּב שָׁם (תהלים פט) מַשְׂכִּיל לְאֵיתָן הָאֶזְרָחִי, וְעַל זֶה לִפְנוֹת בֹּקֶר, בְּאוֹתוֹ זְמַן שֶׁהִקְדִּים אַבְרָהָם לַעֲשׂוֹת רְצוֹן רִבּוֹנוֹ אָז נִקְרַע הַיָּם, (כאן ויהם את מחנה מצרים) וְלָכֵן קָשֶׁה הָיָה לְפָנָיו קְרִיעַת יַם סוּף.</p>"],[9522011775,"<p>כְּמוֹ כֵן קָשִׁים הַזִּוּוּגִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כִּקְרִיעַת יַם סוּף. מַה קְּרִיעַת יַם סוּף הָרַג אֶת אֵלֶּה בַּצַּד הַזֶּה, וְקִיֵּם אֶת אֵלֶּה בַּצַּד הַהוּא - אַף כָּאן בַּזִּוּוּגִים, כָּתוּב (תהלים סח) מוֹצִיא אֲסִירִים בַּכּוֹשָׁרוֹת, וְשָׁנִינוּ - בְּכִי וְשִׁירוֹת. מֵמִית אֶת זֶה, וְנוֹתֵן אֶת אִשְׁתּוֹ לְזֶה, וְלִפְעָמִים לָרָשָׁע מִזְדַּמֶּנֶת אִשָּׁה מְעֻלָּה. אֲבָל סוֹדוֹת נִסְתָּרִים הֵם בַּכֹּל, וְהַכֹּל הוּא בְּדִין. וּמַה שֶּׁהֵעִירוּ הַחֲבֵרִים בָּזֶה, וַדַּאי כָּךְ הוּא.</p>\n<p>וּמַה שֶּׁהֵעִירוּ לִפְנֵי וְלֹא מִלְּפָנַי - לִפְנֵי אוֹתוֹ שֶׁעוֹמֵד לִפְנֵי, לְפָנָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשִׁמֵּשׁ לְפָנָיו. וְעַל כָּךְ לֹא אָמְרוּ שֶׁקָּשִׁים הַזִּוּוּגִים לַקָּדוֹשׁ- בָּרוּךְ- הוּא, וְכֵן קָשִׁים מְזוֹנוֹתָיו שֶׁל אָדָם לַקָּדוֹשׁ- בָּרוּךְ-הוּא, אֶלָּא לִפְנֵי, וְלָזֶה קָשִׁים כָּל אֵלֶּה, שֶׁהֲרֵי לֹא בִרְשׁוּתָם הֵם עוֹמְדִים. אַף עַל גַּב שֶׁהוּא עוֹשֶׂה, (אבל אף על גב שהוא עושה) בְּרָשׁוּת אַחֶרֶת הוּא עוֹשֶׂה.</p>\n<p>כָּתוּב (ויקרא כב) וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מִלְּפָנַי. מַה זֶּה מִלְּפָנַי? אֶלָּא זֶה הָעוֹלָם הַבָּא, הַהוּא שֶׁכָּל הַחַיִּים עוֹמְדִים שָׁם. דָּבָר אַחֵר, זֶה צִנּוֹר עֶלְיוֹן, נָהָר שֶׁאֵין מֵימָיו פּוֹסְקִים לְעוֹלָמִים, וְהַכֹּל אֶחָד. וְזֶהוּ שֶׁנּוֹטֵל אֶת כָּל הָעִדּוּנִים שֶׁל הָעוֹלָם הַבָּא, וּמֵאוֹתָם עִדּוּנִים עֶלְיוֹנִים תִּתְכַּלֶּה (הגפש הזו), מִמָּקוֹם שֶׁשָּׁם אוֹתוֹ נֹעַם ה', וְזֶהוּ מִלְּפָנַי.</p>\n<p>וְאִם תֹּאמַר, אִם כָּךְ, הֲרֵי כָּתוּב (יונה א) וַיָּקָם יוֹנָה לִבְרֹחַ תַּרְשִׁישָׁה מִלִּפְנֵי ה'. כִּי יָדְעוּ הָאֲנָשִׁים כִּי מִלִּפְנֵי ה' הוּא ברֵחַ. וְשָׁנִינוּ, מָה הַטַּעַם הָלַךְ יוֹנָה וּבָרַח? וְכִי מִי יָכוֹל לִבְרֹחַ מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא?! אֶלָּא הָיָה הוֹלֵךְ וּבוֹרֵחַ לָצֵאת מֵהָאָרֶץ הַקְּדוֹשָׁה, שֶׁהֲרֵי הַשְּׁכִינָה אֵינָהּ שׁוֹרָה מִחוּץ לְאֶרֶץ יִשְׂרָאֵל, וּמִשּׁוּם שֶׁלֹּא תִשְׁרֶה עָלָיו הַשְּׁכִינָה, הָיָה בוֹרֵחַ מֵאֶרֶץ הַקֹּדֶשׁ, שֶׁהֲרֵי הַשְׁכִינָה שׁוֹרָה שָׁם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ. גֶּפֶן פֹּרִיָּה - זוֹ שְׁכִינָה. מַה שְּׁכִינָה הָיְתָה נִסְתֶּרֶת בְּתוֹךְ בֵּית קָדְשֵׁי הַקְּדָשִׁים, אַף כָּךְ אִשָּׁה צְנוּעָה לֹא יוֹצֵאת מִשַּׁעַר בֵּיתָהּ הַחוּצָה. וּמִשּׁוּם כָּךְ הָיָה בּוֹרֵחַ יוֹנָה מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, וַהֲרֵי כָּאן כָּתוּב מִלִּפְנֵי, וְלֹא כָתוּב לִפְנֵי.</p>\n<p>אֶלָּא וַדַּאי כָּךְ הוּא - מִלִּפְנֵי, שֶׁהֲרֵי רוּחַ נְבוּאָה לֹא בָאָה מִתּוֹךְ שְׁכִינָה אֶלָּא מִלִּפְנֵי. אוֹתָן שְׁתֵּי דַרְגּוֹת הַנְּבִיאִים שֶׁשּׁוֹרִים עַל הַשְּׁכִינָה, וּמֵאוֹתוֹ מָקוֹם פַּחַד לִהְיוֹת שָׁם בָּאָרֶץ הַקְּדוֹשָׁה, וְעַל זֶה מִלִּפְנֵי. כִּי מִלִּפְנֵי ה' הוּא ברֵחַ, וְלֹא לִפְנֵי ה', שֶׁהֲרֵי הָיָה יוֹדֵעַ שֶׁנְּבוּאָה לֹא הָיְתָה בָאָה אֶלָּא מִלִּפְנֵי.</p>\n<p>וּמִשּׁוּם כָּךְ קָשִׁים זִוּוּגִים, קָשִׁים מְזוֹנוֹתָיו שֶׁל אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן דָּוִד הַמֶּלֶךְ תָּלָה מְזוֹנוֹתָיו לְמַעְלָה, מִשּׁוּם שֶׁלְּמַעְלָה לֹא פוֹסֵק לְעוֹלָמִים. אֲבָל כָּאן פּוֹסֵק, שֶׁהֲרֵי לֹא תְלוּיִים בּוֹ מְזוֹנוֹת. לְמַעְלָה הֵם. וְעַל זֶה כָּתוּב (תהלים כג) ה' רֹעִי לֹא אֶחְסָר, לֹא יִפְסְקוּ מְזוֹנוֹת מִמֶּנִּי לְעוֹלָמִים, מִשּׁוּם שֶׁאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן לֹא פוֹסֵק לְעוֹלָמִים, וּמִשּׁוּם זֶה קוֹדֶמֶת שְׁכִינָה עַל זֶה.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאוֹתוֹ מָקוֹם מְקַבֵּל מְזוֹנוֹת מִלְמַעְלָה, כָּל הַמְקַדְּשִׁים אֶת רִבּוֹנָם, כֻּלָּם מִתְעַדְּנִים וּמִתְעוֹרְרִים וּמַעֲלִים כְּנָפַיִם כְּשֶׁבָּאָה שְׁכִינָה עִם אוֹתוֹ מָזוֹן, כְּדֵי שֶׁלֹּא יִסְתַּכְּלוּ בָהּ.</p>\n<p>וְאוֹתָן שָׁלֹשׁ מַחֲנוֹת בַּעֲלִיָּה אַחַת קוֹרְאִים וְאוֹמְרִים קָדוֹשׁ. אֵלֶּה קוֹרְאִים לְמַחֲנֶה שֵׁנִי, וּמַעֲלִים כְּנָפַיִם אֵלֶּה הָרִאשׁוֹנִים וְאֵלֶּה הַשְּׁנִיִּים, וְאוֹמְרִים הַשְּׁנִיִּים הַלָּלוּ קָדוֹשׁ. אֵלֶּה קוֹרְאִים לְמַחֲנֶה שְׁלִישִׁי וּמַעֲלִים כְּנָפַיִם שְׁלֹשׁ הַמַּחֲנוֹת כְּאֶחָד, וְכֻלָּם אוֹמְרִים: קָדוֹשׁ ה' צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. וְעַל זֶה כֻּלָּם מְשֻׁלָּבִים זֶה בָּזֶה, אֵלֶּה נִכְנָסִים לְתוֹךְ אֵלֶּה, וְאֵלֶּה נִכְנָסִים לְתוֹךְ אֵלֶּה, מְשֻׁלָּבִים זֶה בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר מְשֻׁלָּבת אִשָּׁה אֶל אֲחֹתָהּ כֵּן תַּעֲשֶׂה לְכֹל קַרְשֵׁי הַמִּשְׁכָּן.</p>\n<p>הַקְּרָשִׁים עוֹמְדִים תָּמִיד בְּקִיּוּמָם וְלֹא מִתְכּוֹפְפִים, כְּמוֹ שֶׁהֵם עוֹמְדִים, שֶׁלֹּא מִתְכּוֹפְפִים, שֶׁאֵין לָהֶם כְּרָעַיִם, וְעוֹמְדִים תָּמִיד בְּלִי יְשִׁיבָה, וְעַל זֶה כָּתוּב בַּקְּרָשִׁים, עֹמְדִים.</p>\n<p>מַה כָּתוּב? שְׁתֵּי יָדוֹת לַקֶּרֶשׁ הָאֶחָד. אַף כָּךְ בִּשְׁנֵי גְוָנִים הֵם כְּלוּלִים כָּל אֶחָד וְאֶחָד מֵהֶם, אוֹתוֹ שֶׁלּוֹ וְשֶׁל חֲבֵרוֹ, וַחֲבֵרוֹ אַף כָּךְ יֵשׁ בּוֹ, וְעַל זֶה מְשֻׁלָּבִים זֶה עִם זֶה. (זה נוטל שלו ושל חברו, וזה נוטל שלו ושל חברו).</p>\n<p>כְּדֻגְמַת זֶה כָּתוּב בַּתּוֹרָה, (משלי ג) כִּי טוֹב סַחְרָהּ מִסְּחַר כָּסֶף וּמֵחָרוּץ תְּבוּאָתָהּ. זֶה מְלַמֵּד לְזֶה, וְזֶה מְלַמֵּד לְזֶה. נַעֲשׂוּ מְשֻׁלָּבִים זֶה עִם זֶה. זֶה נוֹטֵל שֶׁלּוֹ וְשֶׁל חֲבֵרוֹ, וְזֶה נוֹטֵל שֶׁלּוֹ וְשֶׁל חֲבֵרוֹ, וּמְשֻׁלָּבִים זֶה בָּזֶה.</p>\n<p>כָּתוּב, בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי עַל מֵי מְנֻחוֹת יְנַהֲלֵנִי. נְאוֹת דֶּשֶׁא - אֵלֶּה הֵם הַמְּקוֹרוֹת הָעֶלְיוֹנִים שֶׁכָּל הַמָּזוֹן וְהַהַסְפָּקָה בָּאִים מֵהֶם. הַנָּאוֹת הַלָּלוּ נִקְרָאִים נְאוֹת יַעֲקֹב, נְאוֹת דֶּשֶׁא, מִשּׁוּם שֶׁיֵּשׁ נָאוֹת בַּחוּץ שֶׁנִּקְרָאִים נְאוֹת מִדְבָּר, וְעַל זֶה בִּנְאוֹת דֶּשֶׁא. וְאִם תֹּאמַר, הֲרֵי כָּתוּב תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא, שֶׁהֲרֵי הוּא לְמַטָּה? אֶלָּא דֶּשֶׁא מֵאוֹתָן נָאוֹת בָּא, שֶׁנּוֹלָד וְצוֹמֵחַ מֵהֶם, וְעַל זֶה בִּנְאוֹת דֶּשֶׁא יַרְבִּיצֵנִי.</p>\n<p>עֵל מֵי מְנֻחוֹת יְנַהֲלֵנִי - אֵלּוּ הַמַּיִם שֶׁל מְנוּחָה, שֶׁשּׁוֹפְעִים מֵאוֹתוֹ מָקוֹם שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, וְאוֹתָם הַמַּיִם נִקְרָאִים מֵי מְנֻחוֹת. נַפְשִׁי יְשׁוֹבֵב - זוֹהִי נֶפֶשׁ דָּוִד, וְלֹא רָצָה דָוִד לְתַקֵּן אֶלָּא אֶת אוֹתָהּ הַדַּרְגָּה שֶׁלּוֹ כָּרָאוּי. בְּמֵי הַמְּנוּחוֹת הַלָּלוּ עֲתִידִים הַצַּדִּיקִים לָנוּחַ לָעוֹלָם הַבָּא, שֶׁכָּתוּב (ישעיה נח) וְנָחֲךְ ה' תָּמִיד וְגוֹ'.</p>"],[9522011776,"<p>וְעָשִׂיתָ קַרְסֵי נְחֹשֶׁת חֲמִשִּׁים וְגוֹ'. רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד. כְּשֶׁיָּרַד הַלַּיְלָה, נִכְנְסוּ לְתוֹךְ גַּן שֶׁעַל יָם טְבֶרְיָה, וּבֵין כָּךְ רָאוּ שְׁנֵי כּוֹכָבִים שֶׁנּוֹסְעִים, זֶה מִכָּאן וְזֶה מִכָּאן, וְנִפְגְּשׁוּ זֶה בָּזֶה וְהִסְתַּתְּרוּ.</p>\n<p>אָמַר רַבִּי אַבָּא, כַּמָּה גְדוֹלִים מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּשָּׁמַיִם מִלְמַעְלָה וּבָאָרֶץ מִלְּמַטָּה. מִי יָכוֹל לָדַעַת בִּשְׁנֵי הַכּוֹכָבִים הַלָּלוּ שֶׁיָּצְאוּ אֶחָד מִכָּאן וְאֶחָד מִכָּאן, וְנִפְגְּשׁוּ זֶה בָּזֶה וְהִסְתַּתְּרוּ. אָמַר לוֹ רַבִּי אֶלְעָזָר, וְכִי לֹא רָאִינוּ אוֹתָם?! הֲרֵי הִשְׁגַּחְנוּ בָהֶם וְהִשְׁגַּחְנוּ בְכַמָּה מַעֲשִׂים אֲחֵרִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה תָמִיד.</p>\n<p>פָּתַח וְאָמַר, (תהלים קמז) גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ וְגוֹ'. גָּדוֹל וְרַב וְעֶלְיוֹן הוּא הַקָּדוֹשׁ בָּרוּךְ הוּא. וְכִי לֹא יָדַעְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא גָּדוֹל וְרַב כֹּחַ? מַהוּ שִׁבְחוֹ שֶׁל דָּוִד כָּאן?</p>\n<p>אֶלָּא בְּכָל מָקוֹם הוּא אוֹמֵר גָּדוֹל ה', וְכָאן אָמַר גָּדוֹל אֲדוֹנֵינוּ. מָה הַטַּעַם? אֶלָּא שָׁם שֶׁהוּא אוֹמֵר (שם מא) גָּדוֹל ה' וּמְהֻלָּל מְאֹד, בְּדַרְגָּה עֶלְיוֹנָה הוּא אוֹמֵר. וְכָאן שֶׁכָּתוּבּ גָּדוֹל אֲדוֹנֵינוּ, בְּדַרְגָּה תַחְתּוֹנָה הוּא אוֹמֵר, שֶׁהוּא אֲדוֹן כָּל הָאָרֶץ. מַה כָּתוּב לְמַעְלָה מִפָּסוּק זֶה? מוֹנֶה מִסְפָּר לַכּוֹכָבִים לְכֻלָּם שֵׁמוֹת יִקְרָא. אִם כָּל בְּנֵי הָעוֹלָם מִיּוֹם שֶׁנִּבְרָא אָדָם, יִתְכַּנְּסוּ לִמְנוֹת אֶת הַכּוֹכָבִים, לֹא יוּכְלוּ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית טו) וּסְפֹר הַכּוֹכָבִים אִם תּוּכַל לִסְפֹּר אוֹתָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַה כָּתוּב בּוֹ? מוֹנֶה מִסְפָּר לַכּוֹכָבִים לְכֻלָּם שֵׁמוֹת יִקְרָא. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ וְגוֹ'. כְּמוֹ שֶׁאֵין מִסְפָּר לְכוֹכְבֵי הַשָּׁמַיִם פְּרָט אֵלָיו, אַף כָּךְ הוּא כָּתוּב בּוֹ, וְלִתְבוּנָתוֹ אֵין מִסְפָּר.</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם וְגוֹ'. אֶת כָּל הַחֲיָלוֹת וְהַמַּחֲנוֹת וְהַכּוֹכָבִים הוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֵׁם כָּל אֶחָד וְאֶחָד, וְלֹא גָרַע אֲפִלּוּ אֶחָד. בְּכָל הַכּוֹכָבִים וְהַמַּזָּלוֹת שֶׁל כָּל הָרְקִיעִים נִתְמַנּוּ שָׂרִים וּפְקִידִים לְשַׁמֵּשׁ אֶת הָעוֹלָם כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְאֵין לְךְ עֵשֶׂב קָטָן בְּכָל הָעוֹלָם שֶׁלֹּא שׁוֹלֵט עָלָיו מַזָּל וְכוֹכָב בָּרָקִיעַ, וְעַל אוֹתוֹ כּוֹכָב מְמֻנֶּה אֶחָד שֶׁמְּשַׁמֵּשׁ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>כָּל הַכּוֹכָבִים שֶׁבָּרְקִיעִים, כֻּלָּם מְשַׁמְּשִׁים עַל הָעוֹלָם הַזֶּה, וְכֻלָּם מֻפְקָדִים לְשַׁמֵּשׁ כָּל דָּבָר וְדָבָר לְאוֹתָם שֶׁבָּעוֹלָם הַזֶּה, וְלֹא צוֹמְחִים וְלֹא מְגַדְּלִים עֲשָׂבִים וְאִילָנוֹת וּדְשָׁאִים וְעִשְׂבֵי הַשָּׂדֶה, רַק לְמַרְאֵה הַכּוֹכָבִים שֶׁעוֹמְדִים עֲלֵיהֶם וְנִרְאִים עֲלֵיהֶם פָּנִים בְּפָנִים, כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁרָאוּי לוֹ.</p>\n<p>רֹב הַמַּחֲנוֹת שֶׁל הַכּוֹכָבִים וְהַמַּזָּלוֹת, כֻּלָּם יוֹצְאִים בְּרֵאשִׁית הַלַּיְלָה עַד שָׁלֹשׁ שָׁעוֹת חָסֵר רֶבַע. מִשָּׁם וָהָלְאָה לֹא יוֹצְאִים, רַק מְעַטִּים. וְכָל אוֹתָם הַכּוֹכָבִים לֹא מְשַׁמְּשִׁים לְבַטָּלָה וְלֹא נִרְאִים לְבַטָּלָה. וְיֵשׁ כּוֹכָבִים שֶׁמְּשַׁמְּשִׁים כָּל לַיְלָה כְּדֵי לְהַצְמִיחַ וּלְגַדֵּל אֶת כָּל אוֹתָם דְּבָרִים שֶׁהִצְטַוּוּ עֲלֵיהֶם. וְיֵשׁ כּוֹכָבִים שֶׁמְּשַׁמְּשִׁים עַד חֲצוֹת הַלַּיְלָה, וְצוֹמְחִים וּמְגַדְּלִים מֵרֵאשִׁית הַלַּיְלָה עַד אוֹתָהּ שָׁעָה כָּל אוֹתָם דְּבָרִים שֶׁהֻפְקְדוּ עֲלֵיהֶם. וְיֵשׁ כּוֹכָבִים שֶׁמְּשַׁמְּשִׁים מְעַט מֵהַלַּיְלָה, שֶׁכֵּיוָן שֶׁנִּרְאֶה עִם אוֹתוֹ הָעֵשֶׂב אוֹ אוֹתוֹ הַדֶּשֶׁא, מִיָּד הִשְׁלִים שִׁמּוּשׁוֹ, וְלֹא צָרִיךְ יוֹתֵר בְּאוֹתוֹ לַיְלָה, וַהֲרֵי הֵם אֵינָם עוֹמְדִים לְבַטָּלָה. כֵּיוָן שֶׁהִשְׁלִימוּ אֶת שִׁמּוּשָׁם, אֵינָם נִרְאִים יוֹתֵר בָּעוֹלָם הַזֶּה, וְנִכְנָסִים לִמְקוֹמָם.</p>\n<p>בְּסֵפֶר הַחָכְמָה הָעֶלְיוֹנָה שֶׁל בְּנֵי קֶדֶם אוֹמְרִים עַל כָּל אוֹתָם כּוֹכְבֵי הַשַּׁרְבִיט, שֶׁמְּשַׁלְּחִים שַׁרְבִיט בָּרָקִיעַ, אוֹמְרִים שֶׁהָעֲשָׂבִים הֵם בָּאָרֶץ מֵאוֹתָם שֶׁנִּקְרָאִים סַמֵּי הַחַיִּים, וְאַבְנֵי יְקָר יֵשׁ בָּאָרֶץ, וְזָהָב שָׁחוּט שֶׁל הַמִּגְדָּל בְּתוֹךְ הָרִים רָמִים בִּמְעַט הַמַּיִם שֶׁמְּכַסִּים עֲלֵיהֶם, וְלֹא מְכַסֶּה, אֶלָּא שֶׁשּׁוֹפֵעַ עָלָיו, וְשׁוֹלְטִים עַל כָּל אֵלֶּה אוֹתָם כּוֹכְבֵי הַשַּׁרְבִיט וּמְגַדְּלִים הַלָּלוּ בִּשְׁבִילָם.</p>\n<p>וְכָל תִּקּוּנָם וּגְדֻלָּתָם אֵינוֹ אֶלָּא בְּמַרְאֶה וְנֹגַהּ שֶׁל אוֹתוֹ שַׁרְבִיט שֶׁשּׁוֹלֵחַ אוֹתוֹ הַכּוֹכָב לְתוֹךְ הָרָקִיעַ, וְאָז מִתְתַּקְּנִים וּמִתְגַּדְּלִים כָּל אוֹתָם דְּבָרִים.</p>\n<p>מַחֲלוֹת יֵשׁ בִּבְנֵי אָדָם כְּמוֹ יְרֻקִּים וְחוֹלֵי רוּחַ, שֶׁהָרְפוּאָה שֶׁלָּהֶם לֹא תְלוּיָה כִּי אִם בְּמַרְאֶה אֶחָד שֶׁל בַּרְזֶל קַלִּיל הַנּוֹצֵץ לָעֵינַיִם, וְיֵשׁ לוֹ לְבַעַל הַחֹלִי לְהִסְתַּכֵּל בּוֹ. וְלֹא (שוכך) שַׁיָּךְ (נרפא) בָּזֶה, עַד שֶׁעוֹבֵר אוֹתוֹ מַרְאֶה לְצַד זֶה וּלְצַד זֶה כְּמוֹ הַשַּׁרְבִיט שֶׁיּוֹשִׁיט הִתְנוֹצְצוּת שֶׁל בָּרָק לְפָנָיו. וּבְאוֹתָהּ הוֹשָׁטָה שֶׁל בָּרָק שֶׁנּוֹצֵץ לָעֵינַיִם, בָּאָה לוֹ הָרְפוּאָה. אַף כָּךְ כָּל אוֹתָם שֶׁשּׁוֹלְטִים עֲלֵיהֶם אוֹתָם כּוֹכָבִים, אֵין לָהֶם תִּקּוּן וּגְדֻלָּה בְּמַה שֶּׁנִּרְאֶה, פְּרָט לְאוֹתָהּ הִתְפַּשְּׁטוּת הַשַּׁרְבִיט, וּבָזֶה מִתְתַּקְּנִים בַּמַּרְאֶה, בַּגָּוֶן, בַּכֹּחַ, כְּמוֹ שֶׁנִּרְאֶה.</p>\n<p>וְיָפֶה הוּא, שֶׁהֲרֵי כְּמוֹ זֶה רָמוּז בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ בְּחָכְמַת הָאֲבָנִים הַיְקָרוֹת, שֶׁאִם חָסֵר מֵהֶם נֹגַהּ שֶׁל הִתְנוֹצְצוּת וְלַהַט הַכּוֹכָבִים הַיְדוּעִים, לֹא מְגַדְּלִים וְלֹא (מתתקנים לעולמים) מְתַקְּנִים אוֹתָם לְעוֹלָמִים, וְהַכֹּל תִּקֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא לְתִקּוּן הָעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) לְהָאִיר עַל הָאָרֶץ, בְּכָל מַה שֶּׁצָּרִיךְ בָּעוֹלָם הַזֶּה לְתַקֵּן אוֹתוֹ.</p>\n<p>כָּתוּב וְעָשִׂיתָ קַרְסֵי נְחֹשֶׁת חֲמִשִּׁים, וְכָתוּב וְעָשִׂיתָ חֲמִשִּׁים קַרְסֵי זָהָב, וְשָׁנִינוּ, מִי שֶׁלֹּא רָאָה אוֹתָם הַקְּרָסִים בַּמִּשְׁכָּן, לֹא רָאָה אוֹר שֶׁל כּוֹכָבִים בָּרָקִיעַ, מִשּׁוּם שֶׁבְּאוֹתוֹ מַרְאֶה וּבְאוֹתוֹ גָוֶן דּוֹמִים לְכָל מִי שֶׁמִּסְתַּכֵּל בָּהֶם.</p>\n<p>יִשִׁ כּוֹכָבִים בָּרָקִיעַ, שֶׁאֵלֶּה יוֹצְאִים מֵאוֹתוֹ הָרָקִיעַ שֶׁכָּל הַכּוֹכָבִים הֲדוּקִים שָׁם. בְּאוֹתוֹ הָרָקִיעַ יֵשׁ מֵאָה חַלּוֹנוֹת שְׁקוּפִים, מֵהֶם לְצַד מִזְרָח, וּמֵהֶם לְצַד דָּרוֹם, וּבְכָל חַלּוֹן וְחַלּוֹן יֵשׁ כּוֹכָב אֶחָד.</p>\n<p>וּכְשֶׁהַשֶּׁמֶשׁ הוֹלֶכֶת בְּאוֹתָם חַלּוֹנוֹת וְשִׁקּוּעִים שֶׁבָּרָקִיעַ, הוּא נוֹצֵץ בְּהִתְנוֹצְצוּת, וְהַכּוֹכָבִים הַלָּלוּ יוֹצְאִים לְהִתְנוֹצֵץ מֵאוֹתָהּ הִתְנוֹצְצוּת שֶׁל הַשֶּׁמֶשׁ וְנִצְבָּעִים, מֵהֶם אֲדֻמִּים כְּגוֹן הַנְּחֹשֶׁת, מֵהֶם יְרֻקִּים כְּגוֹן הַזָּהָב, וְלָכֵן אֵלֶּה אֲדֻמִּים וְאֵלֶּה יְרֻקִּים. חֲמִשִּׁים הֵם בְּאוֹתָם חֲמִשִּׁים חַלּוֹנוֹת, (וחמשים הם באותם החלונות) הָאֲחֵרִים. שֶׁל צַד מִזְרָח הֵם יְרֻקִּים, שֶׁל צַד דָּרוֹם הֵם אֲדֻמִּים, בָּהֶם אָחוּז סִיּוּם הַמִּשְׁכָּן.</p>\n<p>בְּכָל אוֹתָם הַכּוֹכָבִים שֶׁיּוֹצְאִים מֵאוֹתוֹ רָקִיעַ מִתְעָרְבִים אוֹתָם כּוֹכָבִים בַּלַּיְלָה, וְנוֹצְצִים וְלוֹהֲטִים וְשׁוֹלְטִים בָּעוֹלָם הַזֶּה, מֵהֶם עַל נְחֹשֶׁת, מֵהֶם עַל זָהָב יְרַקְרַק, וּמִתְתַּקְּנִים וּגְדֵלִים עַל הַכֹּחַ שֶׁלָּהֶם.</p>\n<p>אֵלֶּה הַכּוֹכָבִים שׁוֹלְטִים בְּכ\"ה וַחֲצִי הַנְּקֻדּוֹת שֶׁל הַלַּיְלָה, שֶׁהֵם רְגָעִים שֶׁל שָׁעָה, וְהֵם שֶׁמְּגַדְּלִים נְחֹשֶׁת, שֶׁהֵם אֲדֻמִּים וְלוֹהֲטִים וְנוֹצְצִים. וּכְשֶׁמּוֹשִׁיטִים שָׁלֹשׁ פְּעָמִים הִתְנוֹצְצוּת לְצַד הַמִּזְרָח, אוֹ חָמֵשׁ אוֹ שֶׁבַע, מַלְכֵי הָעַמִּים יָבֹאוּ עַל אוֹתוֹ צַד, וְכָל הָעֹשֶׁר וְהַזָּהָב יִסְתַּלֵּק מֵאוֹתוֹ מָקוֹם. וְאִם הִתְנוֹצְצוּת אַחַת, שְׁתַּיִם, אַרְבַּע, שֵׁשׁ, זוֹ אַחַר זוֹ, אֵימָה וָפַחַד יִפֹּל וְיִשְׁרֶה עַל אוֹתוֹ הַצַּד. מַכָּה הַהִתְנוֹצְצוּת וְשׁוֹכֶכֶת, מַכָּה הַהִתְנוֹצְצוּת וְשׁוֹכֶכֶת - יִתְעוֹרְרוּ קְרָבוֹת וְלֹא יֵעָשׂוּ (בעולם באותו צד), שֶׁהֲרֵי בְּאוֹתוֹ זְמַן הִתְעוֹרְרוּת לְמַעְלָה הִיא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָם הַמְמֻנִּים שֶׁל הָעוֹלָם שֶׁשּׁוֹלְטִים עַל שְׁאָר הָעַמִּים, וְכֵן כְּמוֹ זֶה בְּצַד אַחֵר.</p>\n<p>פָּתַח וְאָמַר, (דניאל ב) יְהִי שֵׁם הָאֱלוֹהַּ מְבֹרָךְ מִן הָעוֹלָם וְעַד הָעוֹלָם, שֶׁהַחָכְמָה וְהַגְּבוּרָה שֶׁלּוֹ הִיא. וְהוּא מְשַׁנֶּה עִדָּנִים וּזְמַנִּים. וְהַכֹּל הוּא בִּרְשׁוּתוֹ, וְהוֹצִיא אֶת עַמּוֹ הַקָּדוֹשׁ מֵהַכֹּחַ וְהָרְשׁוּת שֶׁל כּוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁהֵם אֱלִילִים אֲחֵרִים, וְלֹא בְאֵלֶּה חֶלְקוֹ שֶׁל יַעֲקֹב, כִּי אִם בְּיוֹצֵר הַכֹּל הוּא.</p>\n<p>רָקִיעַ יֵשׁ לְמַעְלָה עַל כָּל הָרְקִיעִים הַלָּלוּ, וְהוּא טָמִיר וְגָנוּז, וְחוֹתַם טַבַּעַת הַמִּשְׁכָּן שׁוֹלֵט עַל הָרָקִיעַ הַזֶּה, וְהָרָקִיעַ הַזֶּה נִקְרָא הַחֶדֶר שֶׁל הַמִּשְׁכָּן, וּבָרָקִיעַ הַזֶּה כָּל אוֹתָם חַלּוֹנוֹת מִצַּד זֶה וּמִצַּד זֶה, וְאוֹחֵז אֶת כָּל אוֹתָם הַסִּדּוּרִים שֶׁל הַמִּשְׁכָּן. שִׁשָּׁה חַלּוֹנוֹת הֵם גְּדוֹלִים מִכֻּלָּם, וְאֶחָד נִסְתָּר שֶׁשּׁוֹלֵט עֲלֵיהֶם.</p>\n<p>חַלּוֹן אֶחָד נִקְרָא חַלּוֹן הַזֹּהַר, וּבוֹ יוֹצֵא כּוֹכָב אֶחָד שֶׁנִּקְרָא לַחֲכָמִים יָ\"ד, וְזֶהוּ הִתּוּךְ שֶׁמְּהַתֵּךְ לְמַטָּה בַּשִּׁלְטוֹן שֶׁל יְהוּדָה. לֹא שֶׁאֵין לוֹ חֵלֶק בּוֹ, שֶׁהֲרֵי אֵין לְשִׁבְטֵי יִשְׂרָאֵל חֵלֶק וְנַחֲלָה בָּהֶם, אֶלָּא שֶׁשֵּׁבֶט יְהוּדָה שׁוֹלֵט עַל זֶה, וְאֵינוֹ עָלָיו.</p>\n<p>וּכְשֶׁהֵסִיטוּ בְּנֵי יְהוּדָה אֶת דַּרְכָּם מֵאַחֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הָלְכוּ לָדַעַת אַחַר הַחַלּוֹן הַזֶּה וְהַכּוֹכָב הַזֶּה, וְאָמְרוּ (שהרי ידע) שֶׁזּוֹ הַיָּד הַמְנַצַּחַת אֶת שְׁאָר הָעַמִּים, שֶׁכָּתוּב בּוֹ (בראשית מט) יָדְךְ בְּעֹרֶף אֹיְבֶיךְ, וְהָלְכוּ אַחֲרָיו וְעוֹשִׂים לוֹ שִׁמּוּשׁ וּפֻלְחָן, וְעַל זֶה כָּתוּב, (מלכים א יד) וַיַּעַשׂ יְהוּדָה הָרַע בְּעֵינֵי ה'.</p>\n<p>כְּשֶׁהַכּוֹכָב הַזֶּה יוֹצֵא, פּוֹשֵׁט יָד אַחַת בְּחָמֵשׁ אֶצְבָּעוֹת, מֵאִיר וְנוֹצֵץ בְּאוֹתוֹ חַלּוֹן. בַּעֲלֵי הַקְּסָמִים וְהַכְּשָׁפִים פּוֹחֲדִים מֵהַמָּקוֹם הַזֶּה, מִשּׁוּם שֶׁבְּשָׁעָה שֶׁזֶּה שׁוֹלֵט, כָּל הַקְּסָמִים וְהַכְּשָׁפִים מִתְבַּלְבְּלִים וְלֹא מַצְלִיחִים בִּידֵיהֶם.</p>\n<p>וְאִם תֹּאמַר, הוֹאִיל וְהָרָקִיעַ הַזֶּה טָמִיר, וְאֵיךְ יוֹדְעִים אוֹתוֹ? אֶלָּא סִימָן חִיצוֹן יֵשׁ לָהֶם, וְיוֹדְעִים שֶׁהֲרֵי שׁוֹלֵט הַכּוֹכָב הַזֶּה, וּפוֹחֲדִים תָּמִיד מִמֶּנּוּ, וְלֹא מַצְלִיחִים בִּידֵיהֶם אוֹתָם קְסָמִים וּכְשָׁפִים. וְלָכֵן יֵשׁ פְּעָמִים שֶׁמַּצְלִיחִים בּוֹ בְּנֵי אָדָם, וְיֵשׁ פְּעָמִים שֶׁלֹּא מַצְלִיחִים בּוֹ. וְלָכֵן אוֹתָם בַּעֲלֵי קְסָמִים וּכְשָׁפִים מִתְמַעֲטִים מֵהָעוֹלָם, כִּי הֵם לֹא יוֹדְעִים אֶת הָעִקָּר לָמָּה לֹא מַצְלִיחַ בִּידֵיהֶם. וְעַל זֶה אוֹתָם הָרִאשׁוֹנִים הָיוּ יוֹדְעִים וּמִסְתַּכְּלִים בַּחוּץ בְּאוֹתוֹ סִימָן שֶׁיּוֹדְעִים.</p>\n<p>חַלּוֹן שֵׁנִי נִקְרָא חַלּוֹן הַצִּפֹּרֶן, מִשּׁוּם שֶׁהוּא כְּעֵין הַצִּפֹּרֶן, וּבוֹ יוֹצֵא כּוֹכָב אֶחָד שֶׁנִּקְרָא לַחֲכָמִים צִפְעוֹן, שֶׁהֲרֵי זֶה שׁוֹלֵט בְּשִׁלְטוֹן חָזָק בְּדִין בְּרֹאשׁ וְזָנָב, יֵשׁ לוֹ כְּמוֹ צִפְעוֹן אוֹרֵב לַהֲרֹג.</p>\n<p>מֵאוֹתוֹ חַלּוֹן יוֹצְאִים שֵׁשׁ מֵאוֹת אֶלֶף רִבּוֹא שֶׁל רוּחוֹת שֶׁשּׁוֹלְטוֹת עַל אוֹתָן הַצִּפָּרְנַיִם שֶׁל בְּנֵי אָדָם כְּשֶׁהֵן נִזְרָקוֹת בְּגִלּוּי, וּבָזֶה עוֹשִׂים כְּשָׁפִים וּקְסָמִים כָּל אוֹתָם שֶׁמַּכִּירִים אוֹתָם. בְּאוֹתָהּ שָׁעָה שֶׁהַכּוֹכָב הַזֶּה שׁוֹלֵט, כָּל אוֹתָם שֶׁזּוֹרְקִים צִפָּרְנַיִם, (אם עשה) אוֹ עוֹשִׂים בָּהֶם כְּשָׁפִים, גּוֹרְמִים מָוֶת לְכָל הָעוֹלָם, וְהַכְּשָׁפִים עוֹלִים בִּידֵי אוֹתָם שֶׁעוֹשִׂים אוֹתָם.</p>\n<p>הַחַלּוֹן הַשְּׁלִישִׁי נִקְרָא חַלּוֹן הַחֹשֶׁן, וּבוֹ יוֹצֵא כּוֹכָב אֶחָד שֶׁנִּקְרָא נִגְהָ\"ה דְבוּסִי\"נָא (אור הגר). זוֹהִי הִתְנוֹצְצוּת שֶׁנּוֹצֶצֶת וְעוֹמֶדֶת עַל כָּל רוּחַ, וּמְנוּחָה וְהַצָּלָה (וטוב) בָּהּ, אֵין בָּהּ כְּלָל קִטְרוּג. כְּשֶׁהוּא שׁוֹלֵט, כָּל הַמְּנוּחָה וְכָל הָאוֹר שׁוֹלֵט בָּעוֹלָם, שַׁלְוָה וְשּבַע, וְהַכֹּל שׁוֹלֵט בָּעוֹלָם.</p>\n<p>חַלּוֹן רְבִיעִי הוּא חַלּוֹן שֶׁנִּקְרָא גָּבִיעַ, וּבוֹ יוֹצֵא כּוֹכָב אֶחָד שֶׁנִּקְרָא לַחֲכָמִים אֶשְׁכּוֹל הַכֹּפֶר, מִשּׁוּם שֶׁכָּךְ יוֹצֵא כְּמוֹ אֶשְׁכּוֹל, נוֹצֵץ נִצְנוּצִים כְּמוֹ עֲנָבִים בְּכֹפֶר, וּבָזֶה הִתְעוֹרְרוּת הָרַחֲמִים מִתְעוֹרְרִים בָּעוֹלָם, מַרְחִיק וּמְקָרֵב, תּוֹלָדוֹת רַבּוֹת מִתְרַבּוֹת בָּעוֹלָם, וּבְנֵי הָעוֹלָם לֹא מַקְפִּידִים כְּשֶׁצְּרִיכִים זֶה אֶת זֶה, שָׁלוֹם וְשִׂמְחָה מִתְעוֹרְרִים בָּעוֹלָם.</p>\n<p>חַלּוֹן חֲמִישִׁי הוּא חַלּוֹן שֶׁנִּקְרָא בְּאֵר עַל שֵׁם הַכּוֹכָב שֶׁיּוֹצֵא בּוֹ, נִכְנָס וְיוֹצֵא וְשׁוֹאֵב כַּדְּלִי, לֹא שׁוֹכֵךְ לְעוֹלָמִים. בָּזֶה חַכְמֵי הַלֵּב לֹא יְכוֹלִים לַעֲמֹד בְּדֶרֶךְ אֱמֶת, מִשּׁוּם שֶׁאֵינוֹ עוֹמֵד בְּקִיּוּם וְלֹא שׁוֹכֵךְ לְעוֹלָמִים, וְעַל כָּךְ דּוֹחֲקִים אֶת עַצְמָם לְעַיֵּן בַּמָּקוֹם הַזֶּה וְלָדוּן דִּין.</p>\n<p>חַלּוֹן שִׁשִּׁי הוּא הַחַלּוֹן שֶׁנִּקְרָא נֹגַהּ, וְיוֹצֵא בּוֹ כּוֹכָב אֶחָד שֶׁנִּקְרָא גִּזְרוֹן, מִשּׁוּם שֶׁכַּאֲשֶׁר זֶה שׁוֹלֵט, הָעוֹלָם עוֹמֵד בְּדִין בְּכַמָּה גְזֵרוֹת וּבְכַמָּה עֳנָשִׁים, וּבְכָל יוֹם וָיוֹם מִתְחַדְּשׁוֹת גְּזֵרוֹת עַל הָעוֹלָם, וְטֶרֶם שֶׁאֵלֶּה מִסְתַּיְּמוֹת, מִתְחַדְּשׁוֹת אֲחֵרוֹת, וְזֶה לֹא כָּל כָּךְ שׁוֹלֵט בָּעוֹלָם.</p>\n<p>אֲבָל סָמוּךְ לִימוֹת הַמָּשִׁיחַ יִשְׁלֹט הַחַלּוֹן הַזֶּה בַּכּוֹכָב הַזֶּה עַל הָעוֹלָם, וְעַל כֵּן יִשְׁלְטוּ חַיּוֹת רָעוֹת עַל הָעוֹלָם, וְיִתְחַדְּשׁוּ מִינִים רַבִּים זֶה אַחַר זֶה, וְיִשְׂרָאֵל יִהְיוּ בְצָרָה. וּכְשֶׁיִּדָּחֲקוּ בְּתוֹךְ חֶשְׁכַת הַגָּלוּת, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא יָאִיר לָהֶם אֶת אוֹר הַיּוֹם, וִיקַבְּלוּ הַמַּלְכוּת קְדוֹשִׁים עֶלְיוֹנִים, וְתִתְבַּטֵּל הַמַּלְכוּת מִיָּדָם שֶׁל הָעַמִּים עוֹבְדֵי כוֹכָבִים, וְיִשְׁלְטוּ עֲלֵיהֶם יִשְׂרָאֵל, וְיִתְקַיֵּם וְהָיָה אוֹר הַלְּבָנָה וְגוֹ'.</p>\n<p>וְאָז יִפָּתַח הַחַלּוֹן הַשְּׁבִיעִי בְּכָל הָעוֹלָם, וְכוֹכָבוֹ הוּא הַכּוֹכָב שֶׁל יַעֲקֹב, וְזֶהוּ שֶׁאָמַר בִּלְעָם, דָּרַךְ כּוֹכָב מִיַּעֲקֹב. וְהַכּוֹכָב הַזֶּה יָאִיר (ארבעהימיםוארבעהלילות) אַרְבָּעִים יוֹם (וארבעים לילה). וּכְשֶׁיִּתְגַּלֶּה מֶלֶךְ הַמָּשִׁיחַ וְיִתְכַּנְּסוּ לְמֶלֶךְ הַמָּשִׁיחַ כָּל הָעַמִּים שֶׁל הָעוֹלָם, אָז יִתְקַיֵּם הַפָּסוּק שֶׁכָּתוּב, (ישעיה יא) שֹׁרֶשׁ יִשַׁי אֲשֶׁר עֹמֵד לְנֵס עַמִּים אֵלָיו גּוֹיִם יִדְר!שׁוּ וְהָיְתָה מְנֻחָתוֹ כָּבוֹד.</p>"],[9522011777,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (איוב לה) וְלֹא אָמַר אַיֵּה אֱלוֹהַּ עֹשָׂי נֹתֵן זְמִרוֹת בַּלָּיְלָה. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל עֹשָׂי?! עוֹשִׂי הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה עֹשָׂי? אֶלָּא שֵׁם הָאֱלוֹהַּ הוּא שֵׁם כָּלוּל שֶׁנִּרְאֶה הוּא וּבֵית דִּינוֹ. זֶהוּ שֵׁם שָׁלֵם שֶׁכּוֹלֵל זָכָר וּנְקֵבָה: א\"ל ו\"ה, וּמִשּׁוּם כָּךְ עֹשָׂי.</p>\n<p>נֹתֵן זְמִרוֹת בַּלָּיְלָה, מִשּׁוּם שֶׁזֶּהוּ שֶׁמְּשַׁבֵּחַ תָּמִיד אֶל הַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, כְּמוֹ שֶׁהַמְּנוֹרָה לֹא שׁוֹקֵט תָּמִיד לְקַבֵּל אוֹר הַשִּׂמְחָה הָעֶלְיוֹנָה מֵרֹב הַשִּׂמְחָה שֶׁלּוֹ, וְלָכֵן נֹתֵן זְמִרוֹת בַּלָּיְלָה.</p>\n<p>כָּל אוֹתָם כּוֹכָבִים שֶׁמְּאִירִים בָּרָקִיעַ, כֻּלָּם מוֹדִים וּמְשַׁבְּחִים לַקָּדוֹשׁ- בָּרוּךְ- הוּא בְּכָל אוֹתוֹ זְמַן שֶׁנִּרְאִים בָּרָקִיעַ, מִשּׁוּם שֶׁהַמַּלְאָכִים הָעֶלְיוֹנִים כֻּלָּם מוֹדִים וּמְשַׁבְּחִים אַשְׁמוּרוֹת אַשְׁמוּרוֹת, בִּשְׁלֹשֶׁת חֶלְקֵי הַלַּיְלָה.</p>\n<p>בַּלַּיְלָה נֶחֱלָקִים כַּמָּה צְדָדִים. בְּרֵאשִׁית הַלַּיְלָה, כְּשֶׁיּוֹרֵד הַלַּיְלָה וּמַחְשִׁיךְ, כָּל אוֹתָן רוּח וֹת רָעוֹת וּמִינִים רָעִים, כֻּלָּם מִתְפַּזְּרִים וּמְשׁוֹטְטִים בְּכָל הָעוֹלָם, וְנִפְרָד הַצַּד הָאַחֵ ר, וְתוֹבְעִים דַרְכֵי בֵּית הַמֶּלֶךְ מִכָּל אוֹתָם הַצְּדָדִים הַקְּדוֹשִׁים.</p>\n<p>כֵּיוָן שֶׁמִּתְעוֹרֵר אוֹתוֹ הַצַּד הָאַחֵר, כָּל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת, (השנה) אֶחָת מִשִּׁשִּׁים בַּמָּוֶת, וְשׁוֹלֵט עֲלֵיהֶם. אָז כֵּיוָן שֶׁהַטֻּמְאָה נִפְרְדָה מִלְמַעְלָה וְשׁוֹלֶטֶת וְיוֹרֶדֶת לְמַטָּה, אָז נִפְרָדִים שְׁלֹשָׁה מַחֲנוֹת לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁלֹשָׁה צְדָדִים (משמרות) שֶׁל הַלַּיְלָה, כְּמוֹ שֶׁהֵעִירוּ בָזֶה הַחֲבֵרִים.</p>\n<p>בְּעוֹד שֶׁהֵם מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַצַּד הָאַחֵר הוֹלֵךְ וּמְשׁוֹטֵט לְמַטָּה בְּכָל צִדְדֵי הָעוֹלָם. וְעַד שֶׁהַצַּד הָאַחֵר אֵינוֹ עוֹבֵר מִשָּׁם, הֵם לֹא יְכוֹלִים לְהִתְיַחֵד עִם רִבּוֹנָם.</p>\n<p>סוֹד לַחֲכָמִים, מַלְאָכִים עֶליוֹנִים וְיִשְׂרָאֵל לְמַטָּה, כֻּלָּם דּוֹחֲקִים בְּאוֹתוֹ הַצַּד הָאַחֵר. כְּשֶׁרוֹצִים הַמַּלְאָכִים הֶעֶלְיוֹנִים לְהִתְיַחֵד עִם רִבּוֹנָם, לֹא יְכוֹלִים, עַד שֶׁדּוֹחִים אוֹתוֹ הַחוּצָה. מָה עוֹשִׂים? יוֹרְדִים שִׁשִּׁים רִבּוֹא שֶׁל מַלְאָכִים קְדוֹשִׁים וּמַפִּילִים שֵׁנָה עַל כָּל בְּנֵי הָעוֹלָם. כֵּיוָן שֶׁהִיא יוֹרֶדֶת, שֶׁדּוֹחִים אוֹתָהּ הַחוּצָה, וְנוֹתְנִים לָהּ כָּל הָעוֹלָם הַזֶּה בְּאוֹתָהּ שֵׁנָה, אָז הִיא שׁוֹלֶטֶת עֲלֵיהֶם וּמְקַבְּלִים מִמֶּנּוּ טֻמְאָה, פְּרָט לְאֶרֶץ יִשְׂרָאֵל לְבַדָּהּ שֶׁשָּׁם אֵינָהּ שׁוֹלֶטֶת. כֵּיוָן שֶׁנִּפְרְדָה מֵהֶם, הֵם נִכְנָסִים לְרִבּוֹנָם, וּמְשַׁבְּחִים וּמוֹדִים לְפָנָיו.</p>\n<p>כְּמוֹ זֶה יִשְׂרָאֵל לְמַטָּה לֹא יְכוֹלִים לְהִתְיַחֵד עִם רִבּוֹנָם עַד שֶׁדּוֹחִים אוֹתוֹ הַצַּד הָאַחֵר מֵהֶם, וְנוֹתְנִים לוֹ חֵלֶק בְּמַה שֶּׁיִּתְעַסֵּק, וְאַחַר כָּךְ הֵם מִתְקָרְבִים לְרִבּוֹנָם, וְלֹא נִמְצָא מְקַטְרֵג לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְאִם תֹּאמַר, מֵילָא לְמַטָּה, אֲבָל לְמַעְלָה מָה הַקִּטְרוּג שָׁם? אֶלָּא לְמַעְלָה, מִשּׁוּם שֶׁהִיא רוּחַ טֻמְאָה וְהֵם רוּחוֹת קְדוֹשׁוֹת, עַד שֶׁמְּשַׁלְּחִים רוּחַ טֻמְאָה מִבֵּינֵיהֶם לֹא יְכוֹלִים לִקְרַב אֶל רִבּוֹנָם, שֶׁהֲרֵי קְדֻשָּׁה בְּתוֹךְ טֻמְאָה לֹא מִתְעָרְבוֹת לְעוֹלָמִים. וְכֵן כְּמוֹ זֶה יִשְׂרָאֵל לְמַטָּה לֹא מִתְעָרְבִים בְּאֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם. וּשְׁנֵי צְדָדִים, עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּשֶׁרוֹצִים לִקְרַב לַמֶּלֶךְ הַקָּדוֹשׁ, דּוֹחִים אוֹתָהּ הַחוּצָה.</p>\n<p>וְלָכֵן כְּשֶׁנִּכְנָס הַלַּיְלָה, וּמַלְאָכִים קְדוֹשִׁים עֶלְיוֹנִים כְּשֶׁמִּסְתַּדְּרִים שׁוּרוֹת שׁוּרוֹת לִקְרַב (לשבח) לְרִבּוֹנָם, דּוֹחִים אֶת אוֹתוֹ צַד הַחוּצָה בָּרִאשׁוֹנָה, וְאַחַר כָּךְ נִכְנָסִים לַקֹּדֶשׁ. (ועל זה, כשגכנס הלילה, כל רוחות רעות ומינים רעים ורוחות טמאה נדחות לחוץ, ושמשי המלך נכנסים לתוך הקדשה).</p>\n<p>לְמֶלֶךָ שֶׁהָיוּ לוֹ אֲבָנִים יְקָרוֹת בְּתֵבָה אַחַת חֲקוּקָה בְּהֵיכָלוֹ, וְאוֹתוֹ מֶלֶךְ הָיָה חָכָם, וּכְדֵי שֶׁלֹּא יִתְקָרֵב כָּל מִי שֶׁרוֹצֶה לְאוֹתָהּ תֵּבָה שֶׁל אֲבָנִים יְקָרוֹת וּמַרְגָּלִיּוֹת שֶׁל שָׁם, נָטַל בְּחָכְמָתוֹ נָחָשׁ חָזָק אֶחָד וְכָרַךְ אוֹתוֹ סְבִיב אוֹתָהּ תֵּבָה. כָּל מִי שֶׁרוֹצֶה לְהוֹשִׁיט יָדוֹ לַתֵּבָה, הֲרֵי הַנָּחָשׁ קוֹפֵץ עָלָיו וְהוֹרְגוֹ.</p>\n<p>אָהוּב אֶחָד הָיָה לַמֶּלֶךְ. אָמַר לוֹ הַמֶּלֶךְ, כָּל פַּעַם שֶׁאַתָּה רוֹצֶה לְהִכָּנֵס וּלְהִשְׁתַּמֵּשׁ בַּתֵּבָה, תַּעֲשֶׂה כָּךְ וְכָךְ לְאוֹתוֹ נָחָשׁ, וְתִפְתַּח אֶת הַתֵּבָה וְתִשְׁתַּמֵּשׁ בַּגְּנָזִים שֶׁלִּי. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא כָּרַךְ נָחָשׁ סְבִיב הַקְּדֻשָּׁה, בָּאִים מַלְאָכִים עֶלְיוֹנִים לְתוֹךְ הַקְּדֻשָּׁה - הֲרֵי הַנָּחָשׁ שָׁם, וּפוֹחֲדִים לְהִטָּמֵא בּוֹ. (ואם תאמר, זה כלם אש, ואש לא מקבלת טמאה)</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לֹהֵט. עֹשֶׂה מַלְאָכָיו רוּחוֹת - אֵלּוּ הַמַּלְאָכִים שֶׁעוֹמְדִים בַּחוּץ. מְשָׁרְתָיו אֵשׁ לֹהֵט - אֵלּוּ מַלְאָכִים שֶׁעוֹמְדִים בִּפְנִים. הוּא רוּחַ טֻמְאָה, וְהֵם רוּחַ. רוּחַ עִם רוּחַ לֹא נִכְנָסוֹת זוֹ בָּזוֹ. רוּחַ טֻמְאָה בְּרוּחַ קְדֻשָּׁה לֹא מִתְעָרְבוֹת זוֹ בָּזוֹ. וּמִשּׁוּם כָּךְ אוֹתָם שֶׁנִּקְרְאוּ רוּחַ לֹא יְכוֹלִים לְהִכָּנֵס לִפְנִים מִשּׁוּם אוֹתָהּ רוּחַ טֻמְאָה. אוֹתָם שֶׁבִּפְנִים הֵם אֵשׁ, וְאוֹתָהּ אֵשׁ דּוֹחָה אֶת אוֹתָהּ רוּחַ טֻמְאָה שֶׁלֹּא נִכְנֶסֶת לִפְנִים. וּמִשּׁוּם כָּךְ הַכֹּל דּוֹחִים אֶת הַטֻּמְאָה הַחוּצָה שֶׁלֹּא תִתְעָרֵב עִמָּם, וְלָכֵן הַמַּלְאָכִים הָעֶלְיוֹנִים מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַחַר שֶׁדּוֹחִים אֶת הַטֻּמְאָה הַחוּצָה.</p>\n<p>שָׁלש אַשְׁמוּרוֹת הֵן בַּלַּיְלָה כְּנֶגֶד שָׁלֹשׁ מַחֲנוֹת שֶׁנֶּחֱלָקִים לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנִּתְבָּאֵר. וְעַל זֶה זֶה הָרִבּוֹן שֶׁל כֻּלָּם, הוּא נֵר (כגור) דָּוִד שֶׁלֹּא שׁוֹכֵךְ לְעוֹלָמִים, אֶלָּא תָּמִיד מוֹדֶה וּמְשַׁבֵּחַ אֶת הַמֶּלֶךְ הָעֶלְיוֹן, וְעַל זֶה (איוב לה) נֹתֵן זְמִרוֹת בַּלָּיְלָה.</p>\n<p>דָּבָר אַחֵר וְלֹא אָמַר אַיֵּה אֱלוֹהַּ עֹשָׂי - כְּמוֹ שֶׁנֶּאֱמַר, מִשּׁוּם שֶׁהֲרֵי הָאָדָם נִכְלָל מִמַּעְלָה וּמִמַּטָּה, וְנַעֲשָׂה כְּמוֹ שֶׁהוּא גּוּף מִשְּׁנֵי צְדָדִים, מִתּוֹךְ זָכָר וּנְקֵבָה. אַף כָּךְ הָרוּחַ, הָרוּחַ כְּלוּלָה מִתּוֹךְ זָכָר וּנְקֵבָה, וְעַל הַסּוֹד הַזֶּה מִתְתַּקֵּן אָדָם בַּחֲקִיקוֹתָיו בְּגוּף וּבְרוּחַ, וּמִשּׁוּם שֶׁהוּא כָּלוּל בְּסוֹד זֶה וּבְמַעֲשֶׂה זֶה כְּמוֹ שֶׁנִּתְבָּאֵר, לָכֵן (ודאי) כָּתוּב (בראשית א) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בַּלַּיְלָה הֲרֵי אָמַרְתָּ, שֶׁהֲרֵי בְּרֵאשִׁית הַלַּיְלָה כָּל אוֹתָם מִינִים וְרוּחוֹת רָעוֹת מִתְעוֹרְרִים בָּעוֹלָם, אֵיךְ הוּא יָכוֹל לִהְיוֹת? שֶׁאִם כָּךְ, הֲרֵי שָׁנִינוּ שֶׁמִּצַּד הַצָּפוֹן יוֹצְאִים כָּל אוֹתָם מִינִים רָעִים, וְאַתָּה אָמַרְתָּ (ונתבאר) שֶׁכַּאֲשֶׁר מִתְעוֹרֶרֶת רוּחַ צָפוֹן בַּחֲצוֹת הַלַּיְלָה, שֶׁהֲרֵי אָז כָּל אוֹתָן רוּחוֹת רָעוֹת וּצְדָדִים רָעִים מִתְכַּנְּסִים מֵהָעוֹלָם וְנִכְנָסִים לְתוֹךְ נֶקֶב תְּהוֹם רַבָּה, אִם כָּךְ, הֲרֵי בְּצַד הַדָּרוֹם, שֶׁהִיא יָמִין, לָמָּה הֵם מְשׁוֹטְטִים אוֹתָם הַמִּינִים הָרָעִים בְּרֵאשִׁית הַלַּיְלָה, שֶׁהֲרֵי שׁוֹלֶטֶת רוּחַ דָּרוֹם?</p>\n<p>אֶלָּא וַדַּאי, אִלְמָלֵא אוֹתוֹ צַד הַדָּרוֹם שֶׁמְּעַכֵּב וְדוֹחֶה צַד הָרָע, הָיָה מְטַשְׁטֵשׁ אֶת כָּל הָעוֹלָם, וְלֹא יָכוֹל הָעוֹלָם לִסְבֹּל. אֲבָל כְּשֶׁמִּתְעוֹרֵר אוֹתוֹ הַצַּד הָאַחֵר, לֹא מִתְעוֹרֵר אֶלָּא בְּצַד רוּחַ מַעֲרָב שֶׁשּׁוֹלֵט בְּרֵאשִׁית הַלַּיְלָה, וְהָעוֹלָם כּוֹנֵס אֶת הַכֹּל. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְדִּים רְפוּאָה לָעוֹלָם בְּגָוֶן זֶה, כְּמוֹ שֶׁנִּתְבָּאֵר. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה בָהֶם מִכָּל שְׁאָר עַמֵּי הָעוֹלָם.</p>\n<p>נִכְנְסוּ לַבַּיִת רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא. כְּשֶׁנֶּחֱלַק הַלַּיְלָה בַּחֲצוֹת, קָמוּ לַעֲסֹק בַּתּוֹרָה. אָמַר רַבִּי אַבָּא, עַכְשָׁו וַדַּאי הִיא עֵת רָצוֹן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וַהֲרֵי פְּעָמִים רַבּוֹת הֵעַרְנוּ אֶת זֶה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּשָׁעָה שֶׁנֶּחֱלָק הַלַּיְלָה, נִכְנָס לְתוֹךְ אוֹתָם הַצַּדִּיקִים בְּגַן עֵדֶן וּמִשְׁתַּעֲשֵׁעַ בָּהֶם. אַשְׁרֵי מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בְּאוֹתוֹ זְמַן.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, זֶה שֶׁמִּשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּתוֹךְ הַצַּדִּיקִים בְּגַן עֵדֶן, אֵיךְ מִשְׁתַּעֲשֵׁעַ? אֶלָּא בְּאוֹתוֹ זְמַן שֶׁנֶּחֱלָק הַלַּיְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר בָּאַהֲבָה שֶׁל הַשְּׂמֹאל אֶל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֲרֵי אֵין אַהֲבָה אֶלָּא מִצַּד הַשְּׂמֹאל. וְלִכְנֶסֶת יִשְׂרָאֵל אֵין דּוֹרוֹן לִקְרַב אֶל הַמֶּלֶךְ אוֹ חֲשִׁיבוּת מְעֻלָּה אֶלָּא בְּאוֹתָן רוּחוֹת הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אוֹתָן מְעֻטָּרוֹת בְּכַמָּה מַעֲשִׂים טוֹבִים וּבְכַמָּה זְכֻיּוֹת שֶׁעָשׂוּ בְּאוֹתוֹ יוֹם, וְלַקָּדוֹשׁ- בָּרוּךְ-הוּא נוֹחַ מִכָּל הַקָּרְבָּנוֹת וְהָעוֹלוֹת, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵרִיחַ בָּהֶם רֵיחַ נִיחֹחַ שֶׁעוֹשִׂים יִשְׂרָאֵל.</p>\n<p>אָז מֵאִיר אוֹר, וְכָל עֲצֵי הַגַּן עֵדֶן אוֹמְרִים שִׁירָה, וְהַצַּדִּיקִים מִתְעַדְּנִים שָׁם בְּאוֹתָם עִדּוּנִים שֶׁל הָעוֹלָם הַבָּא. כְּשֶׁמִּתְעוֹרֵר אָדָם בְּאוֹתָהּ שָׁעָה לַעֲסֹק בַּתּוֹרָה, נוֹטֵל חֶלְקוֹ עִם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן. שֵׁם אֶחָד שֶׁל שְׁלֹשִׁים וּשְׁתַּיִם אוֹתִיּוֹת חָקוּק (מתעורר) מִתְעַטֵּר בָּהֶם שָׁם, וְהוּא בְּתוֹךְ סוֹדוֹת הַצַּדִּיקִים.</p>"],[9522011778,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים קיא) הַלְלוּיָהּ אוֹדֶה ה' בְּכָל לֵבָב וְגוֹ'. הַלְלוּיָהּ, הֲרֵי נִתְבָּאֵר וְהִתְעוֹרְרוּ בוֹ הַחֲבֵרִים, וְכָךְ הוּא, שֶׁזֶּהוּ שֶׁבַח שֶׁעוֹלֶה עַל כָּל אוֹתָן הַשִּׁירוֹת וְהַתִּשְׁבָּחוֹת שֶׁאָמַר דָּוִד בַּעֲשָׂרָה מִינֵי תִשְׁבָּחוֹת שֶׁאָמַר, מִשּׁוּם שֶׁהוּא כּוֹלֵל שֶׁבַח וְשֵׁם בְּאֶחָד, וְהוּא כְּלָל שֶׁל הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן.</p>\n<p>אוֹדֶה ה' בְּכָל לֵבָב. בְּכָל מָקוֹם שֶׁאָמַר דָּוִד הַמֶּלֶךְ סוֹד שֶׁל אַלְפָא בֵּיתָא, הוּא סוֹד הָאוֹתִיּוֹת הַחֲקוּקוֹת שֶׁיּוֹצְאוֹת בַּחֲקִיקוֹת שֶׁל שְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים. וְיֵשׁ אוֹתִיּוֹת עֶלְיוֹנוֹת מִסּוֹד הָעוֹלָם הָעֶלְיוֹן, וְיֵשׁ אוֹתִיּוֹת אֲחֵרוֹת שֶׁהֵן אוֹתִיּוֹת קְטַנּוֹת. וְכָאן הוּא סוֹד שֶׁל אַלְפָא בֵּיתָא שֶׁל הָעוֹלָם (העליון נותן לעולם) הַתַּחְתּוֹן.</p>\n<p>אוֹדֶה ה' בְּכָל לֵבָב - בַּיֵּצֶר הַטּוֹב וּבַיֵּצֶר הָרָע שֶׁהוּא שׁוֹרֶה בְתוֹכוֹ. שֶׁהֲרֵי עַל הַכֹּל יֵשׁ לְהוֹדוֹת לַקָּדוֹשׁ- בָּרוּךְ-הוּא - בַּיֵּצֶר הַטּוֹב וּבַיֵּצֶר הָרָע. שֶׁהֲרֵי מִצַּד שֶׁל יֵצֶר הַטּוֹב בָּא טוֹב לָאָדָם, וְיֵשׁ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא הַטּוֹב וְהַמֵּטִיב. וּבַצַּד שֶׁל יֵצֶר הָרָע בָּא קִטְרוּג לָאָדָם, וְיֵשׁ לְהוֹדוֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא (ביצר הטוב וביצר הרע) בְּכָל מַה שֶּׁבָּא עַל הָאָדָם מִצַּד זֶה וּמִצַּד זֶה.</p>\n<p>בְּסוֹד יְשָׁרִים וְעֵדָה. בְּסוֹד יְשָׁרִים - בְּאוֹתָם (מלאכים עליונים קדושים) שֶׁאֶת סוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם יוֹדְעִים, שֶׁהֲרֵי אֶת כָּל סוֹדוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא הֵם יוֹדְעִים, וְהֵם הַסּוֹד שֶׁלּוֹ. וְלָכֵן בְּסוֹד יְשָׁרִים וְעֵדָה - אֵלֶּה הֵם יִשְׂרָאֵל, כְּשֶׁמִּתְכַּנְּסִים בַּעֲשָׂרָה לְהוֹדוֹת לַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִשּׁוּם כָּךְ יֵשׁ לְהוֹדוֹת לַקָּדוֹשׁ בָּרוּךְ הוּא עַל טוֹב וְעַל רַע וּלְפַרְסֵם לִפְנֵי הַכֹּל. שֶׁאִם תֹּאמַר, הֲרֵי הוּא יוֹדֵעַ, אָז לָמָּה צָרִיךְ לְפַרְסֵם? אֶלָּא בָּזֶה מִתְכַּבֵּד הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם לְפַרְסֵם אֶת הַנֵּס, וְעַל זֶה כָּתוּב בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, (יחזקאל לח) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְגוֹ'.</p>"],[9522011779,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים קנ) כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ. שָׁנִינוּ, כָּל הַנְּשָׁמוֹת בָּאוּ מֵהַגּוּף הַקָּדוֹשׁ הַזֶּה וּמִתְעוֹרְרוֹת בִּבְנֵי אָדָם. וּמֵאֵיזֶה מָקוֹם? מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יָד (י\"ה). מֵאֵיזֶה מָקוֹם זֶה? אָמַר רַבִּי יְהוּדָה, שֶׁכָּתוּב (שם קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ. שָׁנִינוּ, מֵהַחָכְמָה הַזּוֹ שֶׁמַּבּוּעֶיהָ יוֹצְאִים לִשְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים הַכֹּל נִתְקַן, וְכָל מַה שֶּׁיֵּשׁ לְמַעְלָה וּלְמַטָּה, וְהִיא נִקְרֵאת רוּחַ קְדוֹשָׁה שֶׁכָּל הָרוּחוֹת נִתְקְנוּ בָהּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, בַּיּוֹם שֶׁהָיָה רַבִּי שִׁמְעוֹן מְפָרֵשׁ דָּבָר זֶה, הָיוּ עֵינָיו נוֹבְעוֹת מַיִם, וְהָיָה אוֹמֵר: כָּל גִּנְזֵי הַמֶּלֶךְ הָעֶלְיוֹן נִמְסְרוּ בְמַפְתֵּחַ אֶחָד, וּמִתְגַּלֶּה בַּהֵיכָלוֹת הַמְצֻיָּרִים הָעֶלְיוֹנִים הַחֲקוּקִים.</p>\n<p>אֶלָּא כָּךְ שָׁנִינוּ, מִי יָכוֹל לָדַעַת וּלְהִכָּלֵל מַה שֶּׁגָּנוּז בַּמַּבּוּעַ הַזֶּה, שֶׁהֲרֵי מֹשֶׁה לֹא גִלָּה אֶת זֶה בְּיָמָיו כְּשֶׁהָיָה מְגַלֶּה סוֹד הֶעָמֹק לְיִשְׂרָאֵל, וְאַף עַל גַּב שֶׁהַכֹּל הָיָה מִתְגַּלֶּה עַל יָדוֹ. אֶלָּא בְּאוֹתָהּ שָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲלוֹתוֹ לַיְשִׁיבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה וּלְהַטְמִינוֹ מִבְּנֵי אָדָם, שֶׁכָּתוּב (דברים לא) בֶּן מֵאָה וְעֶשְׂרִים שָׁנָה אָנֹכִי הַיּוֹם. הַיּוֹם מַמָּשׁ. שֶׁאוֹתוֹ יוֹם נִשְׁלְמוּ יָמָיו לְהִתְקָרֵב לַמָּקוֹם הַזֶּה, שֶׁכָּתוּב (שם) הֵן קָרְבוּ יָמֶיךְ, קָרְבוּ מַמָּשׁ.</p>"],[9522011780,"<p>שֶׁשָּׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, מֹשֶׁה לֹא מֵת. וְאִם תֹּאמַר, הֲרֵי כָּתוּב (שם לה) וַיָּמָת שָׁם מֹשֶׁה? כָּךְ בְּכָל מָקוֹם לַצַּדִּיקִים קוֹרֵא בָהֶם מִיתָה. מָה הַמִּיתָה? מֵהַצַּד שֶׁלָּנוּ זֶה נִקְרָא כָּךְ. שֶׁשָּׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, וְכֵן שָׁנָה, שֶׁמִּי שֶׁהוּא בִּשְׁלֵמוּת, שֶׁהָאֱמוּנָה הַקְּדוֹשָׁה תְּלוּיָה בּוֹ - לֹא תְלוּיָה בּוֹ מִיתָה וְלֹא מֵת. כְּמוֹ שֶׁהָיָה בְּיַעֲקֹב שֶׁהָאֱמוּנָה הַשְּׁלֵמָה הָיְתָה בּוֹ.</p>\n<p>שֶׁאָמַר רַבִּי שִׁמְעוֹן, (בראשיתלה) לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל. מַה זֶּה יִשְׂרָאֵל? שְׁלֵמוּת הַכֹּל, שֶׁכָּתוּב (ירמיה מו) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב וְאַל תֵּחַת יִשְׂרָאֵל כִּי הִנְנִי מוֹשִׁעֲךְ מֵרָחוֹק וְאֶת זַרְעֲךְ מֵאֶרֶץ שִׁבְיָם וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה מִכָּאן, כִּי אִתְּךְ אָנִי, דַּוְקָא. אַשְׁרֵי חֶלְקוֹ שֶׁרִבּוֹנוֹ אָמַר לוֹ כֵּן. לֹא כָתוּב כִּי אִתִּי אַתָּה, אֶלָּא כִּי אִתְּךְ אָנִי, שֶׁרִבּוֹנוֹ בָּא לְחַבֵּר אֶת דִּיּוּרוֹ עִמּוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, יָפֶה אָמַר רַבִּי אַבָּא, שֶׁאָמַר וְשָׁב יַעֲקוֹב וְשָׁקַט וְשַׁאֲנַן וְאֵין מַחֲרִיד. וְשָׁב יַעֲקוֹב - לְהִקָּרֵא בְשֵׁם אַחֵר, שֶׁכָּתוּב לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל.</p>\n<p>דָּבָר אַחֵר וְשָׁב יַעֲקֹב - לַמָּקוֹם שֶׁנִּלְקַח מִשָּׁם. וְשָׁקַט - בָּעוֹלָם הַזֶּה. וְשַׁאֲנַן - בָּעוֹלָם הַבָּא. וְאֵין מַחֲרִיד - מִמַּלְאַךְ הַמָּוֶת. שֶׁמַּשְׁמָע שֶׁהַכֹּל הָיָה בּוֹ. רַבִּי יִצְחָק אָמַר, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁכָּתוּב וְאֶת זַרְעֲךְ מֵאֶרֶץ שִׁבְיָם. מַה זַּרְעוֹ בַּחַיִּים, אַף הוּא בַּחַיִּים.</p>"],[9522011781,"<p>וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה. רַבִּי יְהוּדָה פָּתַח, (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. וְכָתוּב, אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ. (במהבארנואתהפסוקיםהללו) אוֹי לָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים בַּעֲבוֹדַת רִבּוֹנָם, שֶׁהֲרֵי רִבּוֹנָם מַשְׁגִּיחַ בִּגְלָלָם לְהֵיטִיב לָהֶם, שֶׁהִנִּיחַ לִפְנֵיהֶם דִּבְרֵי תוֹרָה, וְלֹא מַשְׁגִּיחִים.</p>\n<p>שֶׁשָּׁנִינוּ, שְׁלֹשָׁה דְבָרִים צָרִיךְ אָדָם לַעֲשׂוֹת לִבְנוֹ: מִילָה, וּפִדְיוֹן, וּלְהַשִּׂיאוֹ אִשָּׁה. וְהַכֹּל עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. מִילָה - שֶׁכָּתוּב (יהושע ה) וְשׁוּב מֹל אֶת בְּנֵי יִשְׂרָאֵל שֵׁנִית, וְכָתוּב (בראשית יז) וּבֶן שְׁמֹנַת יָמִים יִמּוֹל לָכֶם כָּל זָכָר. פִּדְיוֹן - שֶׁכָּתוּב (דבריםז) וַיִּפְדְּךְ (ה' אלהיך מבית עבדים) מִיַּד פַּרְעֹה מֶלֶךְ מִצְרָיִם. לְהַשִּׂיאוֹ אִשָּׁה - שֶׁכָּתוּב (בראשית א) זָכָר וּנְקֵבָה בָּרָא אֹתָם, וְכָתוּב וַיְבָרֶךְ אֹתָם אֱלֹהִים וַיֹּאמֶר לָהֶם אֱלֹהִים פְּרוּ וּרְבוּ. עוֹד, נָשָׂא אוֹתָם כְּמוֹ הַנֶּשֶׁר הַזֶּה שֶׁמַּטִּיל אֶת בָּנָיו עַל כְּתֵפָיו, שֶׁכָּתוּב (שמות יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים.</p>\n<p>אָמַר רַבִּי יוֹסֵי, הַכֹּל הוּא נָאֶה, אֲבָל הַתּוֹרָה חָזְרָה לִפְנֵי יִשְׂרָאֵל וְלִמְּדָה אוֹתָם יוֹתֵר מֵהַכֹּל. בֹּא וּרְאֵה, אֵין שֶׁבַח שֶׁל אָדָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא כְּמוֹ הַשֶּׁבַח שֶׁל הַתּוֹרָה, שֶׁכָּתוּב בָּהּ (משלי ח) בִּי מְלָכִים יִמְלֹכוּ.</p>\n<p>שֶׁהֲרֵי שָׁנִינוּ, כְּשֶׁעָלָה רַב הוּנָא לְשָׁם, מָצָא אֶת הַחֲכָמִים שֶׁעוֹסְקִים בַּפָּסוּק הַזֶּה שֶׁכָּתוּב, (ירמיה נא) וּפָקַדְתִּי עַל בֵּל בְּבָבֶל וְהֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו וְלֹא יִנְהֲרוּ אֵלָיו עוֹד גּוֹיִם. וְרַב הוּנָא לֹא הָיוּ מַשְׁגִּיחִים בּוֹ, שֶׁהֲרֵי לֹא הִכִּירוּ אוֹתוֹ בָּרִאשׁוֹנָה, מִשּׁוּם שֶׁהָיָה קָטָן. נִכְנַס לְבֵית הַמִּדְרָשׁ, וּמָצָא אֶת הַחֲכָמִים שֶׁהָיוּ אוֹמְרִים שֶׁבַּפָּסוּק הַזֶּה יֵשׁ לְהִתְבּוֹנֵן, אִם יִרְאָתוֹ וֶאֱלִילוֹ שֶׁל נְבוּכַדְנֶצַּר הָיָה שְׁמוֹ בֵּל - הֲרֵי כָּתוּב בּוֹ, (דניאל ד) וְעַד אֲחֵרִים נִכְנַס דָּנִיֵּאל שֶׁשְּׁמוֹ בֵּלְטְשַׁאצַּר כְּשֵׁם אֱלֹהַי? וְעוֹד, מַה זֶּה וְהוֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו?</p>"],[9522011782,"<p>עָמַד רַב הוּנָא בֵּין הַיְסוֹדוֹת שֶׁל הָעַמּוּדִים וְאָמַר, אִלּוּ הָיִיתִי בִּמְקוֹמִי, הָיִיתִי דּוֹרֵשׁ אֶת הַפָּסוּק הַזֶּה. לֹא הִתְבּוֹנְנוּ בוֹ. קָם שֵׁנִית וְאָמַר דָּבָר זֶה. בָּא רַבִּי יוּדַאי בַּר רַב וְהוֹשִׁיבוֹ לְפָנָיו. אָמַר לוֹ, אֱמֹר בְּנִי, אֱמֹר, שֶׁבְּדִבְרֵי תוֹרָה כָּתוּב בָּהֶם (משלי א) בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא וְגוֹ'.</p>\n<p>פָּתַח וְאָמַר, כָּךְ שָׁנִינוּ, בַּיָּמִים הָרִאשׁוֹנִים טֶרֶם בָּא יַעֲקֹב, הָיָה אָדָם שָׁלֵו בְּבֵיתוֹ. הִגִּיעַ זְמַנּוֹ - מֵת בְּלִי מַחֲלוֹת. כֵּיוָן שֶׁבָּא יַעֲקֹב, בִּקֵּשׁ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לוֹ: רִבּוֹן הָעוֹלָם, אִם נוֹחַ לְפָנֶיךְ, שֶׁיִּפֹּל אָדָם בְּבֵית חָלְיוֹ שְׁנַיִם אוֹ שְׁלֹשָׁה יָמִים, וְאַחַר כָּךְ יִתְכַּנֵּס לְעַמּוֹ, וִיצַוֶּה אֶת בֵּיתוֹ וְיָשׁוּב מֵחֲטָאָיו. אָמַר לוֹ: יָפֶה, וְאַתָּה תִּהְיֶה סִימָן בָּעוֹלָם. בֹּא וּרְאֵה מַה כָּתוּב בּוֹ, (בראשיתמח) וַיְהִי אַחֲרֵי הַדְּבָרִים הָאֵלֶּה וַיּאמֶר לְיוֹסֵף הִנֵּה אָבִיךְ חֹלֶה. כָּתוּב חֹלֶה, מַה שֶּׁלֹּא הָיָה לְאָדָם מִקֹּדֶם לָכֵן.</p>"],[9522011783,"<p>אַחַר שֶׁנִּפְטַר, לֹא הָיָה אָדָם שֶׁהָיוּ לוֹ מַחֲלוֹת שֶׁלֹּא מֵת, עַד שֶׁבָּא חִזְקִיָּה. מַה כָּתוּב בּוֹ? (ישעיה לח) בַּיָּמִים הָהֵם חָלָה חִזְקִיָּהוּ לָמוּת וְגוֹ'. בֹּא וּרְאֵה מַה כָּתוּב, וַיַּסֵּב חִזְקִיָּהוּ פָּנָיו אֶל הַקִּיר וַיִּתְפַּלֵּל אֶל ה'. אָמַר לוֹ:אִם נוֹחַ לְפָנֶיךְ שֶׁיִּתְרַפְּאוּ בְּנֵי אָדָם מִבֵּית חָלְיָם וְיוֹדוּ לְשִׁמְךְ, וְיַכִּירוּ וְיָשׁוּבוּ אַחַר כָּךְ בִּתְשׁוּבָה שְׁלֵמָה, וְיִמָּצְאוּ בְּנֵי הָעוֹלָם צַדִּיקִים לְפָנֶיךְ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: נָאֶה הוּא, וְאַתָּה תִּהְיֶה סִימָן לָזֶה בָּעוֹלָם, וְכָךְ הוּא מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן. זֶהוּ שֶׁכָּתוּב (שם) מִכְתָּב לְחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה בַּחֲלֹתוֹ וַיְחִי מֵחָלְיוֹ. וְשָׁנִינוּ, אוֹתוֹ יוֹם חָזְרָה הַשֶּׁמֶשׁ עֶשֶׂר דְּרָגוֹת.</p>\n<p>וְשָׁנִינוּ, מְרוֹדָךְ בַּלְאֲדָן הָיָה אוֹכֵל כָּל יוֹם בְּאַרְבַּע שָׁעוֹת וְיָשֵׁן עַד תֵּשַׁע שָׁעוֹת, וְאוֹתוֹ יוֹם יָשַׁן עַד תֵּשַׁע שָׁעוֹת. כְּשֶׁהִתְעוֹרֵר, רָאָה שֶׁשֶּׁמֶשׁ עוֹמֶדֶת בְּאַרְבַּע שָׁעוֹת. אָמַר, מַה זֶּה? בַּהֲרִיגַת הַכַּעַס קִנְטוּר קְשַׁרְתֶּם עָלַי? אָמְרוּ לוֹ, לָמָּה? אָמַר, שֶׁיָּשַׁנְתִּי יוֹם אֶחָד וּשְׁלִישׁ יוֹם. אָמְרוּ לוֹ, לֹא כָּךְ, אֶלָּא אֱלֹהֵי חִזְקִיָּהוּ עָשָׂה הַיּוֹם הַזֶּה שְׁנֵי נִסִּים: רִפֵּא אֶת חִזְקִיָּה מִבֵּית חָלְיוֹ, וְהֶחֱזִיר אֶת הַשֶּׁמֶשׁ לַזְּמַן הַזֶּה. אָמַר, וְכִי יֵשׁ בָּעוֹלָם אֱלוֹהַּ גָּדוֹל יוֹתֵר חוּץ מֵאֱלֹהַי?! אָמְרוּ, אֱלֹהֵי חִזְקִיָּהוּ.</p>\n<p>עָמַד וְכָתַב כְּתָבוֹ: שָׁלוֹם לְחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה וְשָׁלוֹם לֵאלֹהָיו וְשָׁלוֹם לִירוּשָׁלַיִם עִיר הַקֹּדֶשׁ. אַחַר כָּךְ נִמְלַךְ, וְקָם מִכִּסְאוֹ, וּפָסַע שָׁלֹשׁ פְּסִיעוֹת וְכָתַב אֲחֵרִים: שָׁלוֹם לָאֱלוֹהַּ הַגָּדוֹל שֶׁבִּירוּשָׁלַיִם וְשָׁלוֹם לְחִזְקִיָּהוּ מֶלֶךְ יְהוּדָה וְשָׁלוֹם לִירוּשָׁלַיִם עִיר הַקֹּדֶשׁ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה פָּסַעְתָּ בִּשְׁבִיל כְּבוֹדִי שָׁלֹשׁ פְּסִיעוֹת, חַיֶּיךְ מִמְּךְ יֵצְאוּ שְׁלֹשָׁה מְלָכִים שַׁלִּיטִים רוֹזְנִים וּמַצְבִּיאִים שֶׁשּׁוֹלְטִים בְּכָל הָעוֹלָם, וְרִאשׁוֹן מֵהֶם הָיָה נְבוּכַדְנֶצַּר.</p>\n<p>בֹּא וּרְאֵה מָה אָמַר לוֹ דָּנִיֵּאל, (דניאל ב) אַתָּה הוּא רֹאשׁ הַזָּהָב, וְאַחֲרֶיךְ תָּקוּם מַלְכוּת אַחֶרֶת רָעָה מִמְּךְ וּמַלְכוּת שְׁלִישִׁית אַחֶרֶת. מַה כָּתוּב? (שם ג) הַמֶּלֶךְ נְבוּכַדְנֶצַּר עָשָׂה צֶלֶם שֶׁל זָהָב. גָּבְהוֹ שִׁשִּׁים אַמּוֹת וְרָחְבּוֹ שֵׁשׁ אַמּוֹת. אָמַר נְבוּכַדְנֶצַּר, הַצֶּלֶם שֶׁרָאִיתִי הָיָה רֹאשׁוֹ שֶׁל זָהָב, מֵעָיו שֶׁל כֶּסֶף. אֲנִי אֶעֱשֶׂה הַכֹּל שֶׁל זָהָב, וְשֶׁתִּהְיֶה עֲטֶרֶת זָהָב בְּרֹאשׁוֹ.</p>\n<p>וְשָׁנִינוּ, אוֹתוֹ יוֹם כִּנֵּס אֶת כָּל הָאֻמּוֹת וְהָעַמִּים וְהַלְּשׁוֹנוֹת לַעֲבֹד לְאוֹתוֹ הַצֶּלֶם, וְלָקַח כְּלִי מִכְּלֵי הַמִּקְדָּשׁ שֶׁבּוֹ הָיָה חָקוּק הַשֵּׁם הַקָּדוֹשׁ וְהִכְנִיסוֹ בְּפִי אוֹתוֹ צֶלֶם. וּבְאוֹתָהּ שָׁעָה הָיָה מְדַבֵּר גְּדוֹלוֹת, עַד שֶׁבָּא דָּנִיֵּאל וְקָרַב לְאוֹתוֹ הַצֶּלֶם וְאָמַר: אֲנִי שָׁלִיחַ שֶׁל הָרִבּוֹן הָעֶלְיוֹן, גּוֹזֵר אֲנִי עָלֶיךְ לָצֵאת מִכָּאן. הִזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ, וְיָצָא אוֹתוֹ כְּלִי, וְנָפַל הַצֶּלֶם וְנִשְׁבַּר. הַיְנוּ מַה שֶּׁכָּתוּב, וְהֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו וְלֹא יִנְהֲרוּ אֵלָיו עוֹד גּוֹיִם. קָם רַבִּי יְהוּדָה וּנְשָׁקוֹ עַל רֹאשׁוֹ. אָמַר, אִם לֹא שֶׁקֵּרַבְתִּי אוֹתְךְ לַחֲבוּרָה כָּאן, לֹא הִכַּרְנוּ אוֹתְךְ. וּמֵאוֹתוֹ יוֹם הָיוּ פוֹחֲדִים מִפָּנָיו.</p>"],[9522011784,"<p>שָׁנִינוּ, (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ. רַבִּי יוֹסֵי בֵּאֵר אֶת הַפָּסוּק הַזֶה בְּמֹשֶׁה בְּשָׁעָה שֶׁהוֹצִיא אֶת יִשְׂרָאֵל מִמִּצְרַיִם וְעָשָׂה אוֹתָם בְּנֵי חוֹרִין. וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ, שֶׁכָּתוּב (שמות יב) וַאֲכַלְתֶּם אֹתוֹ בְּחִפָּזוֹן פֶּסַח הוּא לַה'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, וְכִי לֹא אָמַרְתִּי שֶׁדִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ, שֶׁכֻּלָּם בִּפְנִים, לְתוֹךְ הַהֵיכָל הַקָּדוֹשׁ הָיוּ. וְזֶה שֶׁאֲמַרְתֶּם, הַכֹּל יָפֶה הָיָה וְלִדְרָשָׁה הוּא בָּא, אֲבָל פָּסוּק זֶה לְמַעְלָה בַּהֵיכָל הַקָּדוֹשׁ הוּא.</p>\n<p>שָׁנִינוּ, אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים. מַה זֶּה אֶרֶץ? אֶרֶץ סְתָם, שֶׁלָּמַדְנוּ, מַהוּ שֶׁכָּתוּב (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל? אֶלָּא הָאָרֶץ הַזּוֹ הִיא סוֹד בְּתוֹךְ כִּתְרֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁכָּתוּב בּוֹ (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. וְהָאָרֶץ הַזּוֹ וְכָל מַה שֶּׁיּוֹנֵק וְנִזּוֹן, הוּא מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא שָׁמַיִם, וְלֹא נִזּוֹנֵית הָאָרֶץ הַזּוֹ אֶלָּא מִשְּׁלֵמוּת הַקִּדֻשָּׁה שֶׁנִּקְרֵאת שָׁמַיִם.</p>\n<p>וּבְשָׁעָֹה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲרִיב אֶת בֵּיתוֹ שֶׁלְּמַטָּה וְהָאָרֶץ הַקְּדוֹשָׁה שֶׁלְּמַטָּה, הֶעֱבִיר בָּרִאשׁוֹנָה אֶת הָאָרֶץ הַקְּדוֹשָׁה שֶׁלְּמַעְלָה, וְהוֹרִידָהּ מֵאוֹתָהּ דַּרְגָּה שֶׁהָיְתָה יוֹנֶקֶת מֵהַשָּׁמַיִם הַקְּדוֹשִׁים, וְאַחַר כָּךְ הֶחֱרִיב אֶת זוֹ שֶׁלְּמַטָּה. זֶהוּ שֶׁכָּתוּב הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וְלֹא זָכַר הֲדם רַגְלָיו. שֶׁשָּׁנִינוּ, כָּךְ דַּרְכּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא: כְּשֶׁרוֹצֶה לָדוּן אֶת הָעוֹלָם, בָּרִאשׁוֹנָה עוֹשֶׂה דִין לְמַעְלָה, וְאַחַר כָּךְ מִתְקַיֵּם לְמַטָּה, שֶׁכָּתוּב (ישעיהכד) יִפְקוֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם - בָּרִאשׁוֹנָה. וְאַחַר כָּךְ - וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים - שֶׁזָּן אוֹתְךְ בְּרֹב כֹּל, בְּלִי פַחַד שֶׁל אַחֵר, וּמֵאוֹתוֹ הַמֶּלֶךְ הָעֶלְיוֹן נִזּוֹן הַכֹּל. וְשָׂרַיִךְ בָּעֵת יֹאכֵלוּ - כְּמוֹ שֶׁנֶּאֱמַר (במדבר כג) כָּעֵת יֵאָמֵר לְיַעֲקֹב וּלְיִשְׂרָאֵל מַה פָּעַל אֵל. אִי לָךְ אֶרֶץ שֶׁמַּלְכֵּךְ נָעַר - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ג) וְנָתַתִּי נְעָרִים שָׂרֵיהֶם. שֶׁאוֹי לָאָרֶץ כְּשֶׁיּוֹנֶקֶת מִשְּׂמֹאל. וְשָׂרַיִךְ בַּבֹּקֶר יֹאכֵלוּ - בְּאוֹתָהּ קַדְרוּת, וְעַד שֶׁלֹּא מֵאִיר וְלֹא שׁוֹלֵט מַה שֶּׁשּׁוֹלֵט.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה - זֶהוּ יַעֲקֹב הַקָּדוֹשׁ הַשָּׁלֵם, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם יֹשֵׁב אֹהָלִים. לֹא כָתוּב יוֹשֵׁב אֹהֶל, אֶלָּא יֹשֵׁב אֹהָלִים, שְׁנַיִם, שֶׁאוֹחֵז אֶת זֶה וְאוֹחֵז אֶת זֶה. אַף כָּאן כָּתוּב וְהַבְּרִיחַ הַתִּיכֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה, שֶׁאוֹחֵז אֶת זֶה וְאוֹחֵז אֶת זֶה.</p>\n<p>שֶׁשָּׁנִינוּ, מַהוּ אִישׁ תָּם? כְּתַרְגּוּמוֹ - שָׁלֵם. שָׁלֵם מֵהַכֹּל, שָׁלֵם לִשְׁנֵי צְדָדִים, לְעַתִּיקָא קַדִּישָׁא וְלִזְעֵיר אַפִּין. שָׁלֵם לְחֶסֶד עֶלְיוֹן וְלִגְבוּרָה עֶלְיוֹנָה, וּמַשְׁלִים לְזֶה וּלְזֶה.</p>"],[9522011785,"<p>אָמַר רַבִּי שִׁמְעוֹן, רָאִיתִי שֶׁהֲרֵי הַחָכְמָה הַכְּלָל שֶׁל הַכֹּל. וְחֶסֶד עֶלְיוֹן יוֹצֵא מֵחָכְמָה. גְּבוּרָה שֶׁהִיא דִּין הַקָּשֶׁה יוֹצֵאת מִבִּינָה. יַעֲקֹב מַשְׁלִים לִשְׁנֵי הַצְּדָדִים, וְהָאָבוֹת כְּלַל הַכֹּל, וְיַעֲקֹב כְּלָל שֶׁל הָאָבוֹת.</p>\n<p>שָׁנִינוּ, הִכָּה הַחָכְמָה בַּשְּׁבִיל שֶׁלּוֹ, וְכָנַס בָּרוּחַ (מים), וְהִתְכַּנְּסוּ הַמַּיִם לְמָקוֹם אֶחָד, וְנִפְתְּחוּ חֲמִשִּׁים שַׁעֲרֵי בִינָה. מֵהַשְּׁבִילִים הַלָּלוּ יוֹצְאִים עֲשָׂרָה כְתָרִים בְּקַרְנַיִם זוֹהֲרוֹת, וְנִשְׁאֲרוּ עֶשְׂרִים וּשְׁנַיִם שְׁבִילִים. הִכְּתָה אוֹתָהּ רוּחַ בְּאוֹתָם שְׁבִילִים, וְנִפְתְּחוּ חֲמִשִּׁים שַׁעֲרֵי בִינָה, וְנֶחְקְקוּ עֶשְׂרִים וּשְׁנַיִם בַּחֲמִשִּׁים שַׁעֲרֵי הַיּוֹבֵל, וְנִתְעַטְּרוּ בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ. אֵלּוּ נִפְתְּחוּ לִצְדָדָיו.</p>\n<p>וְהִתְעַטְרוּ עֶשְׂרִים וּשְׁנַיִם כִּתְרֵי הָרַחֲמִים שֶׁכְּלוּלִים בְּעַתִּיק הַיָּמִים (כתר) שֶׁמֵּאִיר לָהֶם כָּל אֶחָד בְּצִדּוֹ. הִתְעַטְּרוּ חֲמִשִּׁים חֲקִיקוֹת בְּמ\"ב אוֹתִיּוֹת קְדוֹשׁוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁבָּהֶן נִבְרְאוּ שָׁמַיִם וָאָרֶץ. וְנֶחְקְקוּ בַחֲקִיקוֹתֵיהֶם שְׁמוֹנָה שְׁעָרִים, שֶׁהֵן שְׁמוֹנֶה אוֹתִיּוֹת הָרַחֲמִים, שֶׁכָּתוּב (שמותלד) ה' ה' אֵל רַחוּם וְחַנּוּן, שֶׁיּוֹצֵא מֵהָעַתִּיק הַקָּדוֹשׁ לִזְעִירָא, וּמִתְחַבְּרִים בַּכְּתָרִים הַקְּדוֹשִׁים הַלָּלוּ, חָכְמָה וּבִינָה הָעֶלְיוֹנִים שֶׁעוֹלִים. יוֹצֵא חֶסֶד עֶלְיוֹן מִצַּד זֶה, וְדִין הַגְּבוּרָה מִצַּד זֶה. בָּאָה זְכוּת שֶׁל יַעֲקֹב וּמַשְׁלִימָה אֶת שְׁנֵיהֶם וְאוֹחֶזֶת אוֹתָם, שֶׁהֲרֵי הִיא הַשְּׁלֵמוּת הָעֶלְיוֹנָה.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם כָּךְ נִקְרָא יִשְׂרָאֵל. שֶׁשָּׁנִינוּ, יַעֲקֹב הַתַּחְתּוֹן, יִשְׂרָאֵל הָעֶלְיוֹן. יַעֲקֹב אֵינוֹ שְׁלֵמוּת, יִשְׂרָאֵל שְׁלֵמוּת הַכֹּל. וְכֵן שָׁנִינוּ, נְאֻם דָּוִד בֶּן יִשַׁי - דָּוִד אֵינוֹ שְׁלֵמוּת, שֶׁהֲרֵי אַחֲרוֹן הוּא. יִשַׁי יְסוֹד עֶלְיוֹן הוּא וּשְׁלֵמוּת. וְהַיְנוּ מַה שֶּׁשָּׁנִינוּ, לֹא גָלוּ יִשְׂרָאֵל מֵאַרְצָם עַד שֶׁכָּפְרוּ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וּבְמַלְכוּת בֵּית דָּוִד, שֶׁכָּתוּב (שמואל ב כ) אֵין לָנוּ חֵלֶק בְּדָוִד וְלֹא נַחֲלָה בְּבֶן יִשַׁי אִישׁ לְאֹהָלָיו יִשְׂרָאֵל. מַה זֶּה אִישׁ לְאֹהָלָיו? מָקוֹם שֶׁעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שׁוֹרֶה בְתוֹכָם, הַיְנוּ לֵא לֹהָיו.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כְּשֶׁמַּתְחִילָה חָכְמָה לַחֲקֹק חֲקִיקוֹת בְּכָל הַכְּתָרִים, מֵאֵיזֶה כֶּתֶר מַתְחִילָה? מֵאוֹתָהּ שֶׁנִּקְרֵאת בִּינָה. בַּבִּינָה הַכֹּל נִכְלָל, וּמִשּׁוּם כָּךְ נִפְתְּחוּ בָהּ חֲמִשִּׁים שְׁעָרִים, וְנִמְצָא שֶׁהַכֹּל נֶחְקְקוּ בַחָכְמָה. זֶהוּ שֶׁכָּתוּב (תהלים קד) כֻּלָּם בְּחָכְמָה עָשִׂיתָ.</p>"],[9522011786,"<p>שָׁנִינוּ, כָּתוּב (ישעיה מ) מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְגוֹ'. בְּשָׁעֳלוֹ מַיִם, מָה הַמַּיִם? זֶהוּ בִּינָה. רַבִּי אֶלְעָזָר שׁוֹנֶה כָּךְ, זֶה חֶסֶד. אָמַר לוֹ רַבִּי שִׁמְעוֹן, הַכֹּל עוֹלֶה (נתקן) בְּמִשְׁקָל אֶחָד. וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן, מִי הַשָּׁמַיִם? תִּפְאֶרֶת, שֶׁכָּתוּב תִּפְאֶרֶת יִשְׂרָאֵל. וְכָל בַּשָּׁלִשׁ עֲפַר הָאָרֶץ - זוֹהִי גְבוּרָה. וְשָׁקַל בַּפֶּלֶס הָרִים - אֵלֶּה הֵם שְׁאָר הַכְּתָרִים שֶׁנִּקְרָאִים הָרֵי אֲפַרְסְמוֹן זַךְ. וּגְבָעוֹת בְּמֹאזְנָיִם - אֵלּוּ שְׁאָר הַמֶּרְכָּבוֹת הַתַּחְתּוֹנוֹת מֵהֶם.</p>\n<p>בֹּא וּרְאֵה, בְּשָׁעֳלוֹ, מַה זֶּה בְּשָׁעֳלוֹ? זוֹ רוּחַ חָכְמָה. שֶׁכָּךְ שָׁנִינוּ, שַׁעַל הַסְּבָךְ בְּאַפִּרְיוֹן שְׁקוּעִים.</p>\n<p>וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן, מִי הַזֶּרֶת? אֵלּוּ אוֹתָם (חמשים) שְׁעָרִים שֶׁנִּפְתְּחוּ וְהִתְפַּזְּרוּ לְכָל הַצְּדָדִים, כְּמוֹ שֶׁנֶּאֱמַר וְזֵרִיתִי פֶרֶשׁ עַל פְּנֵיכֶם וְגוֹ'. וְכָל בַּשָּׁלִשׁ, מִי הַשָּׁלִישׁ? רַחֲמִים, שְׁלֵמוּת הַכֹּל. וְשָׁקַל בַּפֶּלֶס, מַה זֶּה פֶּלֶס? אָמַר רַבִּי שִׁמְעוֹן, שֶׁכָּתוּב מֹאזְנֵי צֶדֶק. אַבְנֵי צֶדֶק. עוֹד אָמַר רַבִּי שִׁמְעוֹן, הַדְּבָרִים הַלָּלוּ בְּשִׁעוּר שֶׁל יוֹצֵר הַכֹּל בֵּאַרְנוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, מִזֶּה נִשְׁמָע שֶׁיַּעֲקֹב יָצָא מִתּוֹךְ דִּין קָשֶׁה, שֶׁהֲרֵי יִצְחָק דִּין קָשֶׁה אָחַז לְחֶלְקוֹ. אָמַר לוֹ רַבִּי שִׁמְעוֹן, וְזֶה הוּא לְבַדּוֹ? וַהֲרֵי יִצְחָק יָצָא מִתּוֹךְ חֶסֶד, וְכָךְ כֻּלָּם, דִּין יוֹצֵא מִתּוֹךְ רַחֲמִים, וְרַחֲמִים מִדִּין. אַבְרָהָם יָרַשׁ יְרֻשַּׁת חֶסֶד, וְיָצָא יִצְחָק בְּדִין מִתּוֹךְ חֶסֶד. יַעֲקֹב יָצָא בְרַחֲמִים מִתּוֹךְ הַדִּין הַקָּשֶׁה, וְכָךְ הוּא לְמַעְלָה זֶה מִזֶּה, וְיוֹנֵק זֶה מִזֶּה, עַד שֶׁנּוֹדָע שֶׁהַכֹּל הוּא אֶחָד, וּמֵאֶחָד תְּלוּיִים כֻּלָּם, וְהַכֹּל נִמְצָא אֶחָד. בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, נוֹדָע שֶׁאֵין שְׁלֵמוּת אֶלָּא כְּשֶׁאוֹחֵז זֶה מִזֶּה, (ואחד) וְזֶה אוֹחֵז בִּשְׁנֵיהֶם לְשַׁכְלֵל אֶת הַכֹּל, כְּמוֹ יַעֲקֹב, וְהַיְנוּ שֶׁכָּתוּב מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה.</p>\n<p>שָׁנִינוּ, כָּל זֶה לֹא נִקְרָא אֶלָּא מִצַּד שֶׁלָּנוּ, וּמִצַּד שֶׁלָּנוּ הַכֹּל נוֹדָע. (שהרי בזה למעלה) וּלְמַעְלָה הַכֹּל עוֹלֶה בְּמִשְׁקָל אֶחָד, לֹא שׁוֹנֶה וְלֹא יִשְׁתַּנֶה, כְּמוֹ שֶׁכָּתוּב (מלאכי ג) אֲנִי ה' לֹא שָׁנִיתִי. אָמַר רַבִּי יְהוּדָה, כָּל הַמְּנוֹרוֹת מְאִירוֹת מֵאֶחָד וּתְלוּיוֹת מֵאֶחָד, וְהַמְּנוֹרוֹת הֵן הַכֹּל אֶחָד, שֶׁהֲרֵי לֹא רָצוּ לְהִפָּרֵד, וּמִי שֶׁמַּפְרִידָם כְּאִלּוּ נִפְרָד מֵחַיֵּי הָעוֹלָם.</p>"],[9522011787,"<p>אָמַר רַבִּי יִצְחָק, כָּתוּב (ישעיה ג) וְנָתַתִּי נְעָרִים שָׂרֵיהֶם וְתַעֲלוּלִים יִמְשְׁלוּ בָם, הַיְנוּ שֶׁכָּתוּב (שמות כה) וְעָשִׂיתָ שְׁנַיִם כְּרֻבִים זָהָב. כָּתוּב (שמואל ב ו) יֹשֵׁב הַכְּרֻבִים, וְכָתוּב (שם כב) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף. יֹשֵׁב הַכְּרֻבִים - כְּשֶׁשּׁוֹרֶה לְהִתְיַשֵּׁב בִּשְׁלֵמוּת, כָּתוּב יֹשֵׁב הַכְּרֻבִים. (כשגמצא בשלמות) וּכְשֶׁלֹּא שׁוֹרֶה וְלֹא מִתְיַשֵּׁב הַמֶּלֶךְ בְּכִסֵּא, כָּתוּב וַיִּרְכַּב עַל כְּרוּב, אֶחָד, שֶׁלֹּא מִתְיַשֵּׁב הַמֶּלֶךְ בְּכִסֵּא. יֹשֵׁב הַכְּרֻבִים - שְׁנַיִם.</p>\n<p>אָמַר רַבִּי יוֹסֵי, אוֹי לָעוֹלָם כְּשֶׁכְּרוּב אֶחָד מַחֲזִיר פָּנָיו מֵחֲבֵרוֹ, שֶׁהֲרֵי כָּתוּב וּפְנֵיהֶם אִישׁ אֶל אָחִיו, כְּשֶׁהָיָה שָׁלוֹם בָּעוֹלָם. אָמַר רַבִּי יִצְחָק, הֲרֵי שָׁנִינוּ, (ויקרא יח) עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. אוֹי לְמִי שֶׁמְּגַלֶּה עֶרְוָתָם. כְּמוֹ זֶה כָּתוּב בְּיַעֲקֹב, מַבְרִחַ מִן הַקָּצֶה אֶל הַקָּצֶה. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בְּתִשְׁבַּחְתָּם כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר.</p>\n<p>שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, בַּיָּמִים הָרִאשׁוֹנִים הָיָה אָדָם אוֹמֵר לַחֲבֵרוֹ: אֱמֹר לִי דָּבָר אֶחָד מֵהַתּוֹרָה וְטֹל מָנֶה כֶּסֶף. עַכְשָׁו אוֹמֵר אָדָם לַחֲבֵרוֹ: טֹל מָנֶה כֶּסֶף וַעֲסֹק בַּתּוֹרָה. וְאֵין מִי שֶׁיַּשְׁגִּיחַ, וְאֵין מִי שֶׁיַּרְכִּין אָזְנוֹ, פְּרָט לְאוֹתָם מְעַטִּים (זרעים) קְדוֹשִׁים עֶלְיוֹנִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בָּהֶם, שֶׁכָּתוּב (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>"],[9522011788,"<p>וָוֵי הָעַמֻּדִים וַחֲשֻׁקֵיהֶם כָּסֶף. רַבִּי יִצְחָק אָמַר, וָוֵי הָעַמֻּדִים - הֲרֵי אָמַרְנוּ, כָּל אוֹתָם שֶׁנֶּאֱחָזִים מִקְּשָׁרִים קַיָּמִים עֶלְיוֹנִים, נִקְרָאִים וָוֵי הָעַמֻּדִים. וְכָל אוֹתָם שֶׁלְּמַטָּה תְּלוּיִים מֵאוֹתָם וָוִים. מַה זֶּה וָוִים? שֵׁשׁ בְּתוֹךְ שֵׁשׁ, וְנֶאֱחָזִים וּמוּשְׁקִים מִחוּט הַשִּׁדְרָה שֶׁעוֹמֵד עֲלֵיהֶם. וּבְסֵפֶר הַצְּנִיעוּת לָמַדְנוּ, וָוִים לְמַעְלָה, וָוִים לְמַטָּה, וְכֻלָּם עוֹלִים בְּמִשְׁקָל אֶחָד.</p>"],[9522011789,"<p>וְאַתָּה תְּצַוֶּה אֶת בְּנֵי יִשְׂרָאֵל וְגוֹ'. וְאַתָּה הַקְרֵב אֵלֶיךְ אֶת אַהֲרֹן אָחִיךְ וְגוֹ' (שמות כז). אָמַר רַבִּי חִיָּיא, מַה שּׁוֹנֶה כָּאן מִבְּכָל מָקוֹם, שֶׁכָּתוּב וְאַתָּה הַקְרֵב אֵלֶיךְ, וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב, וְאַתָּה תְּצַוֶּה אֶת בְּנֵי יִשְׂרָאֵל, (שמות ל) וְאַתָּה קַח לְךְ בְּשָׂמִים רֹאשׁ מָר דְּרוֹר? אֶלָּא הַכֹּל בְּסוֹד עֶלְיוֹן הוּא, לִכְלֹל הַשְּׁכִינָה עִמּוֹ.</p>\n<p>אָמַר רַבִּי יִצְחָק, אוֹר עֶלְיוֹן וְאוֹר תַּחְתּוֹן כְּלוּלִים כְּאֶחָד, נִקְרָאִים וְאַתָּה, כְּמוֹ שֶׁנֶּאֱמַר (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. וְעַל כֵּן לֹא כָתוּב וְהִקְרַבְתָּ אֶת אַהֲרֹן אָחִיךְ. וְצִוִּיתָ אֶת בְּנֵי יִשְׂרָאֵל, וְדִבַּרְתָּ אֶל כָּל חַכְמֵי לֵב. מִשּׁוּם שֶׁבַּזְּמַן הַהוּא מְאִירָה הַשֶּׁמֶשׁ בַּיָּרֵחַ, וּמִשְׁתַּתֵּף הַכֹּל כְּאֶחָד, לִשְׁרוֹת עַל אֻמָּנוּת מַעֲשֵׂה הַמִּשְׁכָּן. אָמַר רַבִּי אֶלְעָזָר, מִכָּאן (שמות לו) אֲשֶׁר נָתַן ה' חָכְמָה וּתְבוּנָה בָּהֵמָּה.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, מִכָּאן, וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה. אֲשֶׁר מִלֵּאתִים צָרִיךְ לוֹמַר! אֶלָּא אֲשֶׁר מִלֵּאתִיו - לַלֵּב הַהוּא מִלֵּאתִיו רוּחַ חָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיהיא) וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וְגוֹ'. וְעַל זֶה צָרִיךְ אֲשֶׁר מִלֵּאתִיו רוּחַ חָכְמָה, שֶׁשּׁוֹרָה הַשֶּׁמֶשׁ בַּיָּרֵחַ בַּשְּׁלֵמוּת שֶׁל הַכֹּל, וְעַל כֵּן נִרְשְׁמוּ הַכֹּל בְּכָל מָקוֹם. אָמַר רַבִּי אֶלְעָזָר, אִם כֵּן, אֵלּוּ וְאַתָּה וְאַתָּה, אֵיךְ מִתְיַשְּׁבִים בַּפְּסוּקִים?</p>\n<p>אָמַר לוֹ, כֻּלָּם מִתְיַשְּׁבִים הֵם. וְאַתָּה הַקְרֵב אֵלֶיךְ - לְיַחֵד עִמּוֹ וּלְקָרֵב אֶצְלוֹ סוֹד הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁצָּרִיךְ. וְאַתָּה תְּדַבֵּר אֶל כָּל חַכְמֵי לֵב - לְפִי שֶׁכֻּלָּם לֹא בָאוּ לַעֲשׂוֹת מַעֲשֶׂה עַד שֶׁרוּחַ הַקֹּדֶשׁ מְדַבֶּרֶת בְּתוֹכָם וְלוֹחֶשֶׁת לָהֶם בְּלַחַשׁ, וְאָז עוֹשִׂים עֲבוֹדָתָם. וְאַתָּה תְּצַוֶּה אֶת בְּנֵי יִשְׂרָאֵל - רוּחַ הַקֹּדֶשׁ מְצַוָּה עֲלֵיהֶם וּמְאִירָה עֲלֵיהֶם לַעֲשׂוֹת מַעֲשֶׂה בְּרָצוֹן שָׁלֵם. וְאַתָּה קַח לְךְ - כְּמוֹ שֶׁפֵּרַשְׁנוּ, (שכתוב) וְאַתָּה הַקְרֵב אֵלֶיךְ. וְאֵלֶּה כֻּלָּם כָּאן בַּמַּעֲשֶׂה שֶׁל הַמִּשְׁכָּן. שֶׁהַכֹּל נַעֲשָׂה בְּסוֹד זֶה.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים כב) וְאַתָּה ה' אַל תִּרְחָק אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. וְאַתָּה ה' - הַכֹּל אֶחָד. אַל תִּרְחָק - לְהִתְרַחֵק מֵאִתָּנוּ לִהְיוֹת עוֹלֶה הָאוֹר הָעֶלְיוֹן מִלְּמַטָּה. שֶׁהֲרֵי כַּאֲשֶׁר מִתְעַלֶּה הָאוֹר הָעֶלְיוֹן מִלְּמַטָּה, אֲזַי נֶחְשָׁךְ כָּל הָאוֹר וְלֹא נִמְצָא כְּלָל בָּעוֹלָם.</p>\n<p>וְעַל זֶה נֶחֱרַב בֵּית הַמִּקְדָּשׁ בִּימֵי יִרְמְיָהוּ. וְאַף עַל גַּב שֶׁנִּבְנָה לְבַסּוֹף, לֹא חָזַר הָאוֹר לִמְקוֹמוֹ כְּמוֹ שֶׁצָּרִיךְ. וְעַל סוֹד זֶה שֵׁם הַנָּבִיא הַהוּא שֶׁהִתְנַבֵּא עַל כָּךְ - יִרְמְיָהוּ. הֶעְלֵם שֶׁל הָאוֹר הָעֶלְיוֹן, שֶׁעָלָה לְמַעְלָה לְמַעְלָה וְלֹא חָזַר לְהָאִיר לְבַסּוֹף כְּמוֹ שֶׁצָּרִיךְ. יִרְמְיָהוּ - הִתְעַלָּה וְלֹא חָזַר לִמְקוֹמוֹ, וְנֶחֱרַב בֵּית הַמִּקְדָּשׁ וְנֶחְשְׁכוּ הַמְּאוֹרוֹת.</p>\n<p>אֲבָל יְשַׁעְיָהוּ, הַשֵּׁם גּוֹרֵם הַיְשׁוּעָה, וּלְהַחֲזִיר הָאוֹר הָעֶלְיוֹן לִמְקוֹמוֹ (ישעיהו, להאיר האור העליון ולעשות ישועה) וְלִבְנוֹת בֵּית הַמִּקְדָּשׁ, וְכָל הַטּוֹבוֹת וְכָל הָאוֹרוֹת יַחְזְרוּ כְּבָרִאשׁוֹנָה. וְעַל זֶה שְׁמוֹתָם שֶׁל שְׁנֵי הַנְּבִיאִים הָאֵלּוּ עוֹמְדִים זֶה לְעֻמַּת זֶה, בְּסִבַּת הַשֵּׁם שֶׁגּוֹרֵם, וְצֵרוּף הָאוֹתִיּוֹת זוֹ בָּזוֹ גּוֹרְמוֹת מַעֲשֶׂה, הֵן לְטוֹב וְהֵן לְרַע. וְעַל סוֹד זֶה צֵרוּף הָאוֹתִיּוֹת שֶׁל הַשֵּׁמוֹת הַקְּדוֹשִׁים, וְכֵן הָאוֹתִיּוֹת בְּעַצְמָן גּוֹרְמוֹת לְהַרְאוֹת סוֹדוֹת עֶלְיוֹנִים כְּדֻגְמַת הַשֵּׁם הַקָּדוֹשׁ, שֶׁהָאוֹתִיּוֹת בְּעַצְמָן גּוֹרְמוֹת סוֹדוֹת עֶלְיוֹנִים קְדוֹשִׁים לְהַרְאוֹת בָּהֶם.</p>"],[9522011790,"<p>סוֹד הָרִאשׁוֹן - יוֹ\"ד, נְקֻדָּה רִאשׁוֹנָה שֶׁעוֹמֶדֶת עַל תִּשְׁעָה עַמּוּדִים הַמַּעֲמִידִים אוֹתָהּ. וְהֵם עוֹמְדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, כְּמוֹ שֶׁהַסּוֹף שֶׁל הַמַּחֲשָׁבָה, נְקֻדָּה אַחֲרוֹנָה, עוֹמֶדֶת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. חוּץ מִזֶּה שֶׁזֶּה זָכָר, וְזוֹהִי נְקֵבָה.</p>\n<p>וְזוֹ עוֹמֶדֶת בְּלִי גוּף, וְכַאֲשֶׁר עוֹמֶדֶת בַּלְּבוּשִׁים שֶׁמִּתְלַבֶּשֶׁת בָּהֶם, הִיא עוֹמֶדֶת עַל תִּשְׁעָה עַמּוּדִים, בַּסּוֹד שֶׁל הָאוֹת ם בְּלִי עִגּוּל. וְאַף עַל גַּב שֶׁאוֹת ס' הִיא בְעִגּוּל וְעוֹמֶדֶת בְּעִגּוּל, אֲבָל בְּסוֹד שֶׁל אוֹתִיּוֹת הַחֲקוּקוֹת תּוֹךְ נְקֻדּוֹת שֶׁל אוֹרוֹת שֶׁל מַעְלָה, הֵם בְּרִבּוּעַ, וְשֶׁל מַטָּה הוּא בְעִגּוּל.</p>\n<p>זֶה הָרִבּוּעַ הוּא עוֹמֵד בְּשִׁעוּר שֶׁל תֵּשַׁע נְקֻדּוֹת, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד. וְהֵם בְּשִׁעוּר שֶׁל חֶשְׁבּוֹן שְׁמֹנֶה נְקֻדּוֹת, וְהֵם תֵּשַׁע. וְאֵלּוּ הֵם שֶׁעוֹמְדִים מִסּוֹד שֶׁל הַנֵּר בְּרִבּוּעַ בְּתִשְׁעָה עַמּוּדִים לָאוֹת יוֹ\"ד, נְקֻדָּה אַחַת. וְאֵלּוּ הַתִּשְׁעָה הֵם שְׁמוֹנָה בְּסוֹד שֶׁל אוֹת ם בְּרִבּוּעַ, כְּמוֹ זֶה: שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד,</p>\n<p>וְזֶהוּ סוֹד הָאוֹת יוֹ\"ד, נְקֻדָּה אַחַת. וְאַף אַף גַּב שֶׁהִיא נְקֻדָּה אַחַת, הַצּוּרָה שֶׁלָּהּ - רֹאשׁ לְמַעְלָה, וְקוֹץ לְמַטָּה. וְהַשִּׁעוּר שֶׁלָּהּ שָׁלֹשׁ נְקֻדּוֹת כְּדֻגְמָא זוֹ: וְעַל כֵּן הִתְפַּשְּׁטוּתָהּ לְאַרְבָּעָה צְדָדִים, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד, הִיא תֵּשַׁע וְהִיא שְׁמוֹנֶה.</p>\n<p>וְאֵלּוּ הֵם הָעַמוּדִים שֶׁיּוֹצְאִים מִסּוֹד הַנֵּר לִהְיוֹת עַמּוּדִים לָאוֹת יוֹ\"ד, וְאֵלּוּ נִקְרָאִים מֶרְכָּבָה שֶׁלָּהּ. וְלֹא עוֹמְדִים בַּשֵּׁם, רַק בְּסוֹד תֵּשַׁע נְקֻדּוֹת שֶׁל הַתּוֹרָה.</p>\n<p>וּבַסּוֹד שֶׁל סִפְרוֹ שֶׁל אָדָם נֶחְלְקוּ אֵלּוּ הַתֵּשַׁע שֶׁהֵן שְׁמוֹנֶה, בְּצֵרוּף הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, כְּדֵי לְצָרֵף אוֹתָן וּלְיַחֵד אוֹתָן בְּכָל אֵלּוּ הַצּוּרוֹת כַּאֲשֶׁר נוֹסְעוֹת אֵלּוּ הַשְּׁמוֹנֶה שֶׁהֵן תֵּשַׁע, מְאִירוֹת בָּאוֹר שֶׁל אוֹת ם סְתוּמָה בְּרִבּוּעַ, וּמוֹצִיא אוֹרוֹת שְׁמוֹנָה (שמונהנראים) נִרְאִים וְאוֹתִיּוֹת תֵּשַׁע. וּמִתְחַלְּקוֹת לְמַטָּה לְהַנְהִיג אֶת כָּל הַמִּשְׁכָּן.</p>\n<p>וְאֵלּוּ הֵם צֵרוּף שֶׁל הַשֵּׁם הַקָּדוֹשׁ בְּסוֹד שֶׁל שִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת מְחֻקָּקוֹת שֶׁיּוֹצְאוֹת מִסּוֹד שֶׁל שָׁלֹשׁ צוּרוֹת, יָמִין וּשְׂמֹאל וְאֶמְצַע, וְהַכֹּל מִסּוֹד שֶׁל שָׁלֹשׁ נְקֻדּוֹת (ציור למעלה). שִׁעוּר שֶׁל אוֹת יוֹ\"ד, שֶׁהִיא לְאַרְבַּע צְדָדִים, וְהֵן שְׁמוֹנֶה נְקֻדּוֹת, וְהֵם תֵּשַׁע נְקֻדּוֹת, וְהֵם שְׁתֵּים עֶשְׂרֵה נְקֻדּוֹת עֶלְיוֹנוֹת, שָׁלֹשׁ שָׁלֹשׁ לְכָל צַד וְצַד, וּמִכָּאן יוֹרְדוֹת לְמַטָּה בִּשְׁתֵּים עֶשְׂרֵה לְשִׁשָּׁה קְצָווֹת. וְכַאֲשֶׁר נֶחְקָקוֹת שְׁתֵּים עֶשְׂרֵה אֵלּוּ בְּשֵׁשׁ קְצָווֹת, הֵם שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, סוֹד הַשֵּׁם הַקָּדוֹשׁ שֶׁל שִׁבְעִים וּשְׁנַיִם שֵׁהֵם הַשֵּׁם הַזֶּה הַקָּדוֹשׁ.</p>\n<p>וְהַסֹלֹ הוּא עוֹלֶה בְרָצוֹן, שֶׁסָּמַךְ הַמַּחֲשָׁבָה בְּאֵלּוּ שֶׁסּוֹמְכִים אֶת הָאוֹת יוֹ\"ד, וְעַל זֶה הָאוֹתִיּוֹת בְּצֵרוּפֵיהֶן - שָׁלֹשׁ שָׁלֹשׁ בְּכָל צֵרוּף שֶׁלּוֹ, בִּשְׁבִיל לַעֲלוֹת בְּרָצוֹן שֶׁל הָאוֹת י' שֶׁל שָׁלֹשׁ נְקֻדּוֹת, כְּמוֹ שֶׁאָמַרְנוּ, וְעַל זֶה לֹא עוֹלֶה בַּעֲלִיַּת הַצֵּרוּף אֶלָּא מֵעִקָּר וְשֹׁרֶשׁ שֶׁל סוֹד שֶׁל אֵלּוּ הַסּוֹמְכִים שֶׁסּוֹמְכִים לָאוֹת י', סוֹד שֶׁל אוֹת ם בְּרִבּוּעַ, תֵּשַׁע נְקֻדּוֹת, שְׁמוֹנֶה נְקֻדּוֹת, י\"ב נְקֻדּוֹת, שִׁבְעִים וּשְׁתַּיִם נְקֻדּוֹת. נִמְצָא שֶׁכָּל סוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ נִמְצָא בָּאוֹת י', וְהַכֹּל סוֹד אֶחָד וְעוֹמֵד בְּסוֹד הַנֵּר, כְּמוֹ שֶׁאָמַרְנוּ, לַעֲשׂוֹת סֶמֶךְ לְכָל אוֹת וָאוֹת. וְאֵלּוּ הָעַמּוּדִים הֵם מֶרְכָּבָה שֶׁלָּהֶם, שֶׁל כָּל אוֹת וָאוֹת, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>הַסּוֹד הַשֵּׁנִי - אוֹת חֲמִישִׁית שֶׁעוֹמֶדֶת עַל חֲמִשָּׁה עַמּוּדִים שֶׁסּוֹמְכִים אוֹתָהּ, שֶׁיּוֹצְאִים מִסּוֹד הַנֵּר, כַּאֲשֶׁר נֶאֱסָף לַעֲלוֹת לְמַעְלָה מִסּוֹד הַמִּדָּה.</p>\n<p>אוֹת זוֹ נִקְרֵאת הֵיכָל הַקָּדוֹשׁ, וּבְתוֹכָהּ הַנְּקֻדָּה שֶׁאָמַרְנוּ. וְהַכֹּל הוּא בַּסּוֹד שֶׁאָמַרְנוּ שֶׁל אוֹת ם בְּרִבּוּעַ. אֲבָל כָּאן לֹא נִרְשֶׁמֶת, רַק אוֹת ה', וְהַמֶּרְכָּבָה שֶׁלָּהּ חֲמִשָּׁה עַמּוּדִים שֶׁאָמַרְנוּ.</p>\n<p>וְכַאֲשֶׁר מַכֶּה אוֹר הַנֵּר בָּאוֹת י', מְאִירָה, וּמֵהַהַכָּאָה הַהִיא נַעֲשׂוּ אוֹתָם תִּשְׁעָה עַמּוּדִים שֶׁאָמַרְנוּ. וּמִתּוֹךְ הָאוֹר שֶׁמֵּאִיר אוֹת י', נִתְפַּשְּׁטוּ הַשָּׁלֹשׁ נְקֻדּוֹת שֶׁל י'. שְׁתַּיִם לְמַעְלָה, שֶׁהֵן הָרֹאשׁ, וְאֶחָד לְמַטָּה, שֶׁהוּא קוֹץ הַי', כְּמוֹ זֶה שֶׁאָמַרְנוּ. כַּאֲשֶׁר הִתְפַּשְּׁטוּ שְׁתַּיִם, נַעֲשׂוּ שָׁלֹשׁ. אַחַת נֶעֶשְׂתָה שְׁתַּיִם. וְנִתְפַּשְּׁטוּ וְנַעֲשֶׂה הֵיכָל אֶחָד. זֶה הַהֵיכָל, לְאַחַר שֶׁנַּעֲשָׂה הֵיכָל לִנְקֻדָּה אַחַת רִאשׁוֹנָה, נַעֲשָׂה גָנוּז וּמֻסְתָּר סוֹד שֶׁל אוֹת זוֹ, וְעוֹמֶדֶת עַל חָמֵשׁ אֲחֵרוֹת.</p>\n<p>אַרְבַּע גְּנוּזוֹת הֵן בִּנְקֻדָּה אַחַת שֶׁעוֹמֶדֶת בַּתָּוֶךְ בָּאֶמְצַע, וְהֵן חָמֵשׁ, וְהִיא אוֹת ה'. כְּמוֹ שֶׁאוֹת ה' שֶׁלְּמַטָּה עוֹמֶדֶת עַל אַרְבַּע, וְהִיא נְקוּדָה עַל אַרְבַּע וְעוֹמֶדֶת בְּתוֹךְ הָאֶמְצַע, כְּמוֹ כֵן הוּא כָּאן. וּמַה שֶּׁעוֹמֶדֶת עַל חֲמִשָּׁה עַמּוּדִים, כָּךְ הוּא וַדַּאי, לְפִי שֶׁזּוֹ הַנְּקֻדָּה הָעֶלְיוֹנָה הִיא עַל שְׁתֵּי בְחִינוֹת - אַחַת בְּעַצְמָהּ, וְאַחַת בְּהֶעְלֵם.</p>\n<p>וּבְסֵפֶר הַסּוֹדוֹת שֶׁל חֲנוֹךְ, אוֹת ה' וַדַּאי עוֹמֶדֶת עַל חֲמִשָּׁה עַמּוּדִים שֶׁיּוֹצְאִים מִתּוֹךְ הַנֵּר, וְאָז מוֹצִיא חֲמִשָּׁה עַמּוּדִים אֲחֵרִים, וְנִמְצֵאת אוֹת ה' הַזּוֹ בְּסוֹד הָעֲשָׂרָה. וְכַאֲשֶׁר נִפְרֶדֶת, עוֹמֶדֶת אוֹת ה' הַזּוֹ עַל עַמּוּדִים, וְאֵלּוּ הֵן י\"ג מִדּוֹת הָרַחֲמִים בְּדַרְגָּה אַחַת שֶׁנּוֹסֶפֶת עֲלֵיהֶן.</p>\n<p>וְאֵלּוּ הֵם י\"ב שֶׁנִּמְצָאִים בְּשֵׁשׁ. לִפְעָמִים הֵם אַרְבָּעִים וּשְׁתַּיִם, לִפְעָמִים שִׁבְעִים וּשְׁתַּיִם הֵן, אֲבָל יוֹרְדוֹת לְמַטָּה. וְכָאן נִפְרָדִים שְׁבִילִים לְכָל צַד, וְהֵם שְׁלֹשִׁים וּשְׁנַיִם, נִשְׁאָר אַרְבָּעִים. וּשְׁתֵּי אָזְנַיִם יָמִין וּשְׂמֹאל - הֲרֵי אַרְבָּעִים וּשְׁתַּיִם. אֵלּוּ אַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת עֶלְיוֹנוֹת, שֶׁהֵן אוֹתִיּוֹת גְּדוֹלוֹת שֶׁל הַתּוֹרָה.</p>\n<p>לְפִי שֶׁיֵּשׁ אוֹתִיּוֹת גְּדוֹלוֹת, וְיֵשׁ אוֹתִיּוֹת קְטַנּוֹת. אוֹתִיּוֹת גְּדוֹלוֹת הֵן לְמַעְלָה, אוֹתִיּוֹת קְטַנּוֹת לְמַטָּה, וְהַכֹּל לְמַטָּה כְּדֻגְמַת לְמַעְלָה. לְפִי שֶׁיֵּשׁ שֵׁמוֹת קְדוֹשִׁים עֶלְיוֹנִים שֶׁקַּיָּמִים בִּרְצוֹן הָרוּחַ וְהַלֵּב וּבְלִי דִבּוּר כְּלָל.</p>\n<p>וְיְשׁ שֵׁמוֹת קְדוֹשִׁים תַּחְתּוֹנִים שֶׁעוֹמְדִים בְּדִבּוּר וּבְהַמְשָׁכַת הַמַּחֲשָׁבָה וְהָרָצוֹן עֲלֵיהֶם. וְיֵשׁ שֵׁמוֹת אֲחֵרִים לְמַטָּה, שֶׁהֵם מֵהַצַּד הַהוּא הָאַחֵר, שֶׁהוּא מֵהַצַּד הַטָּמֵא, וְאֵלֶּה לֹא קַיָּמִים אֶלָּא בְרָצוֹן שֶׁל מַעֲשֶׂה לְמַטָּה, לְהַעֲלוֹת רָצוֹן שֶׁל הַמַּעֲשֶׂה הַהוּא שֶׁלְּמַטָּה אֵלָיו. לְפִי שֶׁהַצַּד הַהוּא הָאַחֵר אֵינוֹ, אֶלָּא בְּמַעֲשִׂים שֶׁל זֶה הָעוֹלָם לְהִטָּמֵא בָהֶם, כְּמוֹ בִּלְעָם וְאוֹתָם בְּנֵי קֶדֶם, וְכָל אוֹתָם שֶׁמִּתְעַסְּקִים בְּאוֹתוֹ הַצַּד הָאַחֵר.</p>\n<p>וְאֵלֶּה לֹא עוֹמְדִים בְּאוֹתִיּוֹת רְשׁוּמוֹת מִן שְׁתַּיִם וְעֶשְׂרִים שֶׁל הַתּוֹרָה, חוּץ מִשְּׁתַּיִם, וְהֵן אוֹת ח' וְאוֹת ק', וְסוֹמְכִים לָהֶם בִּסְמִיכוּת אוֹתִיּוֹת שֶׁל שֶׁקֶר. אֲבָל אֵלּוּ הֵן נוֹדָעוֹת אֶצְלָן יוֹתֵר. וְעַל זֶה בִּתְהִלָּה לְדָוִד, בְּכֻלָּם כָּתוּב אוֹת ו' בְּכָל אוֹת וָאוֹת, חוּץ מֵאֵלּוּ הַשְּׁתַּיִם שֶׁלֹּא כְתוּבָה אוֹת ו', שֶׁהֲרֵי אוֹת ו' הִיא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>וּבִשְׁבִיל זֶה אֵלּוּ הָאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁהָעוֹלָם הַזֶּה נִבְרָא בָהֶן, נִמְצָא שֶׁאוֹת ה' הָעֶלְיוֹנָה הַזֹּאת לְהַעֲלוֹת לְתִשְׁעִים וּשְׁתַּיִם. תִּשְׁעִים הֵם חוּץ מִשְּׁתֵּי אָזְנַיִם יָמִין וּשְׂמֹאל. וְסוֹד זֶה (וסימנך) - (בראשית יז) וְאִם שָׂרָה הֲבַת תִּשְׁעִים שָׁנָה תֵּלֵד. אֲבָל הוּא בְּחֶשְׁבּוֹן תִּשְׁעִים וּשְׁתַּיִם. וְכַאֲשֶׁר נוֹסֶפֶת דַּרְגָּה שֶׁל סוֹד הַבְּרִית, שֶׁהוּא רָקִיעַ שְׁמִינִי, וְעוֹמֵד לִשְׁמוֹנָה יָמִים, הֲרֵי מֵאָה. וְאֵלֶּה וַדַּאי מֵאָה בְרָכוֹת בְּכָל יוֹם שֶׁצְּרִיכָה כְּנֶסֶת יִשְׂרָאֵל לְהִתְקַשֵּׁט בָּהֶן. וְהַכֹּל בְּסוֹד אוֹת ה'.</p>\n<p>אוֹת ה' זוֹ הִיא צִיּוּר שֶׁלָּהּ בִּשְׁתֵּי אוֹתִיּוֹת נ', סוֹד שֶׁל מֵאָה, וְהֵם חֲמִשָּׁה עַמּוּדִים וּמֶרְכָּבוֹת הַיּוֹצְאִים מִתּוֹךְ הַנֵּר, וְהֵם חֲמִשָּׁה אֲחֵרִים שֶׁיּוֹצְאִים מִמֶּנָּה. וְעַל זֶה צִיּוּרָהּ כְּמוֹ זֶה: ן-ן. שְׁתֵּי נוּנִין, וּנְקֻדָּה שֶׁעוֹמֶדֶת בָּאֶמְצַע. וְעַל זֶה אוֹת ו' עוֹמֶדֶת בֵּינֵיהֶן תָּמִיד, כְּמוֹ זֶה נוּן, לְפִי שֶׁכָּאן הוּא מְקוֹמָהּ לְהִתְקַשֵּׁט, וְאַף עַל גַּב שֶׁסּוֹדוֹת אֲחֵרִים הֵם בְּסוֹד אוֹת ה', אֲבָל זֶה הוּא בְּסוֹדוֹת סִפְרוֹ שֶׁל חֲנוֹךְ, וְכָךְ הוּא בֶּאֱמֶת.</p>\n<p>וְכַאֲשֶׁר נִתְקֶנֶת בְּאֵלּוּ הַחֲמִשִּׁים לְבַדָּם, הִיא נְקֻדָּה אַחַת שֶׁעוֹמֶדֶת בְּסוֹד הָאוֹת נ', כְּמוֹ זֶה נ' - נוּ\"ן. וּנְקֻדָּה אַחַת בָּאֶמְצַע שֶׁהִיא שׁוֹלֶטֶת עֲלֵיהֶם, וְהַכֹּל בְּסוֹד אֶחָד. אַשְׁרֵי הֵם שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה לָלֶכֶת בִּדְרָכִים אֲמִתִּיּוֹת. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה, וְאַשְׁרֵיהֶם בָּעוֹלָם הַבָּא.</p>\n<p>סוֹד שְׁלִישִׁי - אוֹת ו'. אוֹת זוֹ צִיּוּר שֶׁל סוֹד אָדָם, כְּמוֹ שֶׁבֵּאַרְנוּ. וַהֲרֵי בֵּאַרְנוּ שֶׁאוֹת זוֹ עוֹמֶדֶת עַל י\"ב מֶרְכָּבוֹת, וְכַאֲשֶׁר נִפְרָדוֹת, הֵן אַרְבַּע וְעֶשְׂרִים מֶרְכָּבוֹת שֶׁכְּלוּלוֹת בָּאוֹת הַזּוֹ, הִתְפַּשְּׁטוּת דְּמוּת שֶׁל אָדָם, כְּנֶגֶד זְרוֹעוֹת וִירֵכַיִם וְגוּף, אֵיבָרִים שֶׁלָּהֶם אַרְבָּעָה וְעֶשְׂרִים הֵם שֶׁל זְרוֹעוֹת וִירֵכַיִם וְגוּף, הֲרֵי לָמַדְנוּ, אֲבָל כֻּלָּם סְתוּמִים בַּגּוּף, וְהַגּוּף עוֹמֵד בְּכָל הָאַרְבָּעָה וְעֶשְׂרִים, וְכָל הַמֶּרְכָּבוֹת כְּלוּלוֹת בַּגוּף זֶה, וּמִשּׁוּם שֶׁכְּלוּלוֹת כֻּלָּן בּוֹ, עוֹמֶדֶת ו' בְּהִתְפַּשְּׁטוּת אַחַת.</p>\n<p>גּוּף אֶחָד כָּלוּל בְּאַרְבַּע וְעֶשְׂרִים מֶרְכָּבוֹת, וְאֵלֶּה הֵן: הָרֹאשׁ בְּשֵׁשׁ, הַגּוּף בִּשְׁמוֹנֶה עֶשְׂרֵה. וְאַף עַל גַּב שֶׁכָּל הַמֶּרְכָּבוֹת הֵן (י' י') (י\"ח) שְׁתֵּים עֶשְׂרֵה לְכָל צַד - בַּכֹּל עוֹמֵד הַגּוּף. אֲבָל עֶשְׂרִים וְאַרְבַּע הֵן שֵׁשׁ שֶׁל הָרֹאשׁ, שֶׁהֵם אֵיבָרִים לְהַעֲלוֹת לָרֹאשׁ. שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת שֶׁמַּעֲמִידוֹת אֶת הָרֹאשׁ, וַעֲמִידַת הַגּוּף עֲלֵיהֶן.</p>\n<p>וְכֻלָּם הֵם הִתְפַּשְּׁטוּת אַחַת בָּרֹאשׁ וּבַגּוּף, וְאֵלּוּ הַשִּׁשִּׁים כֻּלָּם כּוֹלֵל אוֹתָם שֶׁהוּא סוֹד שֶׁל שֵׁשׁ. וְעַל זֶה שִׁעוּר שֶׁל הָאוֹת ו' - הָרֹאשׁ שִׁעוּרוֹ בְּשֵׁשׁ נְקֻדּוֹת מַמָּשׁ, הַגּוּף בִּשְׁמוֹנֶה עֶשְׂרֵה. כְּעֵין זֶה כָּל אֵלּוּ הַסּוֹדוֹת מִתְפָּרְשִׁים, לִכְלֹל אוֹתָם בַּגּוּף, לְפִי שֶׁהַזְּרוֹעוֹת וְהַיְרֵכַיִם כֻּלָּם בְּהֶעְלֵם, וְעַל זֶה כֻּלָּם נִכְלָלִים בְּסוֹד הָאוֹת ו' וְצִיּוּר שֶׁלָּהּ.</p>\n<p>וְכַאֲשֶׁר שְׁלֵמוּת שֶׁל אוֹת זוֹ נִרְאֵית, אָז כָּל הַצְּדָדִים הָרָעִים נִסְתָּמִים, וְנִפְרָדִים מֵהַלְּבָנָה וְלֹא מְכַסִּים, לְפִי שֶׁהִיא בוֹקַעַת כָּל חַלּוֹנוֹת שֶׁל הָרְקִיעִים וּמְאִירָה לָהּ, וְלֹא יָכוֹל הַמְקַטְרֵג לְהָרַע כְּלָל. וְכַאֲשֶׁר זֶה מִסְתַּלֵּק, אָז עוֹלֶה וּמַסְטִין וּמְפַתֶּה, וְיָכוֹל לְקַטְרֵג עַל כָּל בְּנֵי הָעוֹלָם, לְפִי שֶׁהוּא מֶלֶךְ זָקֵן וּכְסִיל, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>אוֹת ו' הִיא אוֹר שֶׁמֵּאִיר לַלְּבָנָה, וְאַף עַל גַּב שֶׁאוֹרוֹת רַבִּים נִכְלָלִים בּוֹ, אוֹר שֶׁמֵּאִיר לַשְּׁכִינָה הוּא אֶחָד פָּשׁוּט לְמַלֹּאת אוֹתָהּ. וְהוּא סוֹד הָאָלֶף, רָשׁוּם בְּכָל אֵלּוּ הַסּוֹדוֹת. וְכַאֲשֶׁר מֵאִיר לַשְּׁכִינָה, בְּסוֹד אוֹת ו' מֵאִיר לָהּ.</p>\n<p>וּבְסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן, בְּצִיּוּר הָאוֹתִיּוֹת אוֹת ו' נְקֻדָּה אַחַת לְמַעְלָה, וְחָמֵשׁ נְקֻדּוֹת שֶׁלְּמַטָּה, וְכֵן שִׁעוּר שֶׁלָּהּ כְּעֵין זֶה - ו', וְכָל נְקֻדָּה עוֹמֶדֶת בְּסוֹד עֶשֶׂר, לְפִי שֶׁאֵין לְךְ נְקֻדָּה שֶׁלֹּא נִשְׁלֶמֶת לְעֶשֶׂר, שֶׁכָּל נְקֻדָּה יֵשׁ בָּהּ תִּשְׁעָה עַמּוּדִים מֶרְכָּבוֹת, וְהַנְּקֻדָּה הַהִיא מַשְׁלִימָה לְעֶשֶׂר. נְקֻדָּה יְמָנִית תִּשְׁעָה עַמּוּדִים, וּמֶרְכָּבוֹת יֵשׁ לָהּ, וְהִיא עֲשָׂרָה. וְכֵן לִשְׂמֹאל, וְכֵן לְכָל הַצְּדָדִים. וְעַל זֶה כָּל נְקֻדּוֹת אֵלּוּ, כָּל אַחַת וְאַחַת כְּלוּלָה מֵעֶשֶׂר, הִיא וּמַרְכְּבוֹתֶיהָ. וְכֻלָּם כְּלוּלִים בַּהִתְפַּשְּׁטוּת הַהִיא שֶׁל הָאוֹת ו', וְעַל כֵּן הַכֹּל הוּא בְּצִיּוּר בְּסוֹד הָאוֹת ו'.</p>\n<p>וְכַאֲשֶׁר נִכְנָס הַשֶּׁמֶשׁ בַּלְּבָנָה, (הלבנה) יוֹצֵאת מֵאוֹת ו' הַזּוֹ הִתְפַּשְּׁטוּת אַחַת סוֹד הַבְּרִית, כְּעֵין אוֹת ג', וְזֶהוּ לְהִכָּנֵס בַּנְּקֵבָה. וְכַאֲשֶׁר נִכְלָל הַכֹּל בְּהִתְפַּשְּׁטוּת זוֹ שֶׁל אוֹת ו', אָז עוֹמֵד לְשַׁמֵּשׁ בַּנְּקֵבָה. וְסוֹד זֶה שֶׁכָּתוּב, וְאַתָּה הַקְרֵב אֵלֶיךְ אֶת אַהֲרֹן אָחִיךְ. אֶת - לִכְלֹל הַזְּרוֹעוֹת בַּגּוּף. וְאֶת בָּנָיו אִתּוֹ - אֵלֶּה כָּל אֵלּוּ הַמֶּרְכָּבוֹת וְעַמּוּדִים שֶׁלּוֹ. זְרוֹעַ שְׂמֹאל אֶצְלוֹ, שֶׁכָּתוּב (במדבר ג) קַח אֶת הַלְוִיִּם, שֶׁתִּמָּצֵא אוֹת ו' שֶׁכּוֹלֶלֶת הַכֹּל בְּהִתְפַּשְּׁטוּת אַחַת לִהְיוֹת אֶחָד.</p>\n<p>וְעַל זֶה נִמְצָא הַיִּחוּד בָּזֶה, יָמִין וּשְׂמֹאל וְאֶמְצַע. הַכֹּל הוּא כְאֶחָד. וְעַל זֶה נַעֲשֵׂית הִתְפַּשְּׁטוּת אַחַת, וְנִקְרָא אֶחָד, וְלֹא תִמְצָא חוּץ מֵהִתְפַּשְּׁטוּת אַחַת בִּלְבַד. וְזֶהוּ אֶחָד.</p>\n<p>אוֹת ה' אַחֲרוֹנָה נַעֲשֵׂית גּוּף אֶחָד בְּזוֹ הַנְּקֻדָּה הָאֶמְצָעִית. וְנִכְנֶסֶת בָּהּ אוֹת ו', וְנִמְצֵאת אוֹת ו' בֵּין שְׁתֵּי נְקֻדּוֹת, אַחַת לְמַעְלָה וְאַחַת לְמַטָּה. וְאָז מִתְאַחֵד הָעוֹלָם הָעֶלְיוֹן בָּעוֹלָם הַתַּחְתּוֹן, וְהוּא אֶחָד. וּבֵאַרְנוּהָ. בָּא רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא וְנָשְׁקוּ יָדָיו. בָּכָה רַבִּי אַבָּא וְאָמַר, אוֹי לָעוֹלָם כַּאֲשֶׁר יֵאָסֵף הַשֶּׁמֶשׁ וְיֵחָשֵׁךְ הָעוֹלָם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, הַיְרֵכַיִם שֶׁלְּמַטָּה בְּסוֹד אוֹת ו', מִנַּיִן לָנוּ שֶׁנִּכְלְלוּ בְּאוֹת זוֹ? אָמַר לוֹ, שֶׁכָּתוּב (מלאכי ג) זִכְרוּ תּוֹרַת מֹשֶׁה עַבְדִּי, וְלֹא כָתוּב נְבִיאִי, לְהַרְאוֹת שֶׁהַכֹּל נִכְלָל בְּסוֹד אוֹת ו'. וְאוֹת ו' נִקְרֵאת אֶחָד, וְהִיא אַחַת לְבַדָּהּ וְהִתְפַּשְּׁטוּת אַחַת, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522011791,"<p>וְאַתָּה הַקְרֵב אֵלֶיךְ וְגוֹ' (שמות כח). אָמַר רַבִּי שִׁמְעוֹן, לֹא שִׁמֵּשׁ מֹשֶׁה (השמש) (שהוא שמש) בַּלְּבָנָה עַד שֶׁנִּכְלַל בְּכָל הַצְּדָדִים בְּסוֹד אוֹת ו', כְּמוֹ שֶׁבֵּאַרְנוּ. בֹּא וּרְאֵה מַה כָּתוּב, מִתּוֹךְ בְּנֵי יִשְׂרָאֵל לְכַהֲנוֹ לִי. לְכַהֵן לִי לֹא נֶאֱמַר, אֶלָּא לְכַהֲנוֹ לִי, לַשִּׁמּוּשׁ שֶׁלּוֹ, לַשִּׁמּוּשׁ שֶׁל אוֹת זוֹ, לַשִּׁמּוּשׁ שֶׁלּוֹ וַדַּאי. זוֹ אוֹת ה', לְהַעֲלוֹת וּלְשַׁמֵּשׁ ו' בְּה', לִהְיוֹת הַכֹּל אֶחָד. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁנִּכְנְסוּ וְיָצְאוּ וְיוֹדְעִים בְּסוֹד הַדְּרָכִים שֶׁל הַתּוֹרָה לָלֶכֶת בְּדֶרֶךְ אֱמֶת.</p>\n<p>מִתּוֹךָ בְּנֵי יִשְׂרָאֵל. לָמָּה מִתּוֹךְ בְּנֵי יִשְׂרָאֵל? אֶלָּא הַכֹּל לֹא נִקְרָא לִהְיוֹת אֶחָד כְּמוֹ שֶׁצָּרִיךְ, אֶלָּא מִתּוֹךְ בְּנֵי יִשְׂרָאֵל. שֶׁהֲרֵי בְּנֵי יִשְׂרָאֵל קַיָּמִים לְמַטָּה, לִפְתֹּחַ דְּרָכִים וּלְהָאִיר שְׁבִילִים וּלְהַדְלִיק נֵרוֹת, וּלְקָרֵב הַכֹּל מִמַּטָּה לְמַעְלָה לִהְיוֹת הַכֹּל אֶחָד, וּמִפְּנֵי כָּךְ כָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' וְגוֹ'.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הַכֹּל הוּא קָרוֹב לְמִי שֶׁיּוֹדֵעַ לְיַחֵד הַיִּחוּד וְלַעֲבֹד לַאֲדוֹנוֹ, שֶׁהֲרֵי בִּזְמַן שֶׁנִּמְצָא קָרְבָּן כְּמוֹ שֶׁצָּרִיךְ, אָז מִתְקָרֵב הַכֹּל כְּאֶחָד, (הדרגות כלן כאחת) וְהֶאָרַת הַפָּנִים נִמְצֵאת בָּעוֹלָם בְּבֵית הַמִּקְדָּשׁ, וְנִכְנָע וְנִסְתָּר הַצַּד הָאַחֵר, וְשׁוֹלֵט הַצַּד שֶׁל הַקְּדֻשָּׁה בְּאוֹר וְשִׂמְחָה. וְכַאֲשֶׁר הַקָּרְבָּן לֹא נִמְצָא כְּמוֹ שֶׁצָּרִיךְ, אוֹ שֶׁהַיִּחוּד לֹא הָיָה כְּמוֹ שֶׁצָּרִיךְ, אָז הַפָּנִים עֲצוּבוֹת, וְאוֹר לֹא נִמְצָא, וּמִתְכַּסָּה הַלְּבָנָה, וְשׁוֹלֵט הַצַּד הָאַחֵר בָּעוֹלָם (שלא נחרב בית המקדש אלא מפני וכו'), מִפְּנֵי שֶׁאֵין מִי שֶׁיּוֹדֵעַ לְיַחֵד הַשֵּׁם הַקָּדוֹשׁ כְּמוֹ שֶׁצָּרִיךְ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא נִסָּה אֶת אִיּוֹב וְלֹא בָא עִמּוֹ בְנִסָּיוֹן כַּנִּסָּיוֹן שֶׁל שְׁאָר הַצַּדִּיקִים, שֶׁהֲרֵי לֹא כָתוּב בּוֹ וְהָאֱלֹהִים נִסָּה אֶת אִיּוֹב, כְּמוֹ שֶׁכָּתוּב בְּאַבְרָהָם (בראשית כב) !! וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. שֶׁהוּא בְיָדָיו הִקְרִיב אֶת בְּנוֹ יְחִידוֹ אֵלָיו. וְאִיּוֹב לֹא נָתַן לוֹ וְלֹא מָסַר לוֹ כְלוּם, וְלֹא נֶאֱמַר לוֹ. אֲבָל נִמְסַר בְּיַד הַמְקַטְרֵג בְּדִין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהוּא עוֹרֵר אֶת הַמְקַטְרֵג עָלָיו מַה שֶּׁהוּא לֹא רָצָה. שֶׁהֲרֵי בְּכָל זְמַן בָּא הַמְקַטְרֵג הַהוּא לְעוֹרֵר עַל בְּנֵי אָדָם, וְכָאן הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵר אוֹתוֹ עָלָיו, שֶׁכָּתוּב (איוב א) הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב. אֲבָל סוֹד עָמֹק הוּא.</p>"],[9522011792,"<p>פָּתַח וְאָמַר, (בראשית ד) וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה מִנְחָה לַה'. וַיְהִי מִקֵּץ יָמִים, סוֹד הוּא. מִקֵּץ יָמִים וְלֹא מִקֵּץ יָמִין. דָּחָה לְקֵץ הַיָּמִין, וְקֵרַב לְקֵץ הַיָּמִים. וּכְבָר פֵּרַשְׁנוּ, שֶׁכָּתוּב (דניאל יב) וְאַתָּה לֵךְ לַקֵּץ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָנִיֵּאל, וְאַתָּה לֵךְ לַקֵּץ. אָמַר לוֹ, לְאֵיזֶה קֵץ? לְקֵץ הַיָּמִים אוֹ לְקֵץ הַיָּמִין? עַד שֶׁאָמַר לוֹ, לְקֵץ הַיָּמִין.</p>\n<p>וְעַל זֶה פָּחַד דָּוִד, שֶׁכָּתוּב (תהלים לט) הוֹדִיעֵנִי ה' קִצִּי. אוֹ לְקֵץ הַיָּמִים, אוֹ לְקֵץ הַיָּמִין. וְכָאן מַה כָּתוּב? וַיְהִי מִקֵּץ יָמִים, וְלֹא מִקֵּץ יָמִין. וּמִפְּנֵי כֵן לֹא הִתְקַבֵּל קָרְבָּנוֹ, שֶׁהֲרֵי מֵהַצַּד הָאַחֵר הָיָה הַכֹּל.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, (בראשית ד) וְהֶבֶל הֵבִיא גַם הוּא. מַהוּ גַם הוּא? לְרַבּוֹת הַכֹּל זֶה בְזֶה. הַקָּרְבָּן כֻּלּוֹ וְהָעִקָּר שֶׁלּוֹ הָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְנָתַן מֵחֶלְקוֹ לַצַּד הָאַחֵר, כְּמוֹ שֶׁנֶּאֱמַר וּמֵחֶלְבֵיהֶן. וְקַיִן, הָעִקָּר עָשָׂה מִקֵּץ יָמִים, וְנָתַן חֵלֶק לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה נִדְחָה הוּא וְקָרְבָּנוֹ.</p>\n<p>בְּאִיּוֹב מַה כָּתוּב? (איוב א) וְהָלְכוּ בָנָיו וְעָשׂוּ מִשְׁתֶּה וְגוֹ'. וְכָתוּב וַיְהִי כִּי הִקִּיפוּ יְמֵי הַמִּשְׁתֶּה. וְכָתוּב וְשָׁלְחוּ וְקָרְאוּ לִשְׁלֹשֶׁת אַחְיֹתֵיהֶם לֶאֱכֹל וְלִשְׁתּוֹת עִמָּהֶם. שֶׁזֶּהוּ הָעִקָּר לַצַּד הָאַחֵר. וְאַחַר כָּךְ הִקְרִיב עוֹלוֹת, וְעוֹלָה הוּא זָכָר, וְלֹא נְקֵבָה, וְעוֹלָה לְמַעְלָה, וְהַקָּרְבָּן לֹא הִקְרִיב לִכְלֹל אוֹתוֹ כְּמוֹ שֶׁצָּרִיךְ.</p>"],[9522011793,"<p>וּבֹא רְאֵה, אִם הָיָה נוֹתֵן חֵלֶק לְכֻלָּם, הַמְקַטְרֵג לֹא הָיָה יָכוֹל לוֹ לְבַסּוֹף. וְאִם תֹּאמַר, מַדּוּעַ הֵרַע לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא, מִפְּנֵי שֶׁגָּרַם לְכַסּוֹת הָאוֹר וּלְהַעְלִימוֹ, וְהוּא לֹא הִקְרִיב קָרְבָּן אַחֵר לָזוּן בּוֹ אֲחֵרִים, אֶלָּא עוֹלָה, שֶׁעוֹלָה לְמַעְלָה, וְעַל זֶה כָּתוּב, כָּכָה יַעֲשֶׂה אִיּוֹב כָּל הַיָּמִים. שֶׁאִלּוּ הַצַּד הָאַחֵר הָיָה נִזּוֹן בְּחֶלְקוֹ, הָיָה עוֹבֵר מֵעַל הַמִּקְדָּשׁ וּמִסְתַּלֵּק מִמֶּנּוּ, וְצַד הַקְּדֻשָּׁה הָיָה עוֹלֶה לְמַעְלָה לְמַעְלָה.</p>\n<p>אֲבָל הוּא לֹא רָצָה שֶׁיֵּהָנוּ אֲחֵרִים מִקָּרְבָּנוֹ, וְהֵסִיר עַצְמוֹ מִמֶּנּוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (איובא) וְסָר מֵרָע. וְעַל זֶה הִקְרִיב תָּמִיד עוֹלָה, שֶׁהֲרֵי עוֹלָה לֹא נֶהֱנֶה מִמֶּנָּה הַצַּד הָאַחֵר לְעוֹלָם. וּמִפְּנֵי כֵן, כָּל מַה שֶׁנָּטַל לְבַסּוֹף, מִמֶּנּוּ נָטַל. וְעַל זֶה אִיּוֹב גָּרַם לְכַסּוֹת בְּעָרְלָה עַל בְּרִית הַקִּיּוּם, שֶׁלֹּא הָיָה מִסְתַּלֵּק מִמֶּנּוּ. וּמִפְּנֵי כֵן הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵר אֶת הַמְקַטְרֵג הַהוּא, שֶׁכָּתוּב הֲשַׂמְתָּ לִבְּךְ עַל עַבְדִּי אִיּוֹב.</p>\n<p>בֹּא וּרְאֵה, כַּאֲשֶׁר רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְאַחֵד בָּהֶם בְּיִשְׂרָאֵל בְּמִצְרַיִם, לֹא עָמְדָה לָהֶם הַשָּׁעָה, מִפְּנֵי שֶׁהָעָרְלָה מְכַסָּה הָאוֹר עַד זְמַן שֶׁהַמְקַטְרֵג הַהוּא הָיָה לוֹקֵחַ אֶת שֶׁלּוֹ מֵאִיּוֹב, וְעַל זֶה צִוָּה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לֶאֱכֹל אֶת אוֹתוֹ פֶסַח בְּחִפָּזוֹן, עַד שֶׁהַצַּד הָאַחֵר הַהוּא הִתְעַסֵּק בּוֹ בְּאִיּוֹב, וְצִוָּה לְהַעֲבִיר עָרְלָה מֵהֶם, וְאָז הִתְאַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיִשְׂרָאֵל, וְהַצַּד הָאַחֵר נִפְרַד מִן הַקְּדֻשָּׁה, וְהִתְעַסֵּק בּוֹ בְּאִיּוֹב וְלָקַח מִשֶּׁלּוֹ, וְאָז (שמות יב) פֶּסַח הוּא לַה', וַדַּאי. שֶׁעַד כָּאן לֹא הָיָה פֶּסַח לַה'. אַשְׁרֵי אֵלֶּה שֶׁיּוֹדְעִים וּמְיַחֲדִים יִחוּד קוֹנָם כְּמוֹ שֶׁצָּרִיךְ.</p>\n<p>כָּתוּב (שם לד) אֱלֹהֵי מַסֵּכָה לֹא תַעֲשֶׂה לָּךְ, וְכָתוּב אַחֲרָיו אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. מַה (עושה) זֶּה אֵצֶל זֶה? אֶלָּא כָּךְ פֵּרְשׁוּהָ, מִי שֶׁאוֹכֵל חָמֵץ בְּפֶסַח (כאלו עובד כוכבים ומזלות לעבד להם, שכן הסוד כך הוא שחמץ בפסח) כְּמִי שֶׁעוֹבֵד לְכוֹכָבִים וּמַזָּלוֹת הוּא.</p>\n<p>בֹּא וּרְאֵה, כַּאֲשֶׁר יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, יָצְאוּ מֵרָשׁוּת שֶׁלָּהֶם, מֵרָשׁוּת אַחֶרֶת, מֵהָרָשׁוּת הַהִיא שֶׁנִּקְרֵאת חָמֵץ, לֶחֶם רַע. וְעַל זֶה נִקְרָאִים כּוֹכָבִים וּמַזָּלוֹת כָּךְ, וְזֶהוּ סוֹד שֶׁל יֵצֶר הָרָע, עֲבוֹדָה זָרָה, שֶׁנִּקְרֵאת גַּם כָּךְ - שְׂאוֹר. וְזֶהוּ יֵצֶר הָרָע, שֶׁכָּךְ הוּא יֵצֶר הָרָע בַּבֶּן אָדָם כִּשְׂאוֹר שֶׁבָּעִסָּה, שֶׁנִּכְנָס בְּמֵעָיו שֶׁל אָדָם מְעַט מְעַט, וּלְבַסּוֹף מִתְרַבֶּה בוֹ עַד שֶׁכָּל הַגּוּף מְעֹרָב בּוֹ. וְזֶהוּ כּוֹכָבִים וּמַזָּלוֹת. וְעַל זֶה כָּתוּב, (תהלים פא) לֹא יִהְיֶה בְךְ אֵל זָר. אֵל זָר וַדַּאי.</p>"],[9522011794,"<p>אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. רַבִּי יְהוּדָה פָּתַח, (ישעיה ב) חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ כִּי בַמֶּה נֶחְשָׁב הוּא. פָּסוּק זֶה פֵּרְשׁוּהוּ, אֲבָל מַה זֶּה חִדְלוּ לָכֶם מִן הָאָדָם? וְכִי מַזְהִיר לוֹ לָאָדָם לְהִמָּנַע מִשְּׁאָר בְּנֵי אָדָם אֲפִלּוּ הֵם גַּם כֵּן מִמֶּנּוּ יִמָּצְאוּ בְנֵי אָדָם שֶׁלֹּא יִתְקָרְבוּ אֵלּוּ בְאֵלּוּ לְעוֹלָמִים? אֶלָּא זֶה פֵּרְשׁוּהוּ בְּמִי שֶׁמַּשְׁכִּים לְפֶתַח חֲבֵרוֹ לְהָבִיא לוֹ שָׁלוֹם.</p>\n<p>וַאֲנַחְנוּ בֵּאַרְנוּ אוֹתוֹ בְפָסוּק אַחֵר, שֶׁכָּתוּב (משלי כז) מְבָרֵךְ רֵעֵהוּ בְּקוֹל גָּדוֹל בַּבֹּקֶר הַשְׁכֵּים קְלָלָה תֵחָשֶׁב לוֹ. וְאַף עַל פִּי שֶׁהַכֹּל טוֹב, אֲבָל מַה זֶּה חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ? כָּאן צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם וּמַזְהִיר אוֹתוֹ לְהִשָּׁמֵר מֵאֵלּוּ בְּנֵי אָדָם שֶׁנָּטוּ דַרְכָּם מִדֶּרֶךְ טוֹב לְדֶרֶךְ רַע, וּמְטַמְּאִים נַפְשָׁם בַּטֻּמְאָה הַהִיא הָאַחֶרֶת.</p>\n<p>שֶׁהֲרֵי, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם, עָשָׂה אוֹתוֹ בִּדְמוּת עֶלְיוֹנָה, וְנָפַח בּוֹ רוּחַ (נשמה) קְדוֹשָׁה, שֶׁכְּלוּלָה בְשָׁלֹשׁ, כְּמוֹ שֶׁפֵּרַשְׁנוּ, שֶׁיֵּשׁ בּוֹ נֶפֶשׁ רוּחַ וּנְשָׁמָה, וְעֶלְיוֹן מֵהַכֹּל הִיא הַנְּשָׁמָה, שֶׁהִיא כֹּחַ עֶלְיוֹן לָדַעַת וְלִשְׁמֹר צִוּוּיֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִם הַנְּשָׁמָה הַהִיא הַקְּדוֹשָׁה מַעֲלָה אוֹתָהּ בַּעֲבוֹדָה אַחֶרֶת, זֶה הוּא שֶׁמְּטַמֵּא אוֹתָהּ, וְיוֹצֵא מֵעֲבוֹדַת קוֹנוֹ. מִפְּנֵי שֶׁשְּׁלֹשָׁה כֹחוֹת אֵלּוּ, כֻּלָּם אֶחָד, נֶפֶשׁ רוּחַ וּנְשָׁמָה מִשְׁתַּתְּפִים כְּאֶחָד, וְהָיוּ אֶחָד, וְהַכֹּל כְּדֻגְמַת הַסּוֹד הָעֶלְיוֹן. (ועל זה נאמר (שם יג) הולך את חכמים וגו').</p>\n<p>וְאִם רָאִינוּ לְזֶה הָאָדָם שֶׁהָיוּ בוֹ אֵלֶּה הַמַּדְרֵגוֹת כֻּלָּן, עַד שֶׁלֹּא עוֹמְדִים בִּקְבִיעוּת לְדַעַת מִי שֶׁהוּא, בַּמֶּה יִתְוַדַּע (שלא) לְהִתְקָרֵב הָאָדָם אֵלָיו אוֹ לְהִתְרַחֵק מִמֶּנּוּ. (בן אדם שיש בו מדרגות אלו כלם ועומדים קימים, זהו אדם שלם, עבד נאמן לאדונו, וצריך להשתתף בו ולהתחבר בו ללמד דרכים ממגו. ובמה יודע בן אדם לדעת מי הוא להתקרב אליו או להתרחק ממגו, ') בְּרֻגְזוֹ מַמָּשׁ יֵדַע לוֹ הָאָדָם וְיִוָּדַע מִי הוּא. אִם הַנְּשָׁמָה הַהִיא הַקְּדוֹשָׁה שׁוֹמֵר בִּשְׁעַת רֻגְזוֹ (בא עליה) שֶׁלֹּא יַעֲקֹר אוֹתָהּ מִמְּקוֹמָהּ, שֶׁאָז יָבא תַחְתֶּיהָ אוֹתוֹ אֵל זָר - זֶהוּ בֶּן אָדָם כְּמוֹ שֶׁצָּרִיךְ, זֶהוּ עֶבֶד שֶׁל אֲדוֹנוֹ, זֶהוּ גֶבֶר שָׁלֵם.</p>\n<p>וְאִם הָאָדָם הַהוּא לֹא שָׁמַר לָהּ וְהוּא עָקַר הַקְּדֻשָּׁה הַזּוֹ הָעֶלְיוֹנָה מִמְּקוֹמָהּ לִשְׁכֹּן בְּתוֹכָהּ הַצַּד הָאַחֵר - וַדַּאי זֶהוּ אָדָם שֶׁמּוֹרֵד בְּרַבּוֹ, וְאָסוּר לְהִתְקָרֵב אֵלָיו וּלְהִתְחַבֵּר עִמּוֹ, וְזֶהוּ (איוב יח) טֹרֵף נַפְשׁוֹ בְּאַפּוֹ. הוּא טוֹרֵף וְעוֹקֵר נַפְשׁוֹ בְּסִבַּת רֻגְזוֹ, וּמוֹשִׁיב בְּתוֹכָהּ אֵל זָר. וְעַל זֶה כָּתוּב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה הַהִיא טוֹרֵף אוֹתָהּ וּמְטַמֵּא אוֹתָהּ מִשּׁוּם אַפּוֹ. אֲשֶׁר נְשָׁמָה הֶחֱלִיף בְּאַפּוֹ. כִּי בַמֶּה נֶחְשָׁב הוּא - עֲבוֹדָה זָרָה נֶחְשָׁב אוֹתוֹ בֶּן אָדָם.</p>\n<p>וּמִי שֶׁמִּתְחַבֵּר עִמּוֹ וּמִי שֶׁמְּדַבֵּר עִמּוֹ, כְּמִי שֶׁמִּתְחַבֵּר בְּכוֹכָבִים וּמַזָּלוֹת מַמָּשׁ. מָה הַטַּעַם? מִשּׁוּם שֶׁכּוֹכָבִים וּמַזָּלוֹת מַמָּשׁ שׁוֹרִים בְּתוֹכוֹ. וְלֹא עוֹד, אֶלָּא שֶׁעוֹקֵר קְדֻשָּׁה עֶלְיוֹנָה מִמְּקוֹמָהּ, וּמַשְׁכִּין בִּמְקוֹמָהּ עֲבוֹדָה זָרָה אֵל זָר. מָה אֵל זָר כָּתוּב בּוֹ (ויקרא יט) אַל תִּפְנוּ אֶל הָאֱלִילִים - כְּדֻגְמַת זֶה אָסוּר לְהִסְתַּכֵּל בְּפָנָיו.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי רֹגֶז שֶׁל חֲכָמִים - רֹגֶז שֶׁל הַחֲכָמִים טוֹב הוּא לְכָל הַצְּדָדִים, שֶׁהֲרֵי לָמַדְנוּ שֶׁהַתּוֹרָה הִיא אֵשׁ, וְהַתּוֹרָה הִיא מַרְתִּיחָה אוֹתוֹ, שֶׁכָּתוּב (ירמיה כג) הֲלוֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. רֹגֶז שֶׁל חֲכָמִים בְּדִבְרֵי תוֹרָה. רֹגֶז שֶׁל חֲכָמִים לָתֵת כָּבוֹד לַתּוֹרָה, וְהַכֹּל לַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא הָיָה, לְכָךְ נֶאֱמַר (דברים ד) כִּי ה' אֱלֹהֶיךְ אֵשׁ אֹכְלָה הוּא אֵל קַנָּא.</p>\n<p>אֲבָל אִם בִּדְבָרִים אֲחֵרִים, לֹא עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא זֶה, לְפִי שֶׁבְּכָל הַחֲטָאִים שֶׁעוֹשֶׂה הָאָדָם, הִיא לֹא עֲבוֹדָה זָרָה מַמָּשׁ כְּמוֹ זֶה, וְאָסוּר לְהִתְקָרֵב בְּקִרְבָתוֹ שֶׁל זֶה. וְאִם תֹּאמַר, זֶה לְפִי שָׁעָה הָיָה, שֶׁעָבַר וְאַחַר כָּךְ חָזַר - לֹא כָּךְ. שֶׁכֵּיוָן שֶׁעָקַר הַקְּדֻשָּׁה שֶׁל נַפְשׁוֹ מִמֶּנּוּ וּמִמְּקוֹמוֹ, וְאוֹתוֹ אֵל זָר מְקַפֵּחַ הַמָּקוֹם הַהוּא, מִתְחַזֵּק בּוֹ וְלֹא עוֹזֵב אוֹתוֹ, חוּץ מִכַּאֲשֶׁר נִטְהָר הָאָדָם מִכֹּל וָכֹל וְעוֹקֵר אוֹתוֹ לְעוֹלָמִים, וְאַחַר כָּךְ מִשְׁתַּדֵּל לְהִתְקַדֵּשׁ וּלְהַמְשִׁיךְ קְדֻשָּׁה עָלָיו, וְאָז הַלְוַאי וְיִתְקַדֵּשׁ. אָמַר לוֹ רַבִּי יוֹסִי, מִתְקַדֵּשׁ מַמָּשׁ. (למה, ' והרי נדחה והתקדש).</p>\n<p>אָמַר לוֹ, בֹּא וּרְאֵה, בְּשָׁעָה שֶׁהוּא עוֹקֵר קְדֻשָּׁה שֶׁל נַפְשׁוֹ, וְשׁוֹכֵן בִּמְקוֹמוֹ הָאֵל זָר הַהוּא שֶׁנִּקְרָא טָמֵא, נִטְמָא הָאָדָם וּמְטַמֵּא לְמִי שֶׁקָּרֵב עִמּוֹ, וְהַקְּדֻשָּׁה הַהִיא בּוֹרַחַת מִמֶּנּוּ. וְכֵיוָן שֶׁבּוֹרַחַת מִמֶּנּוּ פַּעַם אַחַת, כָּל מַה שֶּׁיַּעֲשֶׂה הָאָדָם עוֹד, לֹא תָשׁוּב לִמְקוֹמָהּ.</p>\n<p>אָמַר לוֹ, אִם כֵּן, כַּמָּה טְמֵאִים יֵשׁ שֶׁמְּטַהֲרִים? אָמַר לוֹ, שׁוֹנָה טֻמְאָה אַחֶרֶת שֶׁלֹּא יְכוֹלָה לַעֲשׂוֹת יוֹתֵר. אֲבָל זֶה מְשֻׁנֶּה מִכֻּלָּם, שֶׁכָּל גּוּפוֹ נִטְמָא מִבִּפְנִים וּמִבַּחוּץ, וְנַפְשׁוֹ וְכֻלּוֹ נִטְמָא. וּשְׁאָר טֻמְאוֹת שֶׁבָּעוֹלָם לֹא נִטְמָא אֶלָּא גוּפוֹ מִבַּחוּץ בִּלְבַד, וְלָכֵן כָּתוּב חִדְלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ, שֶׁמַּחֲלִיף קְדֻשַּׁת רַבּוֹ מִשּׁוּם אַפּוֹ, שֶׁזּוֹהִי טֻמְאָה שֶׁמְּטַמְּאָה הַכֹּל. כִּי בַמֶּה נֶחְשָׁב הוּא - בָּמָה שֶׁל עֲבוֹדָה זָרָה וַדַּאי נֶחְשָׁב הוּא.</p>\n<p>בֹּא וּרְאֵה, זֶהוּ רֹגֶז שֶׁל עֲבוֹדָה זָרָה, הַצַּד הָאַחֵר, כְּמוֹ שֶׁאָמַרְנוּ, שֶׁרוֹצֶה הָאָדָם לְהִשָּׁמֵר מִמֶּנּוּ וּלְהִפָּרֵד מֵעָלָיו, וְעַל זֶה כָּתוּב (שמות לד) אֱלֹהֵי מַסֵּכָה לֹא תַעֲשֶׂה לָּךְ. לָּךְ - כְּדֵי לְהָרַע לְךְ. וְכָתוּב אַחֲרָיו, אֶת חַג הַמַּצּוֹת תִּשְׁמֹר. תִּשְׁמֹר - זֶה צַד הַקְּדֻשָּׁה שֶׁצָּרִיךְ הָאָדָם לִשְׁמֹר אוֹתוֹ וְלֹא יַחֲלִיף אוֹתוֹ בִּגְלַל הַצַּד הָאַחֵר. וְאִם יַחֲלִיף אוֹתוֹ, הֲרֵי הוּא טָמֵא, וּמְטַמֵּא לְכָל מִי שֶׁמִּתְקָרֵב אֵלָיו.</p>"],[9522011795,"<p>אֶת חַג הַמַּצּוֹת תִּשְׁמֹר - זֶהוּ מָקוֹם שֶׁנִּקְרָא שָׁמוֹר. וּמִפְּנֵי כֵן כָּתוּב אֶת חַג הַמַּצּוֹת תִּשְׁמֹר, שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת כַּאֲשֶׁר צִוִּיתִךְ. שִׁבְעַת יָמִים אֵלּוּ אֵינָם כְּשִׁבְעַת הַיָּמִים שֶׁל סֻכּוֹת, שֶׁהֵם עֶלְיוֹנִים, וְאֵלּוּ תַחְתּוֹנִים. וְעַל זֶה, בְּאֵלּוּ הַלֵּל גָּמוּר, וּבְאֵלּוּ אֵין הַלֵּל גָּמוּר, וְעַל שֶׁהֵם לְמַטָּה - שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת. מַצּת כָּתוּב חָסֵר בְּלִי אוֹת ו', שֶׁטֶּרֶם שׁוֹרִים אֵלּוּ הַיָּמִים הָעֶלְיוֹנִים, סוֹד אוֹת ו'.</p>\n<p>וְאִם תֹּאמַר, כֵּיוָן שֶׁסּוֹד זֶה שֶׁל חַג הַמַּצּוֹת הִתְקַדֵּשׁ, מַדּוּעַ יוֹרֵד? שֶׁהֲרֵי לָמַדְנוּ, מַעֲלִים בַּקֹּדֶשׁ וְלֹא מוֹרִידִים. וּמַדּוּעַ יוֹרֶדֶת לְמַטָּה בְּאֵלּוּ הַיָּמִים הַתַּחְתּוֹנִים?</p>\n<p>בֹּא וּרְאֵה, כָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ וְגוֹ'. מִי שֶׁיְּכַפֵּר צָרִיךְ (לכפר) עַל עַצְמוֹ תְחִלָּה, וְאַחַר כָּךְ עַל בֵּיתוֹ. כְּדֻגְמַת זֶה, מַדְרֵגָה זוֹ מַתְחִילָה לְהִתְקַדֵּשׁ וְלָצֵאת בִּקְדֻשָּׁה לְכַפֵּר עָלָיו, וְכֵיוָן שֶׁהוּא הִתְקַדֵּשׁ, צָרִיךְ לְכַפֵּר עַל בֵּיתוֹ וּלְקַדֵּשׁ אוֹתָם, וְעַל זֶה יוֹרֵד לְמַטָּה לְקַדֵּשׁ בֵּיתוֹ. וּבַמֶּה מְקַדֵּשׁ לָהֶם? בְּיִשְׂרָאֵל שֶׁלְּמַטָּה, בְּחֶשְׁבּוֹן הָעֹמֶר. וְכֵיוָן שֶׁאֵלּוּ מִתְקַדְּשִׁים, צְרִיכִים לְהַעֲלוֹת אוֹתָהּ לְמַעְלָה. שֶׁהֲרֵי כַּאֲשֶׁר בֵּית הַמַּלְכָּה מִתְקַדֵּשׁ, אָז עוֹלֶה לְמַעְלָה, לְהִתְקַשֵּׁר בְּאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים לְמַעְלָה.</p>\n<p>וְעַל זֶה אָנוּ עוֹשִׂים חֶשְׁבּוֹן בַּעֲמִידָה עַל הָרַגְלַיִם, לְפִי שֶׁאֵלּוּ הַיָּמִים, יָמִים עֶלְיוֹנִים הֵם. וְכֵן בְּכָל זְמַן שֶׁנִּכְנָס אָדָם לְאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים, בֵּין בִּתְפִלָּה בֵּין בְּשֶׁבַח, צָרִיךְ לַעֲמֹד עַל רַגְלָיו, הַיְרֵכַיִם וְהַגּוּף כְּאֶחָד שָׁם. יְרֵכַיִם וְגוּף לַעֲמִידָה כְּזָכָר שֶׁעוֹמֵד בְּכֹחוֹ, וְלֹא כִנְקֵבָה שֶׁדַּרְכָּהּ לָשֶׁבֶת. וְעוֹד, מִשּׁוּם שֶׁבַח שֶׁל הָעוֹלָם הָעֶלְיוֹן.</p>\n<p>וּמִשּׁוּם שֶׁהוּא סוֹד הַזָּכָר, נָשִׁים פְּטוּרוֹת מֵחֶשְׁבּוֹן זֶה, וְלֹא מְחֻיָּבִים לִמְנוֹת, רַק הַזְּכָרִים, לְהִתְקַשֵּׁר כָּל אֶחָד כְּמוֹ שֶׁצָּרִיךְ. כְּעֵין זֶה, (שמות כג) יֵרָאֶה כָל זְכוּרְךְ. זְכָרִים וְלֹא נָשִׁים. מִשּׁוּם שֶׁסּוֹד הַבְּרִית בְּזָכָר הוּא, וְלֹא בִנְקֵבָה, וּמִשּׁוּם שֶׁעֲמִידָה סוֹד לְמַעְלָה, נָשִׁים לֹא מִתְחַיְּבוֹת.</p>\n<p>וְסוֹד לָמַדְנוּ כָאן, שֶׁבְּכָל שִׁבְעַת הַיָּמִים מֵאֵלּוּ הַיָּמִים הָעֶלְיוֹנִים נוֹטֶלֶת הַקְּדֻשָּׁה יוֹם אֶחָד (ומתאחד) שֶׁל אֵלּוּ הַתַּחְתּוֹנִים, וְזוֹ הַתַּחְתּוֹנָה נִקְרֵאת שָׁבוּעַ, שֶׁמִּתְקַדֵּשׁ בְּשִׁבְעָה יָמִים עֶלְיוֹנִים. וְכֵן בְּכָל שִׁבְעָה וְשִׁבְעָה מֵאֵלּוּ חֲמִשִּׁים יָמִים, עַד וְלֹא עַד בִּכְלָל. וְכַאֲשֶׁר נִמְצָאִים אַרְבָּעִים וְתִשְׁעָה יָמִים עֶלְיוֹנִים, נִמְצְאוּ לְמַטָּה שֶׁבַע יָמִים שֶׁמִּתְקַדְּשִׁים בָּהֶם, וְכָל אֶחָד נִקְרָא שָׁבוּעַ שֶׁעוֹלֶה בְאֵלּוּ הַשֶּׁבַע. וְעַל זֶה כָּתוּב (ויקרא כג) שֶׁבַע שַׁבָּתוֹת תְּמִימֹת תִּהְיֶינָה. מִשּׁוּם שֶׁאֵלּוּ נְקֵבוֹת, תָּפַס הַכָּתוּב לָשׁוֹן שֶׁל נְקֵבוֹת.</p>\n<p>וְכַאֲשֶׁר הִתְקַדְּשׁוּ בָהֶם וְהַבַּיִת נִתְקַן לְהִתְחַבֵּר אִשָּׁה בְּבַעְלָהּ, אָז נִקְרָא חַג הַשָּׁבוּעוֹת, מֵאוֹתָן נְקֵבוֹת שֶׁשּׁוֹרִים עֲלֵיהֶן אוֹתָם יָמִים עֶלְיוֹנִים שֶׁנִּתְקַדְּשׁוּ בָּהֶם. וּמִשּׁוּם זֶה כָּתוּב בְּשָׁבֻעֹתֵיכֶם, הֵם שֶׁלָּכֶם, וְלֹא כָתוּב בְּשָׁבוּעוֹת, לְפִי שֶׁכָּךְ גַּם מִתְקַדְּשִׁים יִשְׂרָאֵל לְמַטָּה עִמָּהֶם.</p>\n<p>וְעַל זֶה כַּאֲשֶׁר מַגִּיעִים לְתִשְׁעָה וְאַרְבָּעִים יָמִים, הַיּוֹם הַהוּא הָעֶלְיוֹן שֶׁעֲלֵיהֶם, שֶׁהוּא יוֹם הַחֲמִשִּׁים שֶׁשּׁוֹלֵט עַל תִּשְׁעָה וְאַרְבָּעִים יָמִים, סוֹד כְּלָלוּת הַתּוֹרָה, בְּתֵשַׁע וְאַרְבָּעִים פָּנִים, וְאָז הַיּוֹם הָעֶלְיוֹן הַהוּא, הַיּוֹם הַחֲמִשִּׁים, בְּהִתְעוֹרְרוּת שֶׁל מַטָּה, מוֹצִיא תוֹרָה כְּלוּלָה בְּתֵשַׁע וְאַרְבָּעִים פָּנִים.</p>"],[9522011796,"<p>רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים פד) גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ אֲשֶׁר שָׁתָה אֶפְרֹחֶיהָ אֶת מִזְבְּחוֹתֶיךְ וְגוֹ'. גַּם צִפּוֹר מָצְאָה בַיִת, אֵלּוּ צִפֳּרֵי שָׁמַיִם שֶׁמֵּהֶם שָׂמִים מְדוֹרֵיהֶם בַּחוּץ, וּמֵהֶם שָׂמִים מְדוֹרֵיהֶם בַּבַּיִת, כְּמוֹ הַדְּרוֹר, שֶׁהוּא עוֹף שֶׁעוֹשֶׂה דִירָתוֹ בְּבַיִת שֶׁל כָּל אָדָם וְלֹא מְפַחֵד. מַדּוּעַ? מִפְּנֵי שֶׁכֻּלָּם קוֹרְאִים לוֹ דְרוֹר. מַהוּ דְרוֹר? חֵרוּת, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) וּקְרָאתֶם דְּרוֹר, וְתַרְגּוּמוֹ חֵרוּת. וְזֶהוּ צִפּוֹר דְּרוֹר. שֶׁהֲרֵי מִיּוֹם שֶׁעוֹשֶׂה קֵן בְּבַיִת, מוֹצִיא בָנִים, מְגוּרָיו בַּבַּיִת חֲמִשִּׁים יָמִים, וּלְאַחֲרֵיהֶם נִפְרָדִים אֵלּוּ מֵאֵלּוּ, וְזֶהוּ עוֹף שֶׁנִּקְרָא דְרוֹר - חֵרוּת.</p>\n<p>בֹּא וּרְאֵה מַה כָּתוּב, וְקִדַּשְׁתֶּם אֵת שְׁנַת הַחֲמִשִּׁים שָׁנָה וּקְרָאתֶם דְּרוֹר בָּאָרֶץ. מִכָּאן יוֹצֵאת חֵרוּת לְכֻלָּם. וּמִפְּנֵי שֶׁיּוֹצֵאת מִמֶּנּוּ חֵרוּת, תּוֹרָה שֶׁיּוֹצֵאת מִמֶּנּוּ נִקְרֵאת חֵרוּת. וְעַל זֶה כָּתוּב (שמות לב) חָרוּת עַל הַלֻּחֹת, אַל תִּקְרָא חָרוּת אֶלָּא חֵרוּת, וְזוֹ הַתּוֹרָה שֶׁנִּקְרֵאת חֵרוּת, שֶׁהֲרֵי מַה שֶּׁמּוֹצִיא יוֹם זֶה הָעֶלְיוֹן נִקְרָא חֵרוּת, וְהוּא חֵרוּת שֶׁל הַכֹּל. וְזֶה הַיּוֹם הוּא חֵרוּת עֶלְיוֹנָה, מִשּׁוּם שֶׁיֵּשׁ חֵרוּת תַּחְתּוֹנָה וְחֵרוּת עֶלְיוֹנָה. הֵ\"א עֶלְיוֹנָה, הֵ\"א תַחְתּוֹנָה. חֵרוּת עֶלְיוֹנָה. וְחֵרוּת תַּחְתּוֹנָה שְׁמִטָּה וְיוֹבֵל כְּאֶחָד הֵם.</p>"],[9522011797,"<p>שְׁנֵי מִינֵי לֶחֶם אָכְלוּ יִשְׂרָאֵל: אֶחָד כַּאֲשֶׁר יָצְאוּ מִמִּצְרַיִם, אָכְלוּ מַצָּה, לֶחֶם עֹנִי. וְאֶחָד בַּמִּדְבָּר, לֶחֶם מִן הַשָּׁמַיִם (אחד בפסח ואחד בשבועות), שֶׁכָּתוּב (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. וְעַל זֶה קָרְבָּן שֶׁל יוֹם זֶה הוּא לֶחֶם. וְעַל לֶחֶם מַקְרִיבִים כָּל שְׁאָר קָרְבָּנוֹת, שֶׁהַלֶּחֶם הוּא הָעִקָּר, שֶׁכָּתוּב (ויקרא כג) וְהִקְרַבְתֶּם עַל הַלֶּחֶם שִׁבְעַת כְּבָשִׂים וְגוֹ', וְכָתוּב (שם) מִמּוֹשְׁבתֵיכֶם תָּבִיאוּ לֶחֶם תְּנוּפָה וְגוֹ'. שֶׁזֶּהוּ לֶחֶם שֶׁחָכְמוּ בוֹ יִשְׂרָאֵל, חָכְמָה עֶלְיוֹנָה שֶׁל הַתּוֹרָה, וְנִכְנְסוּ בִדְרָכֶיהָ.</p>\n<p>עַתָּה יֵשׁ לָנוּ לְהִתְבּוֹנֵן, בְּפֶסַח יָצְאוּ יִשְׂרָאֵל מִלֶּחֶם שֶׁנִּקְרָא חָמֵץ. כָּתוּב (שמות יג) וְלֹא יֵרָאֶה לְךְ חָמֵץ, וְכָתוּב (שם יב) כִּי כָל אֹכֵל מַחְמֶצֶת. מָה הַטַּעַם? בִּשְׁבִיל כָּבוֹד שֶׁל הַלֶּחֶם הַהוּא הַנִּקְרָא מַצָּה. וְעַכְשָׁו שֶׁזָּכוּ יִשְׂרָאֵל לְלֶחֶם עֶלְיוֹן יוֹתֵר, לֹא רָאוּי הָיָה שֶׁיִּתְבַּטֵּל הֶחָמֵץ וְלֹא יֵרָאֶה כְלָל. וּמַדּוּעַ קָרְבָּן זֶה הָיָה חָמֵץ? שֶׁכָּתוּב סֹלֶת תִּהְיֶינָה חָמֵץ תֵּאָפֶינָה. וְעוֹד, שֶׁעַתָּה בְּיוֹם זֶה מִתְבַּטֵּל יֵצֶר הָרָע, וְהַתּוֹרָה שֶׁנִּקְרֵאת חֵרוּת נִמְצֵאת.</p>\n<p>אֶלָּא, לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן יְחִידִי, וְנֶחֱלָה. יוֹם אֶחָד הָיָה מִתְאַוֶּה לֶאֱכֹל. אָמְרוּ, יֹאכַל בֶּן הַמֶּלֶךְ (מאכל של רפואה) רְפוּאָה זוֹ, וְעַד שֶׁיֹּאכַל אוֹתָהּ, לֹא יִמָּצֵא מַאֲכָל וּמָזוֹן אַחֵר בַּבַּיִת. עָשׂוּ כֵן. כֵּיוָן שֶׁאָכַל הָרְפוּאָה הַהִיא, אָמַר, מִכָּאן וָהָלְאָה יֹאכַל כָּל מַה שֶּׁהוּא מִתְאַוֶּה וְלֹא יָכוֹל לְהַזִּיק לוֹ.</p>\n<p>כָּךָ כַּאֲשֶׁר יָצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, לֹא הָיוּ יוֹדְעִים עִקָּר וְסוֹד שֶׁל הָאֱמוּנָה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִטְעֲמוּ יִשְׂרָאֵל רְפוּאָה, וְעַד שֶׁיֹּאכְלוּ רְפוּאָה זוֹ, לֹא יֵרָאֶה לָהֶם מַאֲכָל אַחֵר. כֵּיוָן שֶׁאָכְלוּ מַצָּה, שֶׁהִיא רְפוּאָה לַעֲלוֹת וְלָדַעַת בְּסוֹד הָאֱמוּנָה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: מִכָּאן וָהָלְאָה רָאוּי לָהֶם חָמֵץ וְיֹאכְלוּ אוֹתוֹ, שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהַזִּיק לָהֶם. וְכָל שֶׁכֵּן שֶׁבְּיוֹם הַשָּׁבוּעוֹת שֶׁנִּמְצָא לֶחֶם עֶלְיוֹן, שֶׁהוּא רְפוּאָה לַכֹּל.</p>\n<p>וְעַל זֶה מַקְרִיבִים חָמֵץ לְהִשָּׂרֵף עַל הַמִּזְבֵּחַ. וּמַקְרִיבִים שְׁתֵּי לֶחֶם אֲחֵרִים כְּאֶחָד. וְחָמֵץ נִשְׂרָף בְּאֵשׁ הַמִּזְבֵּחַ, וְלֹא יָכוֹל לִשְׁלֹט וּלְהַזִּיק לָהֶם לְיִשְׂרָאֵל. וּמִשּׁוּם זֶה יִשְׂרָאֵל קְדוֹשִׁים נִדְבָּקִים בּוֹ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא, בָּרְפוּאָה שֶׁל הַתּוֹרָה בְּיוֹם זֶה. וְאִם הָיוּ שׁוֹמְרִים יִשְׂרָאֵל שְׁנֵי צְדָדִים שֶׁל לֶחֶם אֵלּוּ, לֹא הָיוּ עוֹלִים בְּדִין לְעוֹלָם.</p>\n<p>בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין, (בכל יום) שֶׁאֵין הוּא, אֶלָּא לְאֵלּוּ שֶׁלֹּא לָקְחוּ מַאֲכָל שֶׁל הָרְפוּאָה, וְעָזְבוּ אֶת מַאֲכַל הַתּוֹרָה מִשּׁוּם מַאֲכָל אַחֵר שֶׁהוּא חָמֵץ. כִּי בְּיוֹם זֶה שֶׁל רֹאשׁ הַשָּׁנָה הֶחָמֵץ הַהוּא עוֹלֶה, וּמְקַטְרֵג עַל הָאָדָם וּמַלְשִׁין עָלָיו, וְהוּא עוֹמֵד בְּיוֹם זֶה מְקַטְרֵג עַל הָעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל כֻּלָּם וְדָן אֶת הָעוֹלָם.</p>\n<p>וּמִסִּבָּה זוֹ, כַּאֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַתּוֹרָה לְיִשְׂרָאֵל, הִטְעִים לָהֶם מֵהַלֶּחֶם הָעֶלְיוֹן הַהוּא שֶׁל הַמָּקוֹם הַהוּא, וּמִתּוֹךְ הַלֶּחֶם הַהוּא הָיוּ יוֹדְעִים וּמִסְתַּכְּלִים בְּסוֹדוֹת הַתּוֹרָה לָלֶכֶת בְּדֶרֶךְ יָשָׁר, וַהֲרֵי בֵּאֲרוּ הַדְּבָרִים אֵלּוּ הַחֲבֵרִים בְּסוֹדוֹת (אלו שאנחנו אומרים) אֵלּוּ כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>רַבִּי שִׁמְעוֹן וְרַבִּי אֶלְעָזָר בְּנוֹ הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהָיוּ הוֹלְכִים עִמָּהֶם רַבִּי אַבָּא וְרַבִּי יוֹסֵי. עַד שֶׁהָיוּ הוֹלְכִים, פָּגְשׁוּ בְזָקֵן אֶחָד, וְהָיָה אוֹחֵז בְּיָדוֹ תִּינוֹק אֶחָד. הֵרִים עֵינָיו רַבִּי שִׁמְעוֹן וְרָאָה אוֹתוֹ. אָמַר לוֹ לְרַבִּי אַבָּא, וַדַּאי דְּבָרִים חֲדָשִׁים יֵשׁ לָנוּ אֵצֶל הַזָּקֵן.</p>\n<p>כַּאֲשֶׁר הִגִּיעוּ אֵלָיו, אָמַר רַבִּי שִׁמְעוֹן, בְּמַשָּׂא הַקָּשׁוּר בְּגַבְּךְ אַתָּה בָּא? מִי אַתָּה? אָמַר לוֹ, יְהוּדִי אָנִי. אָמַר, דְּבָרִים חֲדָשִׁים וַדַּאי בְּיוֹם זֶה אֶצְלְךְ. אָמַר לוֹ, לְהֵיכָן הוּא דַּרְכְּךְ? אָמַר לוֹ, דִּירָתִי הָיְתָה בְּאֵלּוּ פּוֹרְשֵׁי הַמִּדְבָּר, שֶׁהָיִיתִי מִשְׁתַּדֵּל בַּתּוֹרָה, וְעַתָּה בָּאתִי לְיִשּׁוּב לָשֶׁבֶת בְּצֵל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָמִים אֵלּוּ שֶׁל הַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה.</p>\n<p>שָׂמַח רַבִּי שִׁמְעוֹן, אָמַר, נֵשֵׁב, בְּוַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח אוֹתְךְ אֵלֵינוּ. אָמַר לוֹ, חַיְּיִךְ שֶׁנִּשְׁמַע דָּבָר מִפִּיךְ, מֵאֵלּוּ הַדְּבָרִים הַחֲדָשִׁים עַתִּיקִים שֶׁנְּטַעְתֶּם שָׁם בַּמִּדְבָּר מֵחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה, וּמַדּוּעַ נִפְרַדְתֶּם עַתָּה מֵהַמִּדְבָּר לָבא לְיִשּׁוּב? אָמַר לוֹ אוֹתוֹ הַזָּקֵן, בִּשְׁאֵלָה זוֹ יָדַעְתִּי שֶׁחָכְמָה אֶצְלְךְ וּדְבָרֶיךְ מַגִּיעִים לִרְקִיעֵי הַחָכְמָה (נוטים לתקיעת החכמה).</p>"],[9522011798,"<p>פָּתַח הַזָּקֵן הַהוּא וְאָמַר, (דברים א) וּבַמִּדְבָּר אֲשֶׁר רָאִיתָ אֲשֶׁר נְשָׂאֲךְ ה' אֱלֹהֶיךְ כַּאֲשֶׁר יִשָּׂא אִישׁ אֶת בְּנוֹ וְגוֹ'. פָּסוּק זֶה כָּךְ הָיָה צָרִיךְ לוֹמַר, וּבַמִּדְבָּר אֲשֶׁר נְשָׂאֲךְ. מַהוּ רָאִיתָ? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא הִנְהִיג אֶת יִשְׂרָאֵל בַּמִּדְבָּר, מִדְבָּר חָזָק, כְּמוֹ שֶׁכָּתוּב (דברים ח) נָחָשׁ שָׂרָף וְעַקְרָב וְגוֹ'. וּמִדְבָּר שֶׁהוּא חָזָק מִשְּׁאָר מִדְבָּרִיּוֹת בָּעוֹלָם. מָה הַטַּעַם?</p>\n<p>מִשּׁוּם שֶׁבַּשָּׁעָה הַהִיא שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם וְנִשְׁלְמוּ לְשִׁשִּׁים רִבּוֹא, הִתְחַזְּקָה הַמַּלְכוּת הַקְּדוֹשָׁה וְעָלְתָה עַל הַכֹּל, וְהֵאִירָה הַלְּבָנָה, וְאָז נִכְנְעָה מַלְכוּת הָרְשָׁעָה, הַצַּד הָאַחֵר, וְהוֹצִיא אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לָלֶכֶת בְּמִדְבָּר חָזָק, שֶׁהוּא מְקוֹם וְשִׁלְטוֹן סָמָאֵ\"ל הָרָשָׁע, שֶׁהוּא שֶׁלּוֹ מַמָּשׁ, כְּדֵי לִשְׁבֹּר חָזְקוֹ וְכֹחוֹ וּלְכַתֵּת רֹאשׁוֹ (ולהורידאותו) וּלְהַכְנִיעַ אוֹתוֹ שֶׁלֹּא יִשְׁלֹט. וְאִלְמָלֵא חָטְאוּ יִשְׂרָאֵל, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירוֹ מִן הָעוֹלָם, וְעַל זֶה הֶעֱבִיר אוֹתָם בְּנַחֲלָתוֹ וְגוֹרָלוֹ וְחֶלְקוֹ מַמָּשׁ.</p>\n<p>בִּגְלַל שֶׁחָטְאוּ בְּכַמָּה פְעָמִים, נָשַׁךְ אוֹתָם הַנָּחָשׁ, וְאָז הִתְקַיֵּם (בראשית ג) הוּא יְשׁוּפְךְ רֹאשׁ וְגוֹ'. יִשְׂרָאֵל הִכּוּ רֹאשׁוֹ בַתְּחִלָּה וְלֹא יָדְעוּ לְהִשָּׁמֵר מִמֶּנּוּ, וּלְבַסּוֹף הוּא הִכָּה בָאַחֲרוֹנָה, וְנָפְלוּ כֻלָּם בַּמִּדְבָּר, וְהִתְקַיֵּם וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. וְאַרְבָּעִים שָׁנָה לָקוּ מִמֶּנּוּ, כְּנֶגֶד אַרְבָּעִים מַלְקוֹת שֶׁל בֵּית דִּין.</p>\n<p>וְעַל זֶה כָּתוּב אֲשֶׁר רָאִיתָ, בְּעֵינֵיהֶם הָיוּ רוֹאִים אֶת אֲדוֹן הַמִּדְבָּר הוֹלֵךְ קָשׁוּר לִפְנֵיהֶם, וְלָקְחוּ נַחֲלָתוֹ וְגוֹרָלוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמות טו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם, וְאֵלֶּה הֵם (דבריםח) נָחָשׁ שָׂרָף וְעַקְרָב. וַאֲנַחְנוּ גַּם כָּךְ נִפְרַדְנוּ מֵהַיִּשּׁוּב לַמִּדְבָּר הֶחָזָק לְעַיֵּן שָׁם בַּתּוֹרָה, כְּדֵי לְהַכְנִיעַ אֶת הַצַּד הָאַחֵר.</p>\n<p>וְעוֹד, שֶׁלֹּא מִתְיַשְּׁבִים דִּבְרֵי תוֹרָה אֶלָּא שָׁם, שֶׁאֵין אוֹר אֶלָּא אוֹתוֹ הַיּוֹצֵא מִתּוֹךְ הַחֹשֶׁךְ. שֶׁכַּאֲשֶׁר נִכְנָע צַד זֶה, מִתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּמִתְכַּבֵּד בִּכְבוֹדוֹ, וְאֵין עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא מִתּוֹךְ הַחֹשֶׁךְ, וְאֵין הַטּוֹב אֶלָּא מִתּוֹךְ הָרָע. וְכַאֲשֶׁר נִכְנָס בֶּן אָדָם בְּדֶרֶךְ רָעָה וְעָזַב אוֹתָהּ, אָז מִתְעַלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ, וְעַל זֶה שְׁלֵמוּת הַכֹּל - טוֹב וָרַע כְּאֶחָד, וְלַעֲלוֹת אַחַר כָּךְ בְּטוֹב, וְאֵין טוֹב אֶלָּא הַהוּא שֶׁיָּצָא מִתּוֹךְ הָרָע. וּבְטוֹב זֶה מִתְעַלֶּה כְבוֹדוֹ, וְזוֹהִי עֲבוֹדָה שְׁלֵמָה.</p>\n<p>וַאֲנַחְנוּ עַד עַכְשָׁו יוֹשְׁבִים שָׁם כָּל יְמֵי הַשָּׁנָה בִּכְדֵי לְהַכְנִיעַ בַּמִּדְבָּר לַצַּד הָאַחֵר. עַכְשָׁו שֶׁהִגִּיעַ זְמַן עֲבוֹדַת הַקֹּדֶשׁ שֶׁל צַד הַקְּדֻשָּׁה, חָזַרְנוּ לְיִשּׁוּב, שֶׁשָּׁם הִיא עֲבוֹדָתוֹ. וְעוֹד, שֶׁעַתָּה בְּרֹאשׁ הַשָּׁנָה הִגִּיעַ זְמַן שֶׁל הַנָּחָשׁ הַהוּא לִתְבֹּעַ דִּין מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁם הוּא שׁוֹלֵט, וּמִפְּנֵי כָּךְ יָצָאנוּ מִשָּׁם וּבָאנוּ לְיִשּׁוּב.</p>"],[9522011799,"<p>פָּתַח הַזָּקֵן הַהוּא וְאָמַר, (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. עַכְשָׁו הוּא הַזְּמַן לְהִתְעוֹרֵר הַדִּין הָעֶלְיוֹן הֶחָזָק, וְכַאֲשֶׁר הוּא מִתְעוֹרֵר, הַצַּד הָאַחֵר מִתְחַזֵּק כְּנֶגְדּוֹ. וּמִכֵּיוָן שֶׁהוּא מִתְחַזֵּק, עוֹלֶה וּמְכַסֶּה לַלְּבָנָה, שֶׁלֹּא מְאִירָה אוֹר, וּמִתְמַלֵּאת מִצַּד הַדִּין. אָז כָּל הָעוֹלָם הוּא בְדִין, עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכָרוֹז קוֹרֵא בְכָל הָרְקִיעִים: הַתְקִינוּ כִסֵּא שֶׁל דִּין לַאֲדוֹן הַכֹּל, שֶׁהוּא רוֹצֶה לָדוּן.</p>\n<p>וְסוֹד כָּאן, וְהֵאִיר לָנוּ בַמִּדְבָּר, מַדּוּעַ מִתְעוֹרֵר דִּין עֶלְיוֹן בְּיוֹם זֶה. אֶלָּא כָּל סוֹדוֹת וְכָל הַקְּדֻשּׁוֹת הַנִּכְבָּדוֹת, כֻּלָּם תְּלוּיִים בַּשְּׁבִיעִי. וְהַשְּׁבִיעִי הַהוּא הָעֶלְיוֹן, עוֹלָם הָעֶלְיוֹן, שֶׁנִּקְרָא עוֹלָם הַבָּא. מִמֶּנּוּ מְאִירִים כָּל הַנֵּרוֹת וְכָל הַקְּדֻשּׁוֹת וְכָל הַבְּרָכוֹת. וְכַאֲשֶׁר מַגִּיעַ הַזְּמַן לְחַדֵּשׁ הַבְּרָכוֹת וְהַקְּדֻשּׁוֹת לְהָאִיר, צָרִיךְ לְהַשְׁגִּיחַ בְּכָל תִּקּוּן שֶׁל הָעוֹלָמוֹת כֻּלָּם, וְכָל הַתִּקּוּנִים הָהֵם לְקַיֵּם כֻּלָּם עוֹלִים מִתּוֹךְ הַתַּחְתּוֹנִים, אִם הֵם כְּשֵׁרִים. וְאִם אֵינָם כְּשֵׁרִים, אָז עוֹמֶדֶת, (דבר) שֶׁלֹּא מְאִירָה, עַד שֶׁנִּפְרָדִים הַחַיָּבִים מִתּוֹךְ הַזַּכָּאִים, אָז מִתְעוֹרֵר הַדִּין.</p>\n<p>וּמֵהַדִּין הַהוּא מִתְחַזֵּק הַצַּד הָאַחֵר, וְנִמְצָא מְקַטְרֵג, כְּדֵי שֶׁיִּנָּתְנוּ לוֹ אֵלּוּ הַחַיָּבִים, מִפְּנֵי שֶׁכָּתוּב (איוב כח) וּלְכָל תַּכְלִית הוּא חוֹקֵר. וּמְכַסֶּה לַלְּבָנָה. מַדּוּעַ (לא מוסרת אותם ביד המקטרג) ? מִפְּנֵי שֶׁאֵין רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבֵּד אֶת מַעֲשֵׂי יָדָיו.</p>\n<p>וְהַצַד הָאַחֵר הַהוּא עוֹמֵד כִּקְלִפָּה חֲזָקָה, שֶׁאֵינָהּ יְכוֹלָה לְהִשָּׁבֵר חוּץ בְּאוֹתָהּ עֵצָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְיִשְׂרָאֵל, שֶׁכָּתוּב תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ. כְּדֵי לִשְׁבֹּר הַכִּסּוּי הַהוּא שֶׁמְּכַסֶּה אֶת הַלְּבָנָה, וְלֹא מְאִירָה.</p>\n<p>וְכַאֲשֶׁר מִתְעוֹרְרִים יִשְׂרָאֵל לְמַטָּה בַּשּׁוֹפָר, הַקּוֹל הַהוּא שֶׁיּוֹצֵא מֵהַשּׁוֹפָר מַכֶּה בָאֲוִיר, וּבוֹקֵעַ אֶת הָרְקִיעִים, עַד שֶׁעוֹלֶה לְגַבֵּי הַסֶּלַע הַהוּא הֶחָזָק, (הצד האחר) שֶׁמְּכַסֶּה לַלְּבָנָה, מַשְׁגִּיחַ וּמוֹצֵא הִתְעוֹרְרוּת הָרַחֲמִים, אָז הַהוּא שֶׁעוֹלֶה וְעוֹמֵד לְמַעְלָה, מִתְעַרְבֵּב. אָז הַקּוֹל הַהוּא עוֹמֵד וּמַעֲבִיר הַדִּין הַהוּא, וְכֵיוָן שֶׁלְּמַטָּה מִתְעוֹרְרִים הָרַחֲמִים, כָּךְ גַּם לְמַעְלָה מִתְעוֹרֵר שׁוֹפָר אַחֵר עֶלְיוֹן וּמוֹצִיא קוֹל שֶׁהוּא רַחֲמִים, וּמִתְעַרְבְּבִים קוֹל בְּקוֹל, רַחֲמִים בְּרַחֲמִים, וּבַהִתְעוֹרְרוּת שֶׁל לְמַטָּה מִתְעוֹרֵר כָּךְ גַּם לְמַעְלָה.</p>\n<p>וְאִם תֹּאמַר, אֵיךְ יָכוֹל קוֹל שֶׁל לְמַטָּה אוֹ הִתְעוֹרְרוּת שֶׁל לְמַטָּה לְהִתְעוֹרֵר - כְּמוֹ כֵן? בֹּא וּרְאֵה, עוֹלָם הַתַּחְתּוֹן עוֹמֵד לְקַבֵּל תָּמִיד, וְהוּא נִקְרָא אֶבֶן טוֹבָה, וְעוֹלָם הָעֶלְיוֹן לֹא נוֹתֵן לוֹ, אֶלָּא כְּמוֹ שֶׁהוּא עוֹמֵד. אִם הוּא קַיָּם בְּהֶאָרַת פָּנִים מִלְּמַטָּה, כְּמוֹ כֵן מְאִירִים לוֹ מִלְמַעְלָה. וְאִם הוּא עוֹמֵד בְּעַצְבוּת, נוֹתְנִים לוֹ דִּין כְּנֶגְדּוֹ.</p>\n<p>כְּמוֹ זֶה, (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה. שִׂמְחָה שֶׁל בֶּן אָדָם מוֹשֵׁךְ לְעַצְמוֹ שִׂמְחָה אַחֶרֶת עֶלְיוֹנָה. כָּךְ גַּם זֶה הָעוֹלָם הַתַּחְתּוֹן - כְּמוֹ שֶׁהִיא מִתְעוֹרֶרֶת, כָּךְ מוֹשֵׁךְ מִלְמַעְלָה. מִשּׁוּם כָּךְ מַקְדִּימִים יִשְׂרָאֵל וּמְעוֹרְרִים בַּשּׁוֹפָר קוֹל שֶׁהוּא (סוד של רחמים) כָּלוּל בְּאֵשׁ וּמַיִם וְרוּחַ, וְנַעֲשֶׂה אֶחָד, וְעוֹלֶה לְמַעְלָה, וּמַכֶּה בָּאֶבֶן הַטּוֹבָה הַזּוֹ, וְנִצְבָּע בִּגְוָנִים אֵלּוּ שֶׁל הַקּוֹל הַזֶּה, וְאָז כְּמוֹ שֶׁמִּתְרָאֶה, כָּךְ מוֹשֵׁךְ מִלְמַעְלָה.</p>\n<p>וְכֵיוָן שֶׁנִּתְקֶנֶת בְּקוֹל זֶה, רַחֲמִים יוֹצְאִים מִלְמַעְלָה וְשׁוֹרִים עָלֶיהָ, וְנִכְלֶלֶת בְּרַחֲמִים מִלְּמַטָּה וּמִלְמַעְלָה. וְאָז מִתְעַרְבֵּב הַצַּד הָאַחֵר, (מסתכל ורואה בהארת הפנים) וְנֶחֱלָשׁ כֹּחוֹ וְלֹא יָכוֹל לְקַטְרֵג. וְהָאֶבֶן הַטּוֹבָה הַזּוֹ קַיֶּמֶת בְּהֶאָרַת הַפָּנִים מִכָּל הַצְּדָדִים - בְּהֶאָרָה שֶׁל לְמַטָּה וּבְהֶאָרָה שֶׁל לְמַעְלָה.</p>\n<p>מָתַי עוֹמֶדֶת בְּהֶאָרָה שֶׁל לְמַעְלָה? הֱיֵה אוֹמֵר בְּיוֹם הַכִּפּוּרִים. וּבְיוֹם הַכִּפּוּרִים מְאִירָה הָאֶבֶן הַטּוֹבָה הַהִיא בְּאוֹר שֶׁל לְמַעְלָה מִתּוֹךְ הָאוֹר שֶׁל הָעוֹלָם הַבָּא, (ומתערבב המקטרג ההוא), וְאָז מְתַקְּנִים יִשְׂרָאֵל לְמַטָּה שָׂעִיר אֶחָד, וְשׁוֹלְחִים לַמִּדְבָּר הַזֶּה הֶחָזָק שֶׁהוּא שׁוֹלֵט עָלָיו.</p>"],[9522011800,"<p>וְהַצַד הָאַחֵר הַהוּא הוּא נְקֻדָּה אֶמְצָעִית שֶׁל הָעוֹלָם הֶחָרֵב, מִשּׁוּם שֶׁכָּל חָרָבָה וּשְׁמָמָה (הוא ממגו, מהצד האחר ההוא השולט) מִמֶּנּוּ, הַצַּד הָאַחֵר הַהוּא שׁוֹלֵט עָלָיו, וּנְקֻדָּה הָאֶמְצָעִית שֶׁל כָּל הַיִּשּׁוּב, צַד הַקְּדֻשָּׁה הוּא. וְעַל זֶה עוֹמֶדֶת יְרוּשָׁלַיִם בְּאֶמְצַע כָּל הַיִּשּׁוּב שֶׁל הָעוֹלָם.</p>\n<p>בִּשְׁתֵּי נְקֻדּוֹת נִבְדֶּלֶת מַלְכוּת שָׁמַיִם, צַד הַקְּדֻשָּׁה - אַחַת שֶׁלָּהּ, וְאַחַת שֶׁל הָעוֹלָם הַבָּא. נְקֻדָּה עֶלְיוֹנָה נֶעְלֶמֶת, וְעַל זֶה קַיֶּמֶת בִּשְׁתֵּי נְקֻדּוֹת. נְקֻדָּה שֶׁלָּהּ עוֹמֶדֶת תַּחְתֶּיהָ, יְרוּשָׁלַיִם, אֶמְצַע שֶׁל כָּל הַיִּשּׁוּב. נְקֻדָּה שֶׁלּוֹקַחַת מֵאִמָּא עֶלְיוֹנָה וּסְתוּמָה, הִיא גַן עֵדֶן שֶׁל הָאָרֶץ, שֶׁעוֹמֶדֶת בָּאֶמְצָע שֶׁל כָּל הָעוֹלָם לְכָל הַצְּדָדִים, שֶׁל הֶחָרָבָה וְהַיִּשּׁוּב וְכָל צִדְדֵי הָעוֹלָם.</p>\n<p>וְעַל זֶה בְּאֶמְצַע גַּן עֵדֶן עוֹמֶדֶת נְקֻדָּה אַחַת עֶלְיוֹנָה נֶעְלֶמֶת וּסְתוּמָה שֶׁלֹּא נוֹדַעַת. וְעַמּוּד אֶחָד נָעוּץ מִלְּמַטָּה לְמַעְלָה תּוֹךְ הַנְּקֻדָּה הַהִיא, וּמִשָּׁם נוֹבְעִים מַיִם שֶׁנִּפְרָדִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. נִמְצְאוּ שָׁלֹשׁ נְקֻדּוֹת בָּעוֹלָם שֶׁעוֹמְדוֹת זוֹ עַל זוֹ, כְּדֻגְמַת שָׁלֹשׁ נְקֻדּוֹת שֶׁל הַתּוֹרָה.</p>"]]});
